// Build the message chain for one thread def, padding with filler replies
// (position-aware: growth happens on the side that preserves the requested
// early/mid/late placement) until the ChatML-rendered prompt reaches
// `def.target_tokens`, verified against the real tokenizer each step.
static std::vector<S2Msg> s2_build_thread(Tokenizer* tok, const std::string& task,
                                          const S2ThreadDef& def, const QMessy& seed,
                                          int& corr_idx_out, std::string& corr_old_out) {
    bool de = def.de;
    std::vector<S2Msg> msgs;
    S2Msg m0; m0.body = seed.document;
    for (auto& f : seed.fields) m0.fields.push_back({f.concept, f.value});
    msgs.push_back(m0);

    corr_old_out.clear();
    for (auto& f : seed.fields) if (f.concept == def.corr_concept) corr_old_out = f.value;
    if (corr_old_out.empty())
        throw std::runtime_error("SS2: corr_concept '" + def.corr_concept + "' not found in seed " + def.tag);

    int fi = 0;
    std::string prev_name = "the original sender";
    auto mk_filler = [&]() -> S2Msg {
        const char* txt = (de ? S2_FILLER_DE : S2_FILLER_EN)[fi % 8];
        std::string name = s2_qname(de, fi), date = s2_qdate(fi);
        S2Msg m;
        m.pre = "From: " + name + "\nDate: " + date + "\n\n" + (de ? "Hallo,\n\n" : "Hi,\n\n");
        m.body = txt;
        m.post = de ? "\n\nViele Grüße\n" + name + "\n" : "\n\nBest,\n" + name + "\n";
        m.quote_lead = de ? ("\nAm " + date + " schrieb " + prev_name + ":\n")
                          : ("\nOn " + date + ", " + prev_name + " wrote:\n");
        prev_name = name; fi++;
        return m;
    };
    auto mk_named = [&](const std::string& body, const std::string& concept,
                        const std::string& value) -> S2Msg {
        std::string name = s2_qname(de, fi), date = s2_qdate(fi);
        S2Msg m;
        m.pre = "From: " + name + "\nDate: " + date + "\n\n" + (de ? "Hallo,\n\n" : "Hi,\n\n");
        m.body = body;
        m.post = de ? "\n\nViele Grüße\n" + name + "\n" : "\n\nBest,\n" + name + "\n";
        m.quote_lead = de ? ("\nAm " + date + " schrieb " + prev_name + ":\n")
                          : ("\nOn " + date + ", " + prev_name + " wrote:\n");
        if (!concept.empty()) m.fields = {{concept, value}};
        prev_name = name; fi++;
        return m;
    };
    // Same envelope as mk_named, but for a restatement message that repeats
    // several NON-corrected field values at once (a recap or cross-reference
    // naturally names more than one figure). See S2Restate for why
    // def.corr_concept is never passed through here.
    auto mk_fields = [&](const std::string& body,
                         const std::vector<std::pair<std::string, std::string>>& fields) -> S2Msg {
        std::string name = s2_qname(de, fi), date = s2_qdate(fi);
        S2Msg m;
        m.pre = "From: " + name + "\nDate: " + date + "\n\n" + (de ? "Hallo,\n\n" : "Hi,\n\n");
        m.body = body;
        m.post = de ? "\n\nViele Grüße\n" + name + "\n" : "\n\nBest,\n" + name + "\n";
        m.quote_lead = de ? ("\nAm " + date + " schrieb " + prev_name + ":\n")
                          : ("\nOn " + date + ", " + prev_name + " wrote:\n");
        m.fields = fields;
        prev_name = name; fi++;
        return m;
    };
    // Insert every authored restatement tagged with `depth`, in def.restatements
    // order. Depths are relative to the correction reply, not absolute message
    // count, so a value's occurrences land at genuinely different distances
    // from the decode position across the 4 call sites below.
    auto add_restatements = [&](const char* depth) {
        for (auto& rs : def.restatements)
            if (rs.depth == depth) msgs.push_back(mk_fields(rs.body, rs.fields));
    };

    add_restatements("early");

    int pre_seed = def.position == "late" ? 6 : def.position == "mid" ? 3 : 1;
    int pre_seed_half = pre_seed / 2;
    for (int i = 0; i < pre_seed_half; ++i) msgs.push_back(mk_filler());
    add_restatements("mid");
    for (int i = pre_seed_half; i < pre_seed; ++i) msgs.push_back(mk_filler());

    add_restatements("pre_corr");
    msgs.push_back(mk_named(def.corr_body, def.corr_concept, def.corr_new));
    int corr_pos = (int)msgs.size() - 1;
    add_restatements("post_corr");

    if (def.has_distractor) {
        msgs.push_back(mk_filler());
        msgs.push_back(mk_named(def.distr_body, def.corr_concept, corr_old_out));
    }

    auto token_len = [&]() {
        S2Built b = s2_build(msgs);
        return (int)tok->encode(qdocs_chat_prompt(b.text, task)).size();
    };
    bool toggle = true;
    for (int guard = 0; guard < 300 && token_len() < def.target_tokens; ++guard) {
        S2Msg f = mk_filler();
        if (def.position == "late") { msgs.insert(msgs.begin() + corr_pos, f); corr_pos++; }
        else if (def.position == "early") { msgs.push_back(f); }
        else {
            if (toggle) { msgs.insert(msgs.begin() + corr_pos, f); corr_pos++; }
            else { msgs.push_back(f); }
            toggle = !toggle;
        }
    }
    corr_idx_out = corr_pos;
    return msgs;
}

static bool s2_bytes_to_toks(const std::vector<size_t>& cum, int n, size_t b0, size_t b1,
                             int& lo, int& hi) {
    lo = hi = -1;
    for (int k = 0; k < n; ++k) if (cum[k] < b1 && cum[k + 1] > b0) { if (lo < 0) lo = k; hi = k; }
    return lo >= 0;
}
static int s2_classify(const std::vector<std::pair<size_t, size_t>>& env, size_t pos) {
    for (size_t i = 0; i < env.size(); ++i)
        if (pos >= env[i].first && pos < env[i].second) return (int)i;
    return -1;
}

// TRIVIAL-RULE CONTROL — defends the citation result against the same
// failure class that killed the earlier image-tap probe (a head that looked
// like it tracked an object but was actually just favouring one side of the
// image). Threads quote history, so a scored value string can appear in
// several messages; if a head merely points at "the most recent copy" or
// "the first copy" of the string, it adds nothing over a plain string search
// and the citation result is an artifact, not evidence of retrieval. This
// finds every literal occurrence of a value in the prompt and classifies
// each by message index, so callers can compare the head's pick against
// R_last / R_first / R_near. Known limitation: literal substring match can
// false-positive on short values (e.g. "5" inside "15") — acceptable here
// because the scored fields (names, prices, order numbers, dates) are
// distinctive strings, not single digits.
static std::vector<std::pair<int, int>> s2_occurrences(
        const std::string& prompt, const std::vector<std::pair<size_t, size_t>>& env,
        const std::vector<size_t>& pcum, int P, const std::string& value) {
    std::vector<std::pair<int, int>> occ;   // {msg_idx, token_pos}, ascending position
    if (value.empty()) return occ;
    size_t p = 0;
    while (true) {
        size_t f = prompt.find(value, p);
        if (f == std::string::npos) break;
        int mi = s2_classify(env, f);
        int lo, hi;
        if (mi >= 0 && s2_bytes_to_toks(pcum, P, f, f + value.size(), lo, hi))
            occ.push_back({mi, lo});
        p = f + 1;
    }
    return occ;
}

// One row of the alarm-field control (item 4): what the head cited vs. what
// each trivial rule would have predicted, for the 8 correction instances.
// n is tiny here — print rows, not a rate.
struct S2TrivAlarmRow {
    std::string thread, concept;
    int head_msg = -1, r_last = -1, r_first = -1, r_near = -1;
};

// One scored field instance (the corrected field, one per thread).
struct S2AlarmRec {
    std::string thread, position; bool de, explicit_ph, has_distractor;
    int label = -1;           // 1 FRESH (emitted current), 0 STALE (emitted superseded), -1 excluded
    bool alarm = false;       // ORACLE arm — uses corpus ground truth (see below)
    bool alarm_srv = false;   // SERVEABLE arm — uses only what /v1/extract would have
    bool alarm_srv2 = false;  // SERVEABLE+ — same, plus the confirmation check (see below)
    int cited_msg = -1, current_msg = -1, latest_cited_msg = -1;
};

// ═══ Two alarms, deliberately ═════════════════════════════════════════════
// SS2 scored ONE predicate: "the cited message is superseded for this field",
// where `superseded` comes from field_spans — corpus ground truth listing which
// messages state a value for the concept. **A server cannot compute that.** At
// serve time /v1/extract has the document, the caller's message boundaries, the
// emitted value and the top-k citations; it does NOT know which other messages
// speak to the same key. Scoring only the oracle would validate a predicate the
// product can never run — the same class of defect as SS2's own L3H13_SLOT
// no-op override, caught before an hour of GPU rather than after.
//
// So both are scored on the same run:
//   ORACLE     (r.alarm)     — cited message ∈ superseded_msgs (ground truth).
//   SERVEABLE  (r.alarm_srv) — the field's citations span a LATER message than
//                              the one the emitted value was drawn from. Uses
//                              only shipped signals plus caller-declared message
//                              boundaries, so it is exactly what a v3 endpoint
//                              could raise. Its known weakness is that a
//                              citation landing in a later FILLER message counts
//                              — measuring that cost is the point.
// A gap between the two arms is the real cost of shipping the alarm.

static int run_ss2(ForwardPassBase* fp, ggml_backend_sched_t sched,
                   Tokenizer* tok, const ModelMetadata& meta,
                   const std::vector<int32_t>& attn_layers,
                   const std::vector<S2ThreadDef>& defs, const char* leg) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ %-3s — coverage-free thread stale-source alarm (long threads) ║\n", leg);
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");
    std::printf("citation tap: L%dH%d (slot %d)  [defaults 0/13 = Qwen3.6 L3H13; override via "
                "ATTN_FROZEN_SLOT/ATTN_FROZEN_HEAD]\n", (*g_attn_layers)[FROZEN_SLOT], FROZEN_HEAD, FROZEN_SLOT);

    const int TOL = 2;
    // NO GRAMMAR. The fixed KV grammar was REFUTED by measurement 2026-07-16 and
    // REMOVED from the product path in Stage 2 (docs/note-nogrammar-refutation.md);
    // the shipped lens decodes free in one prefill with a tolerant parse
    // (server_lens.h; http_server.cpp: "Builds NO grammar").
    // SS1 §5 recommended a grammar-constrained thread extractor — but SS1 is dated
    // 2026-07-12, FOUR DAYS BEFORE that refutation, so the recommendation is stale.
    // Measured cost of having followed it: the fixed-KV grammar bounds each pair's
    // SHAPE but not the NUMBER of pairs, so a looping model emits syntactically
    // valid infinite JSON (t_en1 invented ~20 nested key variants, never closed).
    // Free decode terminates on '}' — the stopping rule the grammar never had.
    static const std::vector<std::string> S2_KEYS = {
        "customer","product","quantity","unit_price","total",
        "order_date","delivery_date","order_number"};
    std::vector<int> tap(attn_layers.begin(), attn_layers.end());
    // Deliberately tighter than Leg C's "extract every fact" hint: Leg C's
    // single-email documents bound "every fact" naturally, but SS2's threads
    // carry many pages of realistic-but-irrelevant filler (logistics/admin
    // chatter) whose whole purpose is padding length, not being extracted.
    // A first run with Leg C's looser hint spiraled into a repetitive,
    // never-closing key explosion over that filler on long threads — a real,
    // disclosed finding (see docs/note-ss2-thread-alarm.md "What was NOT
    // done"), not a scoring bug, but avoided here by naming the exact ORDER
    // key set and explicitly excluding admin/courtesy content.
    const char* TASK = "\n\nThis is an email thread about ONE order, with possibly one or more "
        "corrections later in the thread, plus unrelated administrative/logistics/courtesy "
        "remarks mixed in. Extract ONLY the order's CURRENT field values (after applying any "
        "corrections) as a flat JSON object with exactly these keys, omitting any that never "
        "appear: customer, product, quantity, unit_price, total, order_date, delivery_date, "
        "order_number. Copy each value verbatim from the email it currently holds. Ignore all "
        "administrative, logistics, and courtesy remarks — do not create keys for them. Output "
        "ONLY the JSON object, nothing else.";

    auto corpus = qdocs_messy_corpus();
    auto find_seed = [&](const std::string& tag) -> const QMessy& {
        for (auto& d : corpus) if (d.tag == tag) return d;
        throw std::runtime_error("SS2: seed tag not found: " + tag);
    };

    struct CiteAcc { int n = 0, t1 = 0, t3 = 0; };
    CiteAcc cite_all;
    // RE-SCORE (2026-09-05). cite_all is STRICT: a hit requires the citation to
    // land in the field's designated message (msg 0 for uncorrected fields).
    // Once the corpus restates values truthfully in several later messages, that
    // label asserts a unique correct source where several equally true ones
    // exist — the head pointing at a confirmation instead of the original scores
    // as a miss. cite_any is PERMISSIVE: a hit if the citation lands in ANY
    // literal occurrence of the value. The strict/permissive GAP separates "the
    // head is inaccurate" from "our ground truth is wrong".
    CiteAcc cite_any;
    std::vector<S2AlarmRec> alarms;
    int excluded = 0, labeled_total = 0;

    // TRIVIAL-RULE CONTROL accumulator, across every scored value token in
    // every thread (see s2_occurrences above for what this defends against).
    struct TrivAgg { long ambiguous = 0, last_agree = 0, first_agree = 0, near_agree = 0; };
    TrivAgg triv;
    std::vector<S2TrivAlarmRow> triv_rows;   // the 8 alarm-field rows (item 4)

    for (auto& def : defs) {
        const QMessy& seed = find_seed(def.seed_tag);
        int corr_idx = -1; std::string corr_old;
        std::vector<S2Msg> msgs = s2_build_thread(tok, TASK, def, seed, corr_idx, corr_old);
        S2Built built = s2_build(msgs);
        std::string prompt = qdocs_chat_prompt(built.text, TASK);
        size_t base = prompt.find(built.text);
        if (base == std::string::npos)
            throw std::runtime_error("SS2: assembled thread text not found verbatim in its own "
                                     "ChatML prompt (thread " + def.tag + ") — cannot locate spans");

        FreeRun R = run_freegen(fp, sched, tok, meta, prompt, "", tap, 380);
        int actual_tokens = R.P;
        std::printf("\n[%s%s] msgs=%zu corr@%d/%zu (%.0f%%) pos=%s phrasing=%s distractor=%s "
                    "target=%d actual=%d tok\n  gen: %s\n",
                    def.tag.c_str(), def.de ? " DE" : "", msgs.size(), corr_idx, msgs.size() - 1,
                    100.0 * corr_idx / std::max<size_t>(1, msgs.size() - 1), def.position.c_str(),
                    def.explicit_ph ? "explicit" : "indirect", def.has_distractor ? "yes" : "no",
                    def.target_tokens, actual_tokens, R.gen_text.c_str());

        std::vector<size_t> pcum = cum_bytes(tok, R.prompt_tokens);
        // Tolerant parse of the free output — the shipped lens contract.
        auto gfs = parse_fields(tok, R, S2_KEYS);
        std::vector<size_t> gcum = cum_bytes(tok, R.gen_tokens);

        // message envelopes, absolute byte ranges in the prompt
        std::vector<std::pair<size_t, size_t>> env(msgs.size());
        std::map<std::string, std::vector<std::pair<int, std::pair<size_t, size_t>>>> field_spans;
        for (auto& sp : built.spans) {
            if (sp.tag == "__msg__") env[sp.msg_idx] = {base + sp.lo, base + sp.hi};
            else field_spans[sp.tag].push_back({sp.msg_idx, {base + sp.lo, base + sp.hi}});
        }

        // `cited_any` collects EVERY top-3 citation's message index over every
        // scored token of the value — the serveable arm's raw material.
        std::set<int> cited_any;
        auto score_field = [&](const std::string& concept, const std::string& emitted_value,
                               const std::vector<std::pair<size_t, size_t>>& target_spans) -> int {
            cited_any.clear();
            // returns the classified msg_idx of the top-1 citation on the LAST
            // scored gen-token (majority not needed for single/short values;
            // multi-token values use the final token, which is where the
            // value's identity is fully resolved).
            size_t gb = R.gen_text.find(emitted_value);
            if (gb == std::string::npos) return -2;   // normalized away
            size_t ge = gb + emitted_value.size();
            int last_cited = -1;
            // Full occurrence set O of this value across the prompt, computed
            // once per field-call (same value for every scored gen-token of
            // it) — see s2_occurrences for what this is for.
            auto occ = s2_occurrences(prompt, env, pcum, R.P, emitted_value);
            // Every literal occurrence, as byte spans — the permissive target.
            std::vector<std::pair<size_t, size_t>> any_spans;
            for (size_t q = 0; ; ) {
                size_t f = prompt.find(emitted_value, q);
                if (f == std::string::npos) break;
                any_spans.push_back({f, f + emitted_value.size()});
                q = f + 1;
            }
            for (int g = 0; g < (int)R.gen_tokens.size(); ++g) {
                if (!(gcum[g] < ge && gcum[g + 1] > gb)) continue;
                if (g < 1 || g - 1 >= (int)R.rows.size()) continue;
                int n_kv = R.n_kv_at_step[g - 1];
                auto tk = topk_head(R.rows[g - 1][L3H13_SLOT], FROZEN_HEAD, n_kv, 3);
                cite_all.n++;
                bool t1 = false, t3 = false;
                for (auto& [tlo, thi] : target_spans) {
                    int slo, shi;
                    if (!s2_bytes_to_toks(pcum, R.P, tlo, thi, slo, shi)) continue;
                    auto in = [&](int p) { return p >= slo - TOL && p <= shi + TOL; };
                    if (!tk.empty() && in(tk[0].first)) t1 = true;
                    for (auto& pr : tk) if (in(pr.first)) { t3 = true; break; }
                }
                if (t1) cite_all.t1++;
                if (t3) cite_all.t3++;
                bool a1 = false, a3 = false;
                for (auto& [tlo, thi] : any_spans) {
                    int slo, shi;
                    if (!s2_bytes_to_toks(pcum, R.P, tlo, thi, slo, shi)) continue;
                    auto ain = [&](int q) { return q >= slo - TOL && q <= shi + TOL; };
                    if (!tk.empty() && ain(tk[0].first)) a1 = true;
                    for (auto& pr : tk) if (ain(pr.first)) { a3 = true; break; }
                }
                cite_any.n++;
                if (a1) cite_any.t1++;
                if (a3) cite_any.t3++;
                // TRIVIAL-RULE CONTROL: only meaningful when the value is
                // genuinely ambiguous in the prompt (|O| >= 2). R_near is
                // computed generically (nearest occurrence by token distance
                // to n_kv) even though, by construction, decode always
                // happens strictly after the whole prompt here, which makes
                // R_near coincide with R_last — reported anyway for
                // completeness and stated explicitly in the summary so it is
                // not mistaken for an independent confirmation.
                if (occ.size() >= 2 && !tk.empty()) {
                    triv.ambiguous++;
                    int head_msg = s2_classify(env, pcum[tk[0].first]);
                    int r_last = occ.back().first, r_first = occ.front().first;
                    int r_near = r_first; int best_d = -1;
                    for (auto& o : occ) {
                        int d = std::abs(n_kv - o.second);
                        if (best_d < 0 || d < best_d) { best_d = d; r_near = o.first; }
                    }
                    if (head_msg == r_last) triv.last_agree++;
                    if (head_msg == r_first) triv.first_agree++;
                    if (head_msg == r_near) triv.near_agree++;
                }
                if (!tk.empty()) last_cited = s2_classify(env, pcum[tk[0].first]);
                for (auto& pr : tk) {
                    int mi = s2_classify(env, pcum[pr.first]);
                    if (mi >= 0) cited_any.insert(mi);
                }
            }
            return last_cited;
        };

        for (auto& f : seed.fields) {
            labeled_total++;
            if (f.concept == def.corr_concept) {
                // "superseded" = every OTHER message that stated a value for
                // this concept (msg0's original, plus the distractor if it
                // restates the old value too) — the alarm's ground-truth
                // predicate, independent of which value was actually emitted.
                std::vector<int> superseded_msgs;
                for (auto& [mi, span] : field_spans[f.concept]) if (mi != corr_idx) superseded_msgs.push_back(mi);

                // Which value did the model emit UNDER THIS KEY? Deliberately NOT a
                // whole-output substring search. That was a real false negative: on
                // t_en3 the model emitted the STALE "unit_price":"0.35 eur" while the
                // fresh 0.42 sat under an invented key, and because has_new is tested
                // first the run scored a genuinely stale emission as FRESH — silently
                // inverting the one error class this alarm exists to catch.
                std::string emitted_here;
                for (auto& gf : gfs) if (gf.name == f.concept) { emitted_here = gf.value; break; }
                bool has_new = !emitted_here.empty() &&
                               emitted_here.find(def.corr_new) != std::string::npos;
                bool has_old = !emitted_here.empty() &&
                               emitted_here.find(corr_old)    != std::string::npos;
                std::string emitted; int label; std::vector<std::pair<size_t, size_t>> target;
                if (has_new) {
                    emitted = def.corr_new; label = 1;
                    for (auto& [mi, span] : field_spans[f.concept]) if (mi == corr_idx) target.push_back(span);
                } else if (has_old) {
                    emitted = corr_old; label = 0;
                    for (auto& [mi, span] : field_spans[f.concept]) if (mi != corr_idx) target.push_back(span);
                } else { excluded++; continue; }
                int cited = score_field(f.concept, emitted, target);
                if (cited == -2) { excluded++; continue; }
                S2AlarmRec r; r.thread = def.tag; r.position = def.position; r.de = def.de;
                r.explicit_ph = def.explicit_ph; r.has_distractor = def.has_distractor;
                r.label = label; r.cited_msg = cited; r.current_msg = corr_idx;
                // ALARM fires iff the citation lands in a message that is
                // superseded for THIS field — not merely "not the current
                // message" (a filler-message citation is noise, not a
                // stale-source finding, and must not count as either).
                r.alarm = std::find(superseded_msgs.begin(), superseded_msgs.end(), cited) != superseded_msgs.end();
                // SERVEABLE arm: the field's citations reach a message LATER than
                // the one the emitted value came from ⇒ the value the model wrote
                // is not from the last place it looked for this key. No ground
                // truth consulted — only citations and message boundaries.
                r.latest_cited_msg = cited_any.empty() ? -1 : *cited_any.rbegin();
                r.alarm_srv = cited >= 0 && r.latest_cited_msg > cited;
                // SERVEABLE+ : SERVEABLE's documented weakness is that ANY later
                // cited message fires it — including one that merely RESTATES the
                // same value. A confirmation ("confirming 300 units") is a later
                // message saying the identical thing; it is not a supersession,
                // and treating it as one manufactured false alarms the moment the
                // corpus gained restatements (FP 2 -> 4). Fix: fire only when the
                // later cited message does NOT contain the emitted value. Still
                // server-computable — the endpoint has the document, the caller's
                // message boundaries and the emitted value, so it can string-search
                // that message without any ground truth about which keys it speaks to.
                std::set<int> msgs_restating;
                for (auto& [mi, tp] : s2_occurrences(prompt, env, pcum, R.P, emitted))
                    msgs_restating.insert(mi);
                r.alarm_srv2 = r.alarm_srv && !msgs_restating.count(r.latest_cited_msg);
                alarms.push_back(r);
                // TRIVIAL-RULE CONTROL, item 4: this correction instance is
                // one of the tiny handful (n=8) of real alarm fields, so
                // record what each trivial rule would have predicted here
                // for the row dump — n is too small for a rate.
                {
                    auto occ = s2_occurrences(prompt, env, pcum, R.P, emitted);
                    if (occ.size() >= 2) {
                        S2TrivAlarmRow tr; tr.thread = def.tag; tr.concept = f.concept;
                        tr.head_msg = cited; tr.r_last = occ.back().first;
                        tr.r_first = occ.front().first; tr.r_near = tr.r_last;
                        triv_rows.push_back(tr);
                    }
                }
                std::printf("  [ALARM FIELD] %-13s emitted=%-12s label=%-5s cited_msg=%-3d "
                            "latest_cited=%-3d current_msg=%-3d -> oracle:%-6s serveable:%s\n",
                            f.concept.c_str(), emitted.c_str(), label ? "FRESH" : "STALE", cited,
                            r.latest_cited_msg, corr_idx, r.alarm ? "ALARM" : "silent",
                            r.alarm_srv ? "ALARM" : "silent");
                // DIAGNOSTIC: SERVEABLE takes the MAX over every message any
                // citation touched, so one stray hit into a late filler fires it.
                // Print the whole cited set, marking which messages actually
                // restate the emitted value (*) vs. which do not (-), so the
                // firing mechanism is visible instead of guessed at.
                std::printf("      cited_any = {");
                for (int cm : cited_any)
                    std::printf("%d%s ", cm, msgs_restating.count(cm) ? "*" : "-");
                std::printf("}  (* = message contains the emitted value)\n");
            } else {
                std::string ev;
                for (auto& gf : gfs) if (gf.name == f.concept) { ev = gf.value; break; }
                if (ev.find(f.value) == std::string::npos) { excluded++; continue; }
                std::vector<std::pair<size_t, size_t>> target;
                for (auto& [mi, span] : field_spans[f.concept]) if (mi == 0) target.push_back(span);
                score_field(f.concept, f.value, target);
            }
        }
    }

    // ── Gate 0: is thread-scale citation measurable? ─────────────────────────
    double t1p = cite_all.n ? 100.0 * cite_all.t1 / cite_all.n : 0;
    double t3p = cite_all.n ? 100.0 * cite_all.t3 / cite_all.n : 0;
    std::printf("\n================ GATE 0 — citation at thread scale ================\n");
    std::printf("  value tokens scored: %d  top1=%.0f%% (%d/%d)  top3=%.0f%% (%d/%d)  [bar top3>=85%%]\n",
                cite_all.n, t1p, cite_all.t1, cite_all.n, t3p, cite_all.t3, cite_all.n);
    std::printf("  excluded (normalized / not emitted verbatim): %d / %d labeled fields\n",
                excluded, labeled_total);
    // PERMISSIVE re-score printed alongside: same citations, target = ANY literal
    // occurrence of the value rather than only its designated message.
    double a1p = cite_any.n ? 100.0 * cite_any.t1 / cite_any.n : 0;
    double a3p = cite_any.n ? 100.0 * cite_any.t3 / cite_any.n : 0;
    std::printf("  RE-SCORE permissive (hit = ANY truthful occurrence of the value):\n"
                "    top1=%.0f%% (%d/%d)  top3=%.0f%% (%d/%d)\n"
                "    strict->permissive delta: top1 %+.0f pts, top3 %+.0f pts\n"
                "    A LARGE delta means the strict number is a LABELLING artifact (the head\n"
                "    points at a truthful confirmation, not the designated message). A SMALL\n"
                "    delta means the head genuinely misses the value's locations.\n",
                a1p, cite_any.t1, cite_any.n, a3p, cite_any.t3, cite_any.n,
                a1p - t1p, a3p - t3p);
    bool gate0 = cite_all.n > 0 && t3p >= 85.0;
    std::printf("  => %s\n", gate0 ? "GATE 0 PASS" : "GATE 0 FAIL — citation not measurable at thread scale");
    // Item 5 (open question settled): every call to score_field passes
    // target_spans restricted to specific message(s) — the corrected
    // message alone for FRESH, the superseded-but-not-corrected messages for
    // STALE, message 0 alone for the non-corrected "other fields" branch.
    // corr_idx's own span is explicitly excluded from the STALE target set.
    // So a hit requires landing in one of those named messages, NOT merely
    // matching the value string anywhere in the prompt: Gate 0's target
    // spans are MESSAGE-SCOPED, not value-scoped. Its 98% therefore DID
    // require the head to land in the right subset of messages for each
    // scored token, not just anywhere the string repeats.
    std::printf("  scope: target spans are MESSAGE-SCOPED (specific message(s) per field), "
                "not value-scoped (any copy anywhere) — see comment above cite_all.n at score_field.\n");

    // ══════════════ TRIVIAL-RULE CONTROL ══════════════════════════════════════
    // Defends the citation result above against the same failure class that
    // killed the earlier image-tap probe: a head that looks like it tracks
    // something meaningful but is actually just a positional artifact (there,
    // favouring one side of the image; here, always pointing at "the most
    // recent copy" or "the first copy" of a repeated value). If a trivial
    // positional rule reproduces the head's picks, the head adds nothing
    // over plain string matching.
    std::printf("\n================ TRIVIAL-RULE CONTROL ================\n");
    // Item 1 — denominator FIRST. Ambiguity requires |O| >= 2 (the value
    // actually repeats in the prompt); MIN_AMBIGUOUS_N is a stated bar below
    // which a rate is not worth reporting (chosen, like the file's other
    // bars, to keep a percentage from resting on a handful of tokens).
    const int MIN_AMBIGUOUS_N = 20;
    std::printf("  scored tokens with an actual ambiguity to resolve (|O|>=2): %ld / %d total scored\n",
                triv.ambiguous, cite_all.n);
    if (triv.ambiguous < MIN_AMBIGUOUS_N) {
        std::printf("  denominator < %d — THE CONTROL CANNOT RUN. Do not read a rate below; there is "
                    "not enough genuine ambiguity in this corpus to test the head against a trivial "
                    "positional rule.\n", MIN_AMBIGUOUS_N);
    } else {
        double rate_last  = 100.0 * triv.last_agree  / triv.ambiguous;
        double rate_first = 100.0 * triv.first_agree / triv.ambiguous;
        double rate_near  = 100.0 * triv.near_agree  / triv.ambiguous;
        std::printf("  R_last  agreement: %.0f%% (%ld/%ld)\n", rate_last,  triv.last_agree,  triv.ambiguous);
        std::printf("  R_first agreement: %.0f%% (%ld/%ld)\n", rate_first, triv.first_agree, triv.ambiguous);
        std::printf("  R_near  agreement: %.0f%% (%ld/%ld)  [coincides with R_last by construction here: "
                    "decode always follows the whole prompt, so the nearest occurrence to the decode "
                    "position is always the last one — reported for completeness, not as an "
                    "independent confirmation]\n", rate_near, triv.near_agree, triv.ambiguous);
        double best = std::max({rate_last, rate_first, rate_near});
        double disagree = 100.0 - best;
        const char* verdict = (best >= 95.0) ? "FAIL (head is redundant — a trivial rule agrees >=95%)"
                            : (disagree >= 15.0) ? "PASS (head is load-bearing — best trivial rule "
                                                    "disagrees on >=15% of ambiguous tokens)"
                            : "WEAK (neither bar met)";
        std::printf("  best trivial rule agrees %.0f%% (disagrees %.0f%%)  => %s\n", best, disagree, verdict);
    }
    // Item 4 — the 8 alarm fields specifically. n is tiny; print rows.
    std::printf("  alarm-field rows (n=%zu, head vs. what each trivial rule predicts):\n", triv_rows.size());
    std::printf("  %-8s %-12s %-8s %-8s %-9s %-8s\n", "thread", "concept", "head", "R_last", "R_first", "R_near");
    for (auto& tr : triv_rows)
        std::printf("  %-8s %-12s %-8d %-8d %-9d %-8d\n", tr.thread.c_str(), tr.concept.c_str(),
                    tr.head_msg, tr.r_last, tr.r_first, tr.r_near);

    // ── Gate 1: natural STALE rate ────────────────────────────────────────────
    int fresh = 0, stale = 0;
    for (auto& r : alarms) { if (r.label == 1) fresh++; else if (r.label == 0) stale++; }
    std::printf("\n================ GATE 1 — natural STALE rate ================\n");
    std::printf("  correction instances scored: %d (FRESH %d, STALE %d)\n", (int)alarms.size(), fresh, stale);
    std::printf("  %-8s %-6s %-9s %-9s %-6s %-6s\n", "thread", "lang", "position", "phrasing", "distr", "label");
    for (auto& r : alarms)
        std::printf("  %-8s %-6s %-9s %-9s %-6s %-6s\n", r.thread.c_str(), r.de ? "DE" : "EN",
                    r.position.c_str(), r.explicit_ph ? "explicit" : "indirect",
                    r.has_distractor ? "yes" : "no", r.label ? "FRESH" : "STALE");
    bool gate1 = stale > 0;
    std::printf("  => %s\n", gate1 ? "STALE occurs naturally at length" :
                "NO natural STALE at 4K-8K tokens (model honored every correction)");

    // ── Gate 2: does the alarm work? ──────────────────────────────────────────
    std::printf("\n================ GATE 2 — alarm precision/recall ================\n");
    if (!gate1) {
        std::printf("  (skipped: Gate 1 yielded 0 natural STALE — nothing to detect)\n");
        int fp_n = 0, fp_fired = 0;
        for (auto& r : alarms) if (r.label == 1) { fp_n++; if (r.alarm) fp_fired++; }
        std::printf("  FRESH false-alarm rate (fired despite correct answer): %d/%d (%.0f%%)\n",
                    fp_fired, fp_n, fp_n ? 100.0 * fp_fired / fp_n : 0);
    } else {
        auto score_arm = [&](const char* name, bool S2AlarmRec::*fired) {
            int tp = 0, fn = 0, fp_n = 0, tn = 0;
            for (auto& r : alarms) {
                if (r.label == 0) { if (r.*fired) tp++; else fn++; }
                else { if (r.*fired) fp_n++; else tn++; }
            }
            double precision = (tp + fp_n) ? 100.0 * tp / (tp + fp_n) : 0;
            double recall = (tp + fn) ? 100.0 * tp / (tp + fn) : 0;
            double falarm = (fp_n + tn) ? 100.0 * fp_n / (fp_n + tn) : 0;
            std::printf("  %-10s TP=%d FN=%d FP=%d TN=%d  precision=%.0f%%  recall=%.0f%%  "
                        "FRESH false-alarm=%.0f%%\n", name, tp, fn, fp_n, tn,
                        precision, recall, falarm);
        };
        score_arm("ORACLE", &S2AlarmRec::alarm);
        score_arm("SERVEABLE", &S2AlarmRec::alarm_srv);
        score_arm("SERVEABLE+", &S2AlarmRec::alarm_srv2);
        std::printf("  ORACLE uses corpus ground truth and CANNOT be computed by /v1/extract.\n"
                    "  SERVEABLE uses only citations + caller-declared message boundaries — it is\n"
                    "  the predicate a v3 endpoint could actually raise. Read the gap as the cost\n"
                    "  of shipping the alarm, not as noise.\n");
    }

    // ── Phrasing split — SS2's one hypothesis, stated as a testable claim ────
    // SS2 §2: its single STALE was late+indirect+distractor while an equally
    // late, equally distracted but EXPLICIT correction survived ⇒ "indirect
    // phrasing is the discriminator, not position." Under SS3's matched pairs
    // (seed, concept, value, distractor, position and length identical within
    // a pair; only phrasing differs) this table is the hypothesis test. Under
    // SS2 it is descriptive only — those threads are not matched.
    int e_n = 0, e_stale = 0, i_n = 0, i_stale = 0;
    for (auto& r : alarms) {
        if (r.explicit_ph) { e_n++; if (r.label == 0) e_stale++; }
        else               { i_n++; if (r.label == 0) i_stale++; }
    }
    std::printf("\n================ PHRASING SPLIT — is indirect the discriminator? ==\n");
    std::printf("  explicit correction: STALE %d/%d\n", e_stale, e_n);
    std::printf("  indirect correction: STALE %d/%d\n", i_stale, i_n);
    std::printf("  (matched pairs under SS3; descriptive only under SS2)\n");

    std::printf("\n================ VERDICT (%s) ================\n", leg);
    if (!gate0) std::printf("  => STILL BLOCKED: Gate 0 failed (top3 %.0f%% < 85%% bar) — citation "
                            "not measurable at thread scale.\n", t3p);
    else if (!gate1) std::printf("  => NO JOB: Gate 0 passed but natural STALE is 0/%d at 4K-8K "
                                 "tokens — the model honored every correction; the alarm has no "
                                 "job on this model at this envelope.\n", (int)alarms.size());
    else std::printf("  => ALARM VALIDATED (see Gate 2 precision/recall above) — but n is small "
                     "(%d STALE case%s); read the numbers as a signal, not a settled rate.\n",
                     stale, stale == 1 ? "" : "s");
    return 0;
}

// ═════════════════════════════════════════════════════════════════════════
// Norm-weighted attention (Metric B) — a calibration probe, gated by
// NORM_WEIGHTED=1. docs/note-lens-norm-weighted-metric.md.
//
// Metric A (shipped): score_j = alpha_j (the raw post-softmax kq_soft row).
// Metric B (candidate): score_j = alpha_j * ||V_j||, renormalized over j so
// the row sums to 1 -- the standard correction for what a head actually
// contributes to `output = sum_j alpha_j * V_j`.
//
// ||V_j|| is read straight off the persisted V cache
// (simple_kv_cache::get_v_cache_tensor) -- no graph change, no new tap. Every
// symbol above this point (Leg C, COV1, N3, ...) is untouched; this section
// only ADDS reader functions and two new driver legs.
// ═════════════════════════════════════════════════════════════════════════

// ‖V_j‖ for KV positions [0, n_kv) of one (cache-layer, kv-head).
//
// `cache_layer` is NOT the GGUF block index `il` (e.g. 27 for L27H13).
// simple_kv_cache is built ATTENTION-LAYERS-ONLY: qwen35.cpp assigns
// `kv_layer_map_[il] = n_attn_layers++` while walking blocks 0..block_count-1
// in increasing order and skipping non-attention blocks, so the compact cache
// index for tap slot `s` is `s` itself -- `attn_layers` (main()) is built by
// the identical increasing-il scan over `kq_soft.<il>` tensors, so slot index
// and cache index coincide by construction. Passing the block number here
// instead would silently read a DIFFERENT layer's V cache under the citation
// head's own printed name -- the exact trap this probe was warned about.
//
// Quantized KV (Q8_0/Q4_0) is out of reach here by construction, not by
// omission: this probe requires --flash-attn OFF (kq_soft never materializes
// under flash -- DecodePolicy::is_attn_impl_coherent() enforces the pairing
// elsewhere), and a quantized KV cache is refused without flash attention
// (kv_type_requires_flash_refusal, kv_cache_simple.h). So any run that reaches
// this function already has an F32 or F16 V cache; anything else fails loud
// instead of silently misreading quantized blocks as floats.
static std::vector<float> value_norms(simple_kv_cache* kv, int cache_layer, int kv_head,
                                      int head_dim, int n_head_kv, int n_kv) {
    ggml_tensor* vt = kv->get_v_cache_tensor(cache_layer);
    if (!vt)
        throw std::runtime_error("value_norms: expected a V cache tensor for cache layer " +
                                 std::to_string(cache_layer) + ", actual nullptr");
    if (vt->type != GGML_TYPE_F32 && vt->type != GGML_TYPE_F16)
        throw std::runtime_error("value_norms: expected V cache type f32 or f16 (quantized KV "
            "requires --flash-attn, which this probe forbids), actual " +
            std::string(ggml_type_name(vt->type)));
    const int n_embd_v = n_head_kv * head_dim;
    if ((int)vt->ne[0] != n_embd_v)
        throw std::runtime_error("value_norms: expected V cache ne[0]=" +
            std::to_string(n_embd_v) + " (n_head_kv*head_dim), actual " + std::to_string(vt->ne[0]));
    if (kv_head < 0 || kv_head >= n_head_kv)
        throw std::runtime_error("value_norms: expected kv_head in [0," + std::to_string(n_head_kv) +
            "), actual " + std::to_string(kv_head));
    // Slot 0 (the only slot this single-slot probe ever uses): byte offset
    // within the tensor is just position * nb[1]. A freshly-allocated ggml
    // tensor is contiguous, so nb[1] must equal n_embd_v * element_size --
    // asserted explicitly (from the tensor's own nb[], not assumed) rather
    // than trusted, per the layout trap this probe was warned about.
    const size_t elem = ggml_type_size(vt->type);
    if (vt->nb[1] != (size_t)n_embd_v * elem)
        throw std::runtime_error("value_norms: expected V cache row stride " +
            std::to_string((size_t)n_embd_v * elem) + " bytes (contiguous), actual " +
            std::to_string(vt->nb[1]));
    std::vector<uint8_t> raw((size_t)n_kv * n_embd_v * elem);
    ggml_backend_tensor_get(vt, raw.data(), 0, raw.size());

    std::vector<float> out(n_kv, 0.0f);
    for (int j = 0; j < n_kv; ++j) {
        double ss = 0;
        const uint8_t* rowb = raw.data() + (size_t)j * n_embd_v * elem;
        if (vt->type == GGML_TYPE_F32) {
            const float* row = reinterpret_cast<const float*>(rowb);
            for (int d = 0; d < head_dim; ++d) { double x = row[(size_t)kv_head * head_dim + d]; ss += x * x; }
        } else {
            const ggml_fp16_t* row = reinterpret_cast<const ggml_fp16_t*>(rowb);
            for (int d = 0; d < head_dim; ++d) {
                double x = ggml_fp16_to_fp32(row[(size_t)kv_head * head_dim + d]);
                ss += x * x;
            }
        }
        out[j] = (float)std::sqrt(ss);
    }
    return out;
}

// Sanity check (trap #3): ||V_j|| should be smooth and positive with no zeros
// in the populated interior -- a block of exact zeros means the read is past
// the populated rows, or striding wrong. Position 0 (BOS) and the very last
// written row are excluded: BOS can legitimately be a near-zero-norm sink,
// and there is no guarantee here about what lies immediately after the
// current write cursor.
static void sanity_check_norms(const std::vector<float>& vnorm, const char* where) {
    if (vnorm.size() < 4) return;
    for (size_t j = 1; j + 2 < vnorm.size(); ++j) {
        if (vnorm[j] <= 0.0f)
            throw std::runtime_error(std::string("value_norms sanity: expected every populated "
                "interior position to have ||V||>0, actual 0 at position ") + std::to_string(j) +
                " of " + std::to_string(vnorm.size()) + " (" + where + ")");
    }
}

// Metric B's analogue of topk_head: rank KV positions by alpha_j * ||V_j||
// instead of alpha_j, renormalized over j so the row sums to 1 (a positive
// rescale of every candidate, so it does not change the ranking by itself --
// done anyway so the reported score is on the same 0..1 "mass" scale as
// Metric A, for honest side-by-side printing). Same BOS-sink exclusion
// (j starts at 1) as Metric A, for the same reason: an attention sink would
// otherwise win every top-1 by construction regardless of ||V||.
static std::vector<std::pair<int, float>> topk_head_weighted(
        const std::vector<float>& row, int h, int n_kv, int k,
        const std::vector<float>& vnorm) {
    const float* r = row.data() + (size_t)h * n_kv;
    double tot = 0;
    for (int j = 0; j < n_kv; ++j) tot += (double)r[j] * vnorm[j];
    const float inv = tot > 0 ? (float)(1.0 / tot) : 0.0f;
    std::vector<std::pair<int, float>> v;
    for (int j = 1; j < n_kv; ++j) v.push_back({j, (float)((double)r[j] * vnorm[j] * inv)});
    std::partial_sort(v.begin(), v.begin() + std::min((size_t)k, v.size()), v.end(),
                      [](auto& a, auto& b) { return a.second > b.second; });
    if ((int)v.size() > k) v.resize(k);
    return v;
}

// Metric B's analogue of the raw-alpha span-mass sum used throughout (topk
// excepted): renormalized weighted mass on [lo,hi], as a fraction of the
// row's total renormalized mass over ALL j in [0,n_kv) (mirroring how Metric
// A's raw row already sums to 1 over all j including the BOS position).
static double span_mass_weighted(const std::vector<float>& row, int h, int n_kv,
                                 int lo, int hi, const std::vector<float>& vnorm) {
    const float* r = row.data() + (size_t)h * n_kv;
    double tot = 0;
    for (int j = 0; j < n_kv; ++j) tot += (double)r[j] * vnorm[j];
    if (tot <= 0) return 0;
    double s = 0;
    for (int q = lo; q <= hi && q < n_kv; ++q) s += (double)r[q] * vnorm[q];
    return s / tot;
}

// Rank-based AUC (Mann-Whitney U / (n_pos*n_neg)): P(random positive scores
// higher than random negative), with average-rank tie handling. A model-free
// separation figure, independent of any chosen threshold.
static double auc_of(const std::vector<std::pair<double, bool>>& data) {
    std::vector<std::pair<double, bool>> v = data;
    std::sort(v.begin(), v.end());
    const int n = (int)v.size();
    std::vector<double> rank(n);
    int i = 0;
    while (i < n) {
        int j = i;
        while (j < n && v[j].first == v[i].first) j++;
        double avg_rank = (i + j - 1) / 2.0 + 1.0;  // 1-indexed
        for (int k2 = i; k2 < j; ++k2) rank[k2] = avg_rank;
        i = j;
    }
    double sum_rank_pos = 0; int n_pos = 0, n_neg = 0;
    for (int k2 = 0; k2 < n; ++k2) { if (v[k2].second) { sum_rank_pos += rank[k2]; n_pos++; } else n_neg++; }
    if (n_pos == 0 || n_neg == 0) return -1;
    double u = sum_rank_pos - n_pos * (n_pos + 1) / 2.0;
    return u / ((double)n_pos * n_neg);
}

// Paired A/B citation+coverage eval for one grounded field value. Mirrors
// qdocs_eval_field exactly for Metric A (byte-identical numbers) and adds the
// Metric B twin computed from the SAME rows in the SAME pass.
struct QFieldEvalDual {
    bool found_verbatim = false;
    int cite_n = 0, t1A = 0, t3A = 0, t1B = 0, t3B = 0;
    double cov_peakA = -1, cov_peakB = -1;
};
static QFieldEvalDual qdocs_eval_field_dual(Tokenizer* tok, const FreeRun& R, const std::string& value,
        const std::vector<int32_t>& attn_layers, int TOL,
        const std::vector<std::vector<float>>& vnorm_cite,  // [kv_head][pos] at L3H13_SLOT's cache layer
        const std::vector<std::vector<float>>& vnorm_cov,   // [kv_head][pos] at L11_SLOT's cache layer
        int group) {
    QFieldEvalDual e;
    int slo, shi;
    if (!qdocs_span_in_prompt(tok, R, value, slo, shi)) return e;

    double sc[SC_N][4]; span_scalars(R, slo, shi, sc, attn_layers);
    e.cov_peakA = sc[1 + L11_SLOT][0];

    double peakB = 0;
    for (int t = 0; t < (int)R.rows.size(); ++t) {
        int n_kv = R.n_kv_at_step[t];
        double layer_best = 0;
        for (int h = 0; h < R.n_head; ++h) {
            int kh = h / group;
            double s = span_mass_weighted(R.rows[t][L11_SLOT], h, n_kv, slo, shi, vnorm_cov[kh]);
            if (s > layer_best) layer_best = s;
        }
        if (layer_best > peakB) peakB = layer_best;
    }
    e.cov_peakB = peakB;

    std::vector<size_t> gcum = cum_bytes(tok, R.gen_tokens);
    size_t gb = R.gen_text.find(value);
    if (gb == std::string::npos) return e;   // normalized away
    e.found_verbatim = true;
    size_t ge = gb + value.size();
    const int kh_cite = FROZEN_HEAD / group;
    for (int g = 0; g < (int)R.gen_tokens.size(); ++g) {
        if (!(gcum[g] < ge && gcum[g + 1] > gb)) continue;
        if (g < 1 || g - 1 >= (int)R.rows.size()) continue;
        int n_kv = R.n_kv_at_step[g - 1];
        auto in = [&](int p) { return p >= slo - TOL && p <= shi + TOL; };
        e.cite_n++;
        auto tkA = topk_head(R.rows[g - 1][L3H13_SLOT], FROZEN_HEAD, n_kv, 3);
        if (!tkA.empty() && in(tkA[0].first)) e.t1A++;
        for (auto& pr : tkA) if (in(pr.first)) { e.t3A++; break; }
        auto tkB = topk_head_weighted(R.rows[g - 1][L3H13_SLOT], FROZEN_HEAD, n_kv, 3, vnorm_cite[kh_cite]);
        if (!tkB.empty() && in(tkB[0].first)) e.t1B++;
        for (auto& pr : tkB) if (in(pr.first)) { e.t3B++; break; }
    }
    return e;
}

// ── ARM 1 — citation, paired A/B, on the SAME Leg C messy corpus (15 docs
// EN+DE, 413 scored value tokens) that produced the shipped 98%/89% numbers.
// Metric A must reproduce those numbers or the plumbing here is wrong.
// used_peaks_AB collects every used-span's (peakA, peakB) pair for Arm 2's
// final cross-check against Leg C's own population.
static int run_qdocs_leg_c_dual(ForwardPassBase* fp, ggml_backend_sched_t sched,
                                Tokenizer* tok, const ModelMetadata& meta,
                                const std::vector<int32_t>& attn_layers,
                                std::vector<std::pair<double, double>>* used_peaks_AB) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ NORM-WEIGHTED ARM 1 — citation, Leg C messy corpus (paired A/B) ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");

    const int TOL = 2;
    const std::vector<std::string>& vocab = tok->get_vocabulary();
    const uint32_t vocab_size = (uint32_t)vocab.size();
    qinf::TokenTrie trie; trie.build(vocab);
    auto gr = qinf::GrammarVocab::parse_impl(QDOCS_GBNF);
    gr->set_token_trie(&trie);
    std::vector<int> taps10(attn_layers.begin(), attn_layers.end());
    const char* TASK = "\n\nExtract every fact from the email above into a flat JSON "
        "object of \"key\": \"value\" pairs. Use short snake_case keys — prefer keys like: "
        "customer, product, quantity, unit_price, total, order_date, delivery, order_number. "
        "Copy each value verbatim from the email. Output ONLY the JSON object, nothing else.";

    auto corpus = qdocs_messy_corpus();
    simple_kv_cache* kv = fp->snapshot_kv_cache();
    if (!kv) throw std::runtime_error("run_qdocs_leg_c_dual: expected a KV cache, actual nullptr");
    const int n_head_kv = (int)meta.attention_head_count_kv;
    const int head_dim  = (int)meta.attention_value_length;
    const int group     = (int)meta.attention_head_count / n_head_kv;

    struct Acc { int cite_n = 0, t1A = 0, t3A = 0, t1B = 0, t3B = 0;
                 int used_spans = 0, used_clearA = 0;
                 std::vector<double> peaksA, peaksB; int grounded = 0, labeled = 0; };
    Acc en, de;
    auto pick = [&](bool d) -> Acc& { return d ? de : en; };

    for (const QMessy& d : corpus) {
        std::string prompt = qdocs_chat_prompt(d.document, TASK);
        std::vector<GStep> tr;
        FreeRun R = run_freegen_grammar(fp, sched, tok, meta, prompt, "", taps10,
                                        320, gr.get(), vocab, vocab_size, &tr);
        std::printf("\n[%s%s] %s\n", d.tag.c_str(), d.de ? " DE" : "", R.gen_text.c_str());

        int n_kv_final = R.n_kv_at_step.empty() ? R.P : R.n_kv_at_step.back();
        std::vector<std::vector<float>> vnorm_cite(n_head_kv), vnorm_cov(n_head_kv);
        for (int kh = 0; kh < n_head_kv; ++kh) {
            vnorm_cite[kh] = value_norms(kv, L3H13_SLOT, kh, head_dim, n_head_kv, n_kv_final);
            sanity_check_norms(vnorm_cite[kh], "leg-c-dual citation layer");
            vnorm_cov[kh] = value_norms(kv, L11_SLOT, kh, head_dim, n_head_kv, n_kv_final);
            sanity_check_norms(vnorm_cov[kh], "leg-c-dual coverage layer");
        }

        Acc& A = pick(d.de);
        for (const QLabel& f : d.fields) {
            A.labeled++;
            QFieldEvalDual e = qdocs_eval_field_dual(tok, R, f.value, attn_layers, TOL,
                                                     vnorm_cite, vnorm_cov, group);
            if (e.cov_peakA >= 0) {
                A.used_spans++; A.peaksA.push_back(e.cov_peakA); A.peaksB.push_back(e.cov_peakB);
                if (e.cov_peakA >= 0.705) A.used_clearA++;
                if (used_peaks_AB) used_peaks_AB->push_back({e.cov_peakA, e.cov_peakB});
            }
            if (!e.found_verbatim) continue;
            A.cite_n += e.cite_n; A.t1A += e.t1A; A.t3A += e.t3A; A.t1B += e.t1B; A.t3B += e.t3B;
            A.grounded++;
        }
    }

    auto med = [](std::vector<double> v) { if (v.empty()) return 0.0; std::sort(v.begin(), v.end());
        return v[v.size() / 2]; };
    auto report = [&](const char* label, const Acc& A) {
        std::printf("\n──────── %s ────────\n", label);
        std::printf("  citation A (raw alpha)     top1 %d/%d (%.0f%%)  top3 %d/%d (%.0f%%)\n",
                    A.t1A, A.cite_n, A.cite_n ? 100.0 * A.t1A / A.cite_n : 0,
                    A.t3A, A.cite_n, A.cite_n ? 100.0 * A.t3A / A.cite_n : 0);
        std::printf("  citation B (alpha*||V||)   top1 %d/%d (%.0f%%)  top3 %d/%d (%.0f%%)\n",
                    A.t1B, A.cite_n, A.cite_n ? 100.0 * A.t1B / A.cite_n : 0,
                    A.t3B, A.cite_n, A.cite_n ? 100.0 * A.t3B / A.cite_n : 0);
        std::printf("  coverage used-clear A @0.705: %d/%d (%.0f%%)  median peakA %.3f  median peakB %.3f\n",
                    A.used_clearA, A.used_spans, A.used_spans ? 100.0 * A.used_clearA / A.used_spans : 0,
                    med(A.peaksA), med(A.peaksB));
    };
    report("EN", en);
    report("DE", de);
    Acc all;
    all.cite_n = en.cite_n + de.cite_n; all.t1A = en.t1A + de.t1A; all.t3A = en.t3A + de.t3A;
    all.t1B = en.t1B + de.t1B; all.t3B = en.t3B + de.t3B;
    all.used_spans = en.used_spans + de.used_spans; all.used_clearA = en.used_clearA + de.used_clearA;
    for (double p : en.peaksA) all.peaksA.push_back(p);
    for (double p : de.peaksA) all.peaksA.push_back(p);
    for (double p : en.peaksB) all.peaksB.push_back(p);
    for (double p : de.peaksB) all.peaksB.push_back(p);
    report("COMBINED", all);

    double t3A = all.cite_n ? 100.0 * all.t3A / all.cite_n : 0;
    double t3B = all.cite_n ? 100.0 * all.t3B / all.cite_n : 0;
    double t1A = all.cite_n ? 100.0 * all.t1A / all.cite_n : 0;
    double t1B = all.cite_n ? 100.0 * all.t1B / all.cite_n : 0;
    std::printf("\n── ARM 1 GATE: metric A top1 %.1f%% top3 %.1f%%  (repro check: want ~89%%/~98%%)\n"
                "               metric B top1 %.1f%% top3 %.1f%%  (STOP condition: top3 <95%%) ──\n",
                t1A, t3A, t1B, t3B);
    return 0;
}

// ── ARM 2 — coverage separation, paired A/B, on the COV1 corpus (cov_calib +
// cov_held, the only corpus here with an explicit USED-vs-DROPPED label) at
// the frozen coverage layer (layer 11 / L11_SLOT — no layer search, per the
// gate's scope). Reports medians, AUC, and each metric's OWN best threshold
// (found independently — the 0.705 constant is Metric-A-only and is never
// applied to Metric B's differently-scaled quantity).
static int run_coverage_probe_dual(ForwardPassBase* fp, ggml_backend_sched_t sched,
                                   Tokenizer* tok, const ModelMetadata& meta,
                                   const std::vector<int32_t>& attn_layers,
                                   Thr* out_thrA, Thr* out_thrB) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ NORM-WEIGHTED ARM 2 — coverage separation, COV1 corpus (paired) ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");
    std::vector<int> tap_layers(attn_layers.begin(), attn_layers.end());
    simple_kv_cache* kv = fp->snapshot_kv_cache();
    if (!kv) throw std::runtime_error("run_coverage_probe_dual: expected a KV cache, actual nullptr");
    const int n_head_kv = (int)meta.attention_head_count_kv;
    const int head_dim  = (int)meta.attention_value_length;
    const int group     = (int)meta.attention_head_count / n_head_kv;

    struct SpanRecW { std::string prompt, marker; int cls = 0, label = 0, len = 0;
                       double peakA = 0, peakB = 0; };
    std::vector<SpanRecW> cal, hel;

    auto run_set = [&](std::vector<CovPrompt> set, std::vector<SpanRecW>& out) {
        for (auto& cp : set) {
            FreeRun R = run_freegen(fp, sched, tok, meta, cp.body, cp.instr,
                                    tap_layers, 320, false, cp.close);
            int n_kv_final = R.n_kv_at_step.empty() ? R.P : R.n_kv_at_step.back();
            std::vector<std::vector<float>> vnorm(n_head_kv);
            for (int kh = 0; kh < n_head_kv; ++kh) {
                vnorm[kh] = value_norms(kv, L11_SLOT, kh, head_dim, n_head_kv, n_kv_final);
                sanity_check_norms(vnorm[kh], "cov1-dual coverage layer");
            }
            for (auto& tg : cp.tg) {
                int lo, hi;
                if (!find_token_span(tok, R.prompt_tokens, cp.body, tg.marker, lo, hi)) {
                    std::printf("  WARN marker not found: %s\n", tg.marker.c_str());
                    continue;
                }
                SpanRecW r; r.prompt = cp.tag; r.marker = tg.marker; r.cls = tg.cls; r.len = hi - lo + 1;
                r.label = tg.cls != CT_TARGET ? -1 : (R.gen_text.find(tg.used) != std::string::npos ? 1 : 0);
                double sc[SC_N][4]; span_scalars(R, lo, hi, sc, attn_layers);
                r.peakA = sc[1 + L11_SLOT][0];
                double peakB = 0;
                for (int t = 0; t < (int)R.rows.size(); ++t) {
                    int n_kv = R.n_kv_at_step[t];
                    double layer_best = 0;
                    for (int h = 0; h < R.n_head; ++h) {
                        int kh = h / group;
                        double s = span_mass_weighted(R.rows[t][L11_SLOT], h, n_kv, lo, hi, vnorm[kh]);
                        if (s > layer_best) layer_best = s;
                    }
                    if (layer_best > peakB) peakB = layer_best;
                }
                r.peakB = peakB;
                out.push_back(r);
            }
        }
    };
    std::printf("\n---- generations + labels ----\n");
    run_set(cov_calib(), cal);
    std::printf("---- held ----\n");
    run_set(cov_held(), hel);

    auto pairsA = [&](const std::vector<SpanRecW>& v) {
        std::vector<std::pair<double, bool>> d;
        for (auto& r : v) if (r.cls == CT_TARGET) d.push_back({r.peakA, r.label == 1});
        return d;
    };
    auto pairsB = [&](const std::vector<SpanRecW>& v) {
        std::vector<std::pair<double, bool>> d;
        for (auto& r : v) if (r.cls == CT_TARGET) d.push_back({r.peakB, r.label == 1});
        return d;
    };

    Thr thrA = best_threshold(pairsA(cal));
    Thr thrB = best_threshold(pairsB(cal));
    double heldA = apply_thr(thrA, pairsA(hel));
    double heldB = apply_thr(thrB, pairsB(hel));
    double aucA_cal = auc_of(pairsA(cal)), aucA_hel = auc_of(pairsA(hel));
    double aucB_cal = auc_of(pairsB(cal)), aucB_hel = auc_of(pairsB(hel));

    std::printf("\n---- separation, TARGET USED vs DROPPED (calib=%zu, held=%zu spans, layer %d) ----\n",
                pairsA(cal).size(), pairsA(hel).size(), attn_layers[L11_SLOT]);
    std::printf("  metric A (raw alpha)     calib-best thr=%.3f dir%+d acc=%.0f%%  AUC(calib)=%.3f  "
                "HELD acc=%.0f%% AUC(held)=%.3f\n",
                thrA.t, thrA.dir, 100 * thrA.acc, aucA_cal, 100 * heldA, aucA_hel);
    std::printf("  metric B (alpha*||V||)   calib-best thr=%.3f dir%+d acc=%.0f%%  AUC(calib)=%.3f  "
                "HELD acc=%.0f%% AUC(held)=%.3f\n",
                thrB.t, thrB.dir, 100 * thrB.acc, aucB_cal, 100 * heldB, aucB_hel);

    std::vector<SpanRecW> all = cal; all.insert(all.end(), hel.begin(), hel.end());
    auto med_cls = [&](int cls, int lab, bool useB) {
        std::vector<double> v;
        for (auto& r : all) if (r.cls == cls && (lab < -1 || r.label == lab)) v.push_back(useB ? r.peakB : r.peakA);
        return median(v);
    };
    std::printf("\n---- per-class medians (COV1 pooled, calib+held) ----\n");
    std::printf("  A: FILLER %.3f  DROPPED %.3f  USED %.3f  [VALUE anchor %.3f]\n",
                med_cls(CT_FILLER, -2, false), med_cls(CT_TARGET, 0, false),
                med_cls(CT_TARGET, 1, false), med_cls(CT_VALUE, -2, false));
    std::printf("  B: FILLER %.3f  DROPPED %.3f  USED %.3f  [VALUE anchor %.3f]\n",
                med_cls(CT_FILLER, -2, true), med_cls(CT_TARGET, 0, true),
                med_cls(CT_TARGET, 1, true), med_cls(CT_VALUE, -2, true));

    if (out_thrA) *out_thrA = thrA;
    if (out_thrB) *out_thrB = thrB;
    return 0;
}

// Combined driver: Arm 1 (citation, Leg C) then Arm 2 (coverage separation,
// COV1), then a final cross-check applying Metric B's OWN best threshold
// (picked on COV1, independently of Metric A's frozen 0.705) to Leg C's own
// used-span population — the number that pairs directly against the shipped
// 87%-at-0.705 result docs/note-lens-qwen38-probe.md reports.
static int run_norm_weighted_probe(ForwardPassBase* fp, ggml_backend_sched_t sched,
                                   Tokenizer* tok, const ModelMetadata& meta,
                                   const std::vector<int32_t>& attn_layers) {
    std::vector<std::pair<double, double>> used_peaks_AB;
    int rc1 = run_qdocs_leg_c_dual(fp, sched, tok, meta, attn_layers, &used_peaks_AB);
    if (rc1) return rc1;

    Thr thrA, thrB;
    int rc2 = run_coverage_probe_dual(fp, sched, tok, meta, attn_layers, &thrA, &thrB);
    if (rc2) return rc2;

    int clearA_frozen = 0, clearA_own = 0, clearB = 0;
    for (auto& pr : used_peaks_AB) {
        if (pr.first >= 0.705) clearA_frozen++;
        bool a_clear_own = thrA.dir > 0 ? pr.first >= thrA.t : pr.first <= thrA.t;
        if (a_clear_own) clearA_own++;
        bool b_clear = thrB.dir > 0 ? pr.second >= thrB.t : pr.second <= thrB.t;
        if (b_clear) clearB++;
    }
    int n = (int)used_peaks_AB.size();
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ ARM 2 CROSS-CHECK — Leg C used-span clear-rate at each metric's║\n");
    std::printf("║ OWN best operating point (thresholds picked on COV1, THIS run) ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");
    std::printf("  metric A @ 0.705 (frozen, COV1-derived on Qwen 3.6):       %d/%d (%.0f%%)  [bar >=90%%]\n",
                clearA_frozen, n, n ? 100.0 * clearA_frozen / n : 0);
    std::printf("  metric A @ %.3f dir%+d (COV1-derived on THIS run, fair):   %d/%d (%.0f%%)  [bar >=90%%]\n",
                thrA.t, thrA.dir, clearA_own, n, n ? 100.0 * clearA_own / n : 0);
    std::printf("  metric B @ %.3f dir%+d (COV1-derived on THIS run):         %d/%d (%.0f%%)  [bar >=90%%]\n",
                thrB.t, thrB.dir, clearB, n, n ? 100.0 * clearB / n : 0);
    std::printf("  (the A-frozen vs A-own-threshold pair isolates how much of any A-vs-B gap is\n"
                "   metric shape vs. simply recalibrating the threshold on THIS model/corpus.)\n");
    return 0;
}


// ═════════════════════════════════════════════════════════════════════════
// COVSEARCH — coverage layer × threshold search. docs/plan-coverage-layer-search.md
//
// The incumbent (layer 11, peak, ≥0.705) is a 48-candidate argmax scored on
// COV1's 12 calibration spans (run_coverage_probe above; note-attn-coverage-
// probe.md §3). It went 100% there and scores 84%/87% on Leg C's 75. This leg
// re-runs the selection with the three things that one lacked:
//
//   1. an evaluation corpus that took no part in choosing (Leg C, 6x larger),
//   2. AUC — threshold-free and two-sided — instead of calibration accuracy,
//   3. a plateau requirement, so a lone spike on 23 spans cannot win.
//
// It costs no extra forward passes: span_scalars() already fills every tapped
// layer's peak in one pass, and the shipped metric throws all but one away.
//
// The scalar SHAPE is held at `peak` deliberately (plan §2): sweeping shapes
// too would rebuild the same 48-way argmax this leg exists to replace.
// ═════════════════════════════════════════════════════════════════════════
// BANDDRIFT — the DRIFT GATE. Does a candidate transform MOVE a lens decision?
//
// This is the standing gate of docs/plan-lens-server-shape.md §4.3: any
// optimisation that changes the numerics is scored the same way and passes or
// fails against a MEASURED budget, instead of being argued about. Generalised
// 2026-09-13 from a probe that knew exactly one transform.
//
// The shape is always: arm A = the shipped configuration, arm B = the
// candidate, same weights, same tokens, same prompt. Pick the candidate with
// DRIFT_ARM (default `chunk`, today's behaviour):
//
//   chunk  — the SAME prompt driven as a chunk sequence over one shared KV.
//            Different matmul widths, which Metal does not reduce identically
//            (project_metal_mm_mv_fork; engine/multimodal_prefill.cpp names it
//            outright). Chunk size: ATTN_BAND_CHUNK, default 128.
//   warm   — the SHIPPED prefix-cache shape: ONE prefill boundary at
//            ATTN_BAND_SPLIT_PCT% of the prompt (default 50). Unlike `chunk`,
//            this is not a stress test — it is what --prefix-cache,
//            --chat-prefix-cache and --conversational do on every warm hit.
//   flash  — flash attention in PREFILL with the decode left materialized
//            (§4.2.1). Not a mix of two known configurations: the attention
//            output feeds the residual stream, so a flash prefill changes every
//            later layer's K/V, and the tapped decode then reads a cache that
//            was written differently. That is precisely what is being scored.
//
// THREE CRITERIA, all reported, all required to PASS:
//
//   1. Token identity. A document whose two arms emit different tokens is
//      EXCLUDED from the drift statistics and FAILS the gate — comparing peaks
//      across two different generations would measure divergence, not drift.
//      This is the repo's standard token-stable gate, not a new bar.
//   2. No decision crossed the threshold. This is the one that matters: the
//      lens publishes `skipped[]`, and a decision that crossed is a line that
//      appeared or vanished from a customer's report.
//   3. Max |delta peak| below the decision margin — the early-warning
//      criterion. Nothing crossed *this* corpus, but a drift larger than the
//      margin means the next document could.
//
// UNITS (fixed 2026-09-13, §4.3). The margin is measured on the SAME unit the
// drift is: BODY LINES. The lens's decision unit is the line — that is what a
// reader sees withdrawn or asserted — so the budget is the distance from 0.705
// to the nearest line peak in arm A. The earlier verdict compared line drift
// against 0.0034, which is a *span*-level margin from BAND COST; lines sum
// 10–40 tokens and spans 1–3, so the two are not the same scale and that
// comparison was meaningless in the safe direction (it flattered nothing — the
// line margin is the wider of the two — but it was not a measurement of this).
//
// LANGUAGE: DRIFT_LANG=en (default, the optimistic arm) or `all`. The German
// spans are the ones crowding the threshold (BAND COST), so an EN-only margin
// is the best case and an EN-only PASS is a weaker statement than it looks.
// Run `all` before claiming a transform is safe for the shipped, bilingual
// path — the margin is what changes, not usually the drift.
//
// Exit code is the gate: 0 = PASS, 1 = FAIL. Wire it into a script and an
// optimisation is tested rather than debated.
struct DriftArm {
    const char* name;
    const char* what;
    int         prefill_chunk = 0;     // 0 = today's single-batch prefill
    bool        flash_prefill = false;
    int         prefill_split_pct = 0; // >0 = ONE boundary at that % (warm cache)
};

// Default `en` keeps today's behaviour and today's published numbers.
static bool drift_en_only() {
    const char* l = std::getenv("DRIFT_LANG");
    if (!l || std::string(l) == "en") return true;
    if (std::string(l) == "all") return false;
    throw std::runtime_error(
        std::string("drift_en_only: slot 'DRIFT_LANG' expected one of en|all, got: ") + l);
}

static DriftArm drift_arm_from_env() {
    std::string want = "chunk";
    if (const char* a = std::getenv("DRIFT_ARM")) want = a;
    int CH = 128;
    if (const char* c = std::getenv("ATTN_BAND_CHUNK")) CH = std::atoi(c);
    if (want == "chunk")
        return {"chunk", "chunked prefill over one shared KV (Metal mm-vs-mv fork)",
                CH, false};
    if (want == "flash")
        return {"flash", "flash PREFILL + materialized decode (plan §4.2.1)",
                0, true, 0};
    if (want == "warm") {
        // The SHIPPED cache shape, not a synthetic one: --prefix-cache,
        // --chat-prefix-cache and --conversational all resume a prompt whose
        // leading run of tokens was written to KV by an EARLIER request, at
        // that request's own batch width. That is exactly one prefill boundary.
        // architecture.md's flag table calls all three "transparent" — warm ==
        // cold — which is a measured fact on dense and an untested claim on
        // MoE, where selection is an argmax. This arm tests the claim.
        int pct = 50;
        if (const char* q = std::getenv("ATTN_BAND_SPLIT_PCT")) pct = std::atoi(q);
        return {"warm",
                "warm prefix cache: ONE prefill boundary (the shipped cache shape)",
                0, false, pct};
    }
    throw std::runtime_error(
        "drift_arm_from_env: slot 'DRIFT_ARM' expected one of chunk|flash|warm, got: " + want);
}

struct BandLine { int lo, hi; double peak; std::string text; };

static std::vector<BandLine> band_body_lines(Tokenizer* tok, const FreeRun& R,
                                             int doc_lo, int doc_hi, int cov_slot) {
    const int G = (int)R.rows.size();
    std::vector<BandLine> out;
    int lstart = doc_lo;
    for (int p = doc_lo; p <= doc_hi && p < R.P; ++p) {
        std::string tt = tok->decode(R.prompt_tokens[p]);
        const bool nl = tt.find('\n') != std::string::npos;
        if (!nl && p != doc_hi) continue;
        const int lo = lstart, hi = p;
        double sp = 0;
        for (int t = 0; t < G; ++t) {
            const int n_kv = R.n_kv_at_step[t];
            double sum = 0;
            for (int q = lo; q <= hi; ++q) {
                if (q >= n_kv) continue;
                double m = 0;
                for (int h = 0; h < R.n_head; ++h) {
                    const double v = R.rows[t][cov_slot][(size_t)h * n_kv + q];
                    if (v > m) m = v;
                }
                sum += m;
            }
            if (sum > sp) sp = sum;
        }
        std::string tx;
        for (int q = lo; q <= hi; ++q) tx += tok->decode(R.prompt_tokens[q]);
        out.push_back({lo, hi, sp, tx});
        lstart = p + 1;
    }
    return out;
}

static int run_band_drift_probe(ForwardPassBase* fp, ggml_backend_sched_t sched,
                                Tokenizer* tok, const ModelMetadata& meta,
                                const std::vector<int32_t>& attn_layers) {
    // No covsearch_require_expressible here: that guard exists for span_scalars'
    // 12-slot layout, which this leg does not use — it reads one tapped layer.
    const DriftArm arm = drift_arm_from_env();
    const bool en_only = drift_en_only();
    const int cov_layer = attn_layers[L11_SLOT];
    // The SHIPPED operating point by default. DRIFT_THR (with ATTN_COV_SLOT for
    // the layer) scores a CANDIDATE one instead — which is the other half of a
    // recalibration: COVSEARCH says a layer reports more of the consulted
    // spans, and this says whether its decisions survive a permitted config
    // change. A constant that wins the first and loses the second is not
    // shippable, and before 2026-09-14 there was no way to ask.
    double THR = 0.705;
    if (const char* t = std::getenv("DRIFT_THR")) THR = std::atof(t);

    // Fail loud rather than silently scoring the shipped path against itself:
    // a recipe that does not thread use_flash would run arm B materialized and
    // report a perfect zero, which is the most misleading result this gate
    // could produce.
    if (arm.flash_prefill && !fp->supports_flash_attn()) {
        std::fprintf(stderr,
            "drift gate: slot 'DRIFT_ARM=flash' expected a recipe that threads "
            "flash attention, actual: this recipe does not support it — arm B "
            "would run materialized and the gate would pass vacuously\n");
        return 1;
    }

    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ DRIFT GATE — does a candidate transform move a decision?       ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");
    std::printf("  arm A  shipped: single-batch prefill, materialized attention\n");
    std::printf("  arm B  %-6s: %s\n", arm.name, arm.what);
    if (arm.prefill_chunk > 0)
        std::printf("         chunk %d tok\n", arm.prefill_chunk);
    if (arm.prefill_split_pct > 0)
        std::printf("         split at %d%% of the prompt — one boundary\n",
                    arm.prefill_split_pct);
    std::printf("  coverage layer L%d @ %.3f%s | %s\n", cov_layer, THR,
                std::getenv("DRIFT_THR") ? " (CANDIDATE operating point)" : "",
                en_only ? "ENGLISH ONLY (optimistic arm)"
                        : "EN + DE (the shipped, bilingual path)");

    const char* TASK = "\n\nExtract every fact from the email above into a flat JSON "
        "object of \"key\": \"value\" pairs. Use short snake_case keys — prefer keys like: "
        "customer, product, quantity, unit_price, total, order_date, delivery, order_number. "
        "Copy each value verbatim from the email. Output ONLY the JSON object, nothing else.";
    const std::vector<int> taps{cov_layer};

    // Restore the perturbation on EVERY exit path, not just the loop's happy
    // one: `fp` is shared with every other leg in this binary, and a leaked
    // prefill implementation would silently re-score whatever ran next. Same
    // class of bug as the lens drivers' EngineRestore, same one-line fix.
    struct ArmRestore {
        ForwardPassBase* fp;
        ForwardPassBase::AttnImpl impl;
        ~ArmRestore() { fp->set_prefill_attn_impl(impl); }
    } arm_restore{fp, fp->prefill_attn_impl()};

    struct DRec { std::string tag; double a, b, d; std::string text; bool de; };
    std::vector<DRec> recs;
    int n_docs = 0, n_diverged = 0, n_shape = 0, n_perturbed = 0;

    for (const QMessy& d : qdocs_messy_corpus()) {
        if (en_only && d.de) continue;
        n_docs++;
        const std::string prompt = qdocs_chat_prompt(d.document, TASK);

        FreeRun A = run_freegen(fp, sched, tok, meta, prompt, "", taps, 320, false, '}', 0);

        // Arm B under the candidate configuration, restored immediately after:
        // every other leg in this binary shares this forward pass and must not
        // inherit the perturbation. The tap set is untouched — only PREFILL
        // moves — because the lens reads decode rows and a flash decode would
        // have no kq_soft to read.
        if (arm.flash_prefill)
            fp->set_prefill_attn_impl(ForwardPassBase::AttnImpl::Flash);
        FreeRun B = run_freegen(fp, sched, tok, meta, prompt, "", taps, 320, false, '}',
                                arm.prefill_chunk, arm.prefill_split_pct);
        if (arm.flash_prefill)
            fp->set_prefill_attn_impl(ForwardPassBase::AttnImpl::Materialized);

        // Did arm B actually differ from arm A on this document? run_freegen
        // falls back to the single-batch path when the prompt is shorter than
        // the chunk, which would score the shipped path against itself and
        // report a perfect zero — the same vacuous pass the flash guard above
        // refuses, arriving by a quieter route.
        if (arm.flash_prefill || arm.prefill_split_pct > 0 ||
            (arm.prefill_chunk > 0 && A.P > arm.prefill_chunk))
            n_perturbed++;

        if (A.gen_tokens != B.gen_tokens) {
            n_diverged++;
            std::printf("  [%s] TOKENS DIVERGED (%zu vs %zu gen tokens) — excluded\n",
                        d.tag.c_str(), A.gen_tokens.size(), B.gen_tokens.size());
            continue;
        }
        int alo, ahi;
        if (!qdocs_span_in_prompt(tok, A, d.document, alo, ahi)) { alo = 0; ahi = A.P - 1; }
        std::vector<BandLine> la = band_body_lines(tok, A, alo, ahi, 0);
        std::vector<BandLine> lb = band_body_lines(tok, B, alo, ahi, 0);
        if (la.size() != lb.size()) { n_shape++; continue; }

        for (size_t i = 0; i < la.size(); ++i) {
            bool has = false;
            for (char c : la[i].text) if (std::isalnum((unsigned char)c)) has = true;
            if (!has) continue;
            recs.push_back({d.tag, la[i].peak, lb[i].peak,
                            std::fabs(la[i].peak - lb[i].peak), la[i].text, d.de});
        }
    }

    std::printf("\n  %d %s documents | %d token-diverged (excluded) | %d line-shape mismatch\n",
                n_docs, en_only ? "English" : "EN+DE", n_diverged, n_shape);
    if (recs.empty()) { std::printf("  no comparable lines — nothing to report\n"); return 1; }
    if (n_perturbed == 0) {
        std::fprintf(stderr,
            "drift gate: arm '%s' expected at least one document to take the "
            "perturbed path, actual 0 of %d — every prompt was shorter than the "
            "%d-token chunk, so both arms ran the shipped path and any PASS here "
            "would be vacuous\n", arm.name, n_docs, arm.prefill_chunk);
        return 1;
    }
    if (n_perturbed < n_docs)
        std::printf("  NOTE: %d of %d documents actually took the perturbed path\n",
                    n_perturbed, n_docs);

    std::vector<double> ds;
    for (auto& r : recs) ds.push_back(r.d);
    std::sort(ds.begin(), ds.end());
    auto q = [&](double f) { return ds[(size_t)(f * (ds.size() - 1))]; };

    int crossed = 0;
    for (auto& r : recs) if ((r.a >= THR) != (r.b >= THR)) crossed++;

    std::printf("\n  ---- drift over %zu body lines ----\n", recs.size());
    std::printf("    |delta peak|   p50 %.6f   p90 %.6f   p99 %.6f   MAX %.6f\n",
                q(0.50), q(0.90), q(0.99), ds.back());
    std::printf("    decisions that CROSSED %.3f : %d / %zu\n", THR, crossed, recs.size());

    std::printf("\n  ---- the 10 largest movers ----\n");
    std::sort(recs.begin(), recs.end(),
              [](const DRec& x, const DRec& y) { return x.d > y.d; });
    std::printf("  %-8s %9s %9s %10s  %s\n", "tag", "shipped", arm.name, "|delta|", "line");
    for (size_t i = 0; i < recs.size() && i < 10; ++i) {
        std::string t = recs[i].text;
        for (char& c : t) if (c == '\n' || c == '\r') c = ' ';
        if (t.size() > 46) t = t.substr(0, 46) + "...";
        std::printf("  %-8s %9.5f %9.5f %10.6f  %s%s\n",
                    recs[i].tag.c_str(), recs[i].a, recs[i].b, recs[i].d, t.c_str(),
                    ((recs[i].a >= THR) != (recs[i].b >= THR)) ? "   << CROSSED" : "");
    }

    // ── the budget ───────────────────────────────────────────────────────────
    // Measured, on the unit the drift is measured on: the closest any body
    // line in arm A comes to the threshold. A transform whose drift stays
    // under this could not have moved any decision on this corpus, and the
    // margin says how much room the NEXT document would have.
    double margin = 1e9, margin_en = 1e9, margin_de = 1e9;
    std::string nearest;
    int n_de_lines = 0;
    for (auto& r : recs) {
        const double m = std::fabs(r.a - THR);
        if (m < margin) { margin = m; nearest = r.text; }
        if (r.de) { n_de_lines++; if (m < margin_de) margin_de = m; }
        else if (m < margin_en) margin_en = m;
    }
    for (char& c : nearest) if (c == '\n' || c == '\r') c = ' ';
    if (nearest.size() > 46) nearest = nearest.substr(0, 46) + "...";

    const bool tokens_ok   = (n_diverged == 0);
    const bool nothing_crossed = (crossed == 0);
    const bool inside_budget   = (ds.back() < margin);
    const bool pass = tokens_ok && nothing_crossed && inside_budget;

    std::printf("\n  ---- GATE: arm B `%s` against the shipped arm ----\n", arm.name);
    std::printf("    1. token identity        : %d/%d documents        %s\n",
                n_docs - n_diverged, n_docs, tokens_ok ? "PASS" : "FAIL");
    std::printf("    2. decisions crossed     : %d / %zu lines          %s\n",
                crossed, recs.size(), nothing_crossed ? "PASS" : "FAIL");
    std::printf("    3. max drift vs margin   : %.6f vs %.6f   %s\n",
                ds.back(), margin, inside_budget ? "PASS" : "FAIL");
    std::printf("       line-level margin measured on %zu %s body lines; nearest line to %.3f:\n",
                recs.size(), en_only ? "EN" : "EN+DE", THR);
    std::printf("       \"%s\"\n", nearest.c_str());
    // The whole point of the language axis: which arm is setting the budget.
    if (n_de_lines > 0)
        std::printf("       by language: EN %.6f (%zu lines) | DE %.6f (%d lines)\n",
                    margin_en, recs.size() - (size_t)n_de_lines, margin_de, n_de_lines);
    const double headroom = (ds.back() > 0) ? margin / ds.back() : 1e9;
    if (inside_budget && ds.back() > 0) {
        std::printf("       headroom: %.1fx\n", headroom);
        // A pass with 1.5x of room is not the same statement as a pass with
        // 25x, and rounding them both to "2x" / "25x" hides which one you got.
        // Thin means: this corpus is clean, and a document whose line sits
        // closer to the threshold than the drift would not be protected.
        if (headroom < 5.0)
            std::printf("       ^^ THIN. Passing here says this corpus is clean, not that "
                        "the transform is safe.\n"
                        "          A line within %.6f of %.3f could be moved across by it.\n",
                        ds.back(), THR);
    }
    std::printf("\n  VERDICT: %s\n", pass
        ? "PASS — this transform moves no lens decision on this corpus"
        : "FAIL — do not ship this transform on the lens path without reading the rows above");
    return pass ? 0 : 1;
}

// ─────────────────────────────────────────────────────────────────────────────
// MOEROUTE — WHICH mechanism makes an MoE model irreproducible?
//
// The 2x2 (Qwen dense/MoE x Gemma dense/MoE, docs/plan-lens-server-shape.md
// §4.3) established that MoE-ness predicts instability under a chunked prefill:
// dense models drift ~8e-4 and never change a token, MoE models drift ~2.2e-2
// and each changed one extraction in fifteen. It did NOT establish why, and two
// mechanisms fit the same data with very different consequences:
//
//   ROUTING FLIP — top-k expert selection is an argmax, so a 1e-4 perturbation
//     picks a DIFFERENT EXPERT. Discrete, inherent to the architecture, not
//     fixable by better kernels.
//   DISPATCH ARITHMETIC — the same experts are chosen, and ggml_mul_mat_id
//     simply reduces differently at a different batch width. A kernel property:
//     bounded, possibly fixable, and not special to MoE except in degree.
//
// This leg separates them by reading the selection itself. `moe_idx.<il>` is
// already a named [top_k, n_tokens] I32 node in every MoE graph
// (layers/moe.cpp), so pinning it as a graph output costs no compute and needs
// no engine change — the same trick mark_attention_taps plays on kq_soft.
//
// Prefill only, no decode: the perturbation is a prefill-shape change, and
// prefill is where the two arms first differ. Head-less on BOTH arms so the
// output head cannot be confused for a difference (it is downstream of every
// router anyway).
//
// READING THE RESULT:
//   any position where the top-k SET differs        ⇒ routing flips are real
//   sets identical everywhere, outputs still differ ⇒ dispatch arithmetic
// The first flip's LAYER matters too: an early flip means the perturbation is
// amplified through the whole stack, a late one that it stayed small until the
// end.
// `moe_idx.<il>` is a ggml_view_2d of the argsort output — the top_k prefix of
// each token's full expert ranking, carrying the PARENT's row stride. Pinning
// and reading the view directly segfaults: ggml_backend_tensor_get copies
// ggml_nbytes() contiguous bytes, which for a strided view is neither the right
// bytes nor, at the last row, necessarily mapped memory. (Found the hard way —
// the first version of this leg died with no message.) So pin the contiguous
// PARENT and slice host-side, which also yields the full ranking for free.
struct MoePin { ggml_tensor* src; int il, top_k, n_exp, n_tok; };

// Must run AFTER build and BEFORE alloc, exactly like mark_attention_taps.
static std::vector<MoePin> moe_pin_idx(ggml_cgraph* gf, uint32_t n_blocks) {
    std::vector<MoePin> out;
    for (uint32_t il = 0; il < n_blocks; ++il) {
        const std::string nm = "moe_idx." + std::to_string(il);
        ggml_tensor* t = ggml_graph_get_tensor(gf, nm.c_str());
        if (!t) continue;
        ggml_tensor* src = t->view_src ? t->view_src : t;
        ggml_set_output(src);
        ggml_build_forward_expand(gf, src);
        out.push_back({src, (int)il, (int)t->ne[0], (int)src->ne[0], (int)t->ne[1]});
    }
    return out;
}

static void moe_read_idx(const std::vector<MoePin>& pins,
                         std::map<int, std::vector<int32_t>>& acc,
                         std::map<int, int>& top_k_of) {
    for (const MoePin& p : pins) {
        std::vector<int32_t> full((size_t)p.n_exp * p.n_tok);
        ggml_backend_tensor_get(p.src, full.data(), 0, ggml_nbytes(p.src));
        top_k_of[p.il] = p.top_k;
        std::vector<int32_t>& dst = acc[p.il];
        for (int t = 0; t < p.n_tok; ++t) {
            const int32_t* row = full.data() + (size_t)t * p.n_exp;
            dst.insert(dst.end(), row, row + p.top_k);
        }
    }
}

// One prefill of `toks`, single-batch or chunked, returning the routing it took.
// Head-less throughout: routing is upstream of the head.
static std::map<int, std::vector<int32_t>>
moe_prefill_routing(ForwardPassBase* fp, ggml_backend_sched_t sched,
                    const ModelMetadata& meta, const std::vector<int32_t>& toks,
                    int chunk, std::map<int, int>& top_k_of, int split_pct = 0) {
    std::map<int, std::vector<int32_t>> acc;
    fp->clear_slot(0);
    fp->set_cache_pos(0, 0);

    auto one_pass = [&](const std::vector<int32_t>& part, int pos) {
        ggml_backend_sched_reset(sched);
        ggml_cgraph* gf = fp->build_prefill_graph(part, pos, 0, /*want_logits=*/false);
        std::vector<MoePin> pins = moe_pin_idx(gf, meta.block_count);
        ggml_backend_sched_alloc_graph(sched, gf);
        fp->set_prefill_inputs(gf, part, pos);
        qinf::engine::require_compute_success(
            ggml_backend_sched_graph_compute(sched, gf), "moe_prefill_routing");
        moe_read_idx(pins, acc, top_k_of);
        fp->advance_cache((uint32_t)part.size(), 0);
    };

    const int P = (int)toks.size();
    const std::vector<int> cuts = prefill_cuts(P, chunk, split_pct);
    if (cuts.empty()) {
        one_pass(toks, 0);
    } else {
        int pos = 0;
        for (int cut : cuts) {
            one_pass(std::vector<int32_t>(toks.begin() + pos, toks.begin() + cut), pos);
            pos = cut;
        }
        one_pass(std::vector<int32_t>(toks.begin() + pos, toks.end()), pos);
    }
    fp->clear_slot(0);
    fp->set_cache_pos(0, 0);
    return acc;
}

static int run_moe_route_probe(ForwardPassBase* fp, ggml_backend_sched_t sched,
                               Tokenizer* tok, const ModelMetadata& meta) {
    int CH = 128;
    if (const char* c = std::getenv("ATTN_BAND_CHUNK")) CH = std::atoi(c);
    // ATTN_BAND_SPLIT_PCT drives arm B as the WARM PREFIX CACHE shape — ONE
    // boundary at that fraction of the prompt — instead of fixed-width
    // chunking. That is the shape the shipped caches actually produce, and the
    // fraction is the product variable (system-prompt hit ~5%, long chat ~90%).
    int SPLIT = 0;
    if (const char* c = std::getenv("ATTN_BAND_SPLIT_PCT")) SPLIT = std::atoi(c);

    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ MOEROUTE — routing flip, or dispatch arithmetic?              ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");
    if (SPLIT > 0)
        std::printf("  arch %s | %u blocks | WARM-CACHE SPLIT at %d%% (one boundary) | "
                    "prefill only, head-less\n",
                    meta.architecture.c_str(), meta.block_count, SPLIT);
    else
        std::printf("  arch %s | %u blocks | chunk %d tok | prefill only, head-less\n",
                    meta.architecture.c_str(), meta.block_count, CH);

    const char* TASK = "\n\nExtract every fact from the email above into a flat JSON "
        "object of \"key\": \"value\" pairs. Use short snake_case keys — prefer keys like: "
        "customer, product, quantity, unit_price, total, order_date, delivery, order_number. "
        "Copy each value verbatim from the email. Output ONLY the JSON object, nothing else.";

    long long tot_pos = 0, set_diff = 0, order_diff = 0;
    int first_layer = -1, first_pos = -1, docs_with_flip = 0, n_docs = 0;
    std::string first_tag, first_a, first_b;
    std::map<int, long long> flips_by_layer;

    for (const QMessy& d : qdocs_messy_corpus()) {
        const std::string prompt = qdocs_chat_prompt(d.document, TASK);
        std::vector<int32_t> toks = tok->encode(prompt);
        // Vacuous only in chunk mode: a split at a percentage always cuts.
        if (SPLIT <= 0 && (int)toks.size() <= CH) continue;
        n_docs++;
        if (const char* m = std::getenv("MOEROUTE_MAX"))
            if (n_docs > std::atoi(m)) { n_docs--; break; }

        // Flushed per step: this leg aborted silently once, and a buffered
        // stdout discards exactly the line that would have said where.
        std::printf("  [%s] %d prompt tokens, arm A...", d.tag.c_str(), (int)toks.size());
        std::fflush(stdout);
        std::map<int, int> tkA, tkB;
        std::map<int, std::vector<int32_t>> A =
            moe_prefill_routing(fp, sched, meta, toks, 0, tkA, 0);
        std::printf(" arm B..."); std::fflush(stdout);
        std::map<int, std::vector<int32_t>> B =
            moe_prefill_routing(fp, sched, meta, toks,
                                SPLIT > 0 ? 0 : CH, tkB, SPLIT);
        std::printf(" compared."); std::fflush(stdout);

        if (A.empty()) {
            std::fprintf(stderr,
                "MOEROUTE: expected at least one `moe_idx.<il>` node, actual 0 — "
                "arch '%s' is not a mixture-of-experts recipe, so there is no "
                "routing to compare\n", meta.architecture.c_str());
            return 1;
        }

        bool doc_flip = false;
        for (const auto& kv : A) {
            const int il = kv.first;
            if (!B.count(il) || tkA[il] != tkB[il]) continue;
            const int K = tkA[il];
            const std::vector<int32_t>& a = kv.second;
            const std::vector<int32_t>& b = B.at(il);
            const size_t n = std::min(a.size(), b.size()) / (size_t)K;
            for (size_t t = 0; t < n; ++t) {
                const int32_t* pa = a.data() + t * K;
                const int32_t* pb = b.data() + t * K;
                tot_pos++;
                if (std::equal(pa, pa + K, pb)) continue;
                std::vector<int32_t> sa(pa, pa + K), sb(pb, pb + K);
                std::sort(sa.begin(), sa.end()); std::sort(sb.begin(), sb.end());
                if (sa == sb) { order_diff++; continue; }
                set_diff++;
                flips_by_layer[il]++;
                doc_flip = true;
                if (first_layer < 0) {
                    first_layer = il; first_pos = (int)t; first_tag = d.tag;
                    for (int k = 0; k < K; ++k) {
                        first_a += (k ? "," : "") + std::to_string(pa[k]);
                        first_b += (k ? "," : "") + std::to_string(pb[k]);
                    }
                }
            }
        }
        if (doc_flip) docs_with_flip++;
        std::printf(" %s\n", doc_flip ? "routing DIFFERS" : "routing identical");
        std::fflush(stdout);
    }

    std::printf("\n  ---- %lld (layer, token) routing decisions compared over %d documents ----\n",
                tot_pos, n_docs);
    std::printf("    different expert SET   : %lld  (%.4f%%)\n",
                set_diff, tot_pos ? 100.0 * (double)set_diff / (double)tot_pos : 0.0);
    std::printf("    same set, different ORDER: %lld\n", order_diff);
    std::printf("    documents with at least one flip: %d / %d\n", docs_with_flip, n_docs);

    if (set_diff > 0) {
        std::printf("\n    first flip: %s layer %d token %d — experts [%s] vs [%s]\n",
                    first_tag.c_str(), first_layer, first_pos,
                    first_a.c_str(), first_b.c_str());
        std::printf("    flips by layer (top 10):\n");
        std::vector<std::pair<int, long long>> v(flips_by_layer.begin(), flips_by_layer.end());
        std::sort(v.begin(), v.end(),
                  [](const std::pair<int,long long>& x, const std::pair<int,long long>& y) {
                      return x.second > y.second; });
        for (size_t i = 0; i < v.size() && i < 10; ++i)
            std::printf("      L%-3d %lld\n", v[i].first, v[i].second);
        std::printf("\n  VERDICT: ROUTING FLIPS ARE REAL. The perturbation changes WHICH\n"
                    "           expert runs, not just how its arithmetic rounds. This is\n"
                    "           inherent to top-k selection and no kernel fixes it.\n");
    } else {
        std::printf("\n  VERDICT: ROUTING IS IDENTICAL on this corpus. Every token took the\n"
                    "           same experts in both arms, so the divergence measured by the\n"
                    "           drift gate comes from the DISPATCH ARITHMETIC (mul_mat_id\n"
                    "           reducing differently at a different batch width), not from\n"
                    "           selection — a kernel property, not an architectural one.\n");
    }
    return 0;
}

// ═════════════════════════════════════════════════════════════════════════
// PINREPLAY — if expert SELECTION is held fixed, does a prefill-shape change
// still move the answer?
//
// The one measurement Movement 3 rests on and that nobody had run
// (plan-lens-only-engine.md §3; note-moe-cache-transparency.md §6). We know a
// prefill-shape change flips 1–6% of top-k selections on an MoE and moves 2 of
// 15 extractions. We do NOT know that PINNING the selection fixes it: the
// ~1e-4 arithmetic difference survives pinning, and only its harmlessness on
// DENSE stacks (0 of 15) suggests the residue is safe. That is an inference.
//
// If pinning does not collapse the divergence, Movement 3 is dead everywhere —
// receipt, prefix cache and batched decode alike — and no architecture
// decision is needed. Worth a day of probe work before it is worth a seam.
//
// MECHANISM. This drives the SHIPPED seam, not a probe trick:
// DecodePolicy::routing_replay -> MoELayer/gemma4 build the top-k operand as a
// graph input instead of an argsort -> RoutingReplayInput fills it. Capture is
// the mirror of the attention taps: mark_moe_routing(gf) before alloc,
// read_moe_routing(gf, trace, pos) after compute.
//
// It did NOT start that way. The first version did graph surgery from here
// (neuter the argsort to GGML_OP_NONE and write the ranking into its buffer),
// which is how the seam was proven worth cutting before it was cut. Two
// failures on the way are worth remembering, because both produced confident
// wrong output: a NaN-blind comparator scored an all-NaN arm as a perfect
// match, and GGML_TENSOR_FLAG_OUTPUT stopped the buffer being FREED but not
// REUSED, so compute overwrote the ids with another tensor's floats. The
// engine path avoids both by construction — ggml_set_input on a real graph
// input is exactly the allocator contract those two bugs were groping for.
//
// Note what is NOT pinned: the router LOGITS still compute, and the gating
// weights are still gathered at the pinned indices. Only the discrete
// selection is replayed — exactly Movement 3's claim, not a broader freeze.
//
// PREFILL ONLY, deliberately. The perturbation is a prefill-shape change;
// decode shape is identical in both arms. The LOGITS at the last prompt
// position are the decision the whole generation hangs from: if they agree
// bitwise the generation cannot diverge, and if they do not, this reports by
// how much without 320 tokens of amplification in the way.
//
// FOUR ARMS per document, all compared against A:
//   A    single-batch prefill, free routing        — the shipped path
//   A'   single-batch prefill, REPLAY A's routing  — CONTROL, must be bitwise A
//   B    shape-changed prefill, free routing       — the known-bad arm
//   B'   shape-changed prefill, REPLAY A's routing — the question
//
// A' is not optional: it is the only thing standing between "pinning works"
// and "the graph surgery silently did nothing", and it fails the leg loud.
//
// READING THE RESULT:
//   B' bitwise identical to A                    ⇒ pinning collapses it fully
//   B' top-1 agrees, |dlogit| in the dense band  ⇒ pinning works in the sense
//                                                  that matters (a decision)
//   B' ≈ B                                       ⇒ pinning buys nothing
// The dense band is not a guess — run this leg on a DENSE model and its own
// B-vs-A max |dlogit| is the number pinning has to reach.
// Restores the replay pointer on EVERY exit path: `fp` is shared with every
// other leg in this binary, and a leaked replay trace would silently re-route
// whatever ran next. Same class of bug as the drift leg's ArmRestore.
struct ReplayRestore {
    ForwardPassBase* fp;
    ~ReplayRestore() { fp->set_routing_replay(nullptr); }
};

// One prefill of `toks` in the given shape, through the SHIPPED seam:
// `replay` non-null builds every MoE layer with RoutingSource::Replay and lets
// RoutingReplayInput fill the operand; `record` non-null marks and reads the
// selections the pass actually took. Returns the logits at the final position.
static std::vector<float>
pin_prefill(ForwardPassBase* fp, ggml_backend_sched_t sched,
            const ModelMetadata& /*meta*/, const std::vector<int32_t>& toks,
            int chunk, int split_pct,
            const RoutingTrace* replay, RoutingTrace* record)
{
    if (replay && record)
        throw std::runtime_error(
            "pin_prefill: expected at most one of replay/record, actual: both — a "
            "replayed pass has no computed selection to capture");
    ReplayRestore restore{fp};
    fp->set_routing_replay(replay);
    fp->clear_slot(0);
    fp->set_cache_pos(0, 0);
    std::vector<float> logits;

    auto one_pass = [&](const std::vector<int32_t>& part, int pos, bool want_logits) {
        ggml_backend_sched_reset(sched);
        ggml_cgraph* gf = fp->build_prefill_graph(part, pos, 0, want_logits);
        if (record) fp->mark_moe_routing(gf);   // before alloc, like the taps
        fp->alloc_readback_graph(sched, gf);
        fp->set_prefill_inputs(gf, part, pos);
        qinf::engine::require_compute_success(
            ggml_backend_sched_graph_compute(sched, gf), "pin_prefill");
        if (record) fp->read_moe_routing(gf, *record, pos);
        if (std::getenv("PINREPLAY_DEBUG") && (record || replay)) {
            // Check EVERY layer, not just the first: a seam that fills one slot
            // correctly and leaves 29 as garbage looks identical at layer 0.
            const RoutingTrace* tr = record ? record : replay;
            const char* pfx = replay ? "moe_routing." : "moe_idx.";
            int present = 0, matched = 0, absent = 0;
            std::string first_bad;
            for (const auto& kv : tr->by_layer()) {
                ggml_tensor* t = ggml_graph_get_tensor(
                    gf, (pfx + std::to_string(kv.first)).c_str());
                if (!t) { absent++; continue; }
                present++;
                ggml_tensor* src = t->view_src ? t->view_src : t;
                std::vector<int32_t> raw((size_t)ggml_nelements(src));
                ggml_backend_tensor_get(src, raw.data(), 0, ggml_nbytes(src));
                const int stride = (int)src->ne[0];
                bool ok = true;
                for (int r = 0; r < (int)t->ne[1] && ok; ++r) {
                    const int32_t* want = tr->at(kv.first, (size_t)(pos + r));
                    for (int k = 0; k < tr->top_k(); ++k)
                        if (raw[(size_t)r * stride + k] != want[k]) { ok = false; break; }
                }
                if (ok) matched++;
                else if (first_bad.empty()) first_bad = std::to_string(kv.first);
            }
            std::printf("    [dbg] %-7s rows=%zu  slots present %d / absent %d / "
                        "matching trace %d%s\n",
                        replay ? "REPLAY" : "CAPTURE", (size_t)part.size(),
                        present, absent, matched,
                        first_bad.empty() ? "" : ("  first mismatch at layer " + first_bad).c_str());
            std::fflush(stdout);
        }
        if (want_logits) logits = fp->get_output_logits(gf);
        fp->advance_cache((uint32_t)part.size(), 0);
    };

    const int P = (int)toks.size();
    int pos = 0;
    for (int cut : prefill_cuts(P, chunk, split_pct)) {
        one_pass(std::vector<int32_t>(toks.begin() + pos, toks.begin() + cut), pos, false);
        pos = cut;
    }
    one_pass(std::vector<int32_t>(toks.begin() + pos, toks.end()), pos, true);
    fp->clear_slot(0);
    fp->set_cache_pos(0, 0);
    return logits;
}

// Fail loud on a non-finite logit. This is not defensive padding: the first
// version of this leg compared arms with std::max(m, |a-b|), and since
// std::max(x, NaN) returns x, an arm that came back entirely NaN scored a
// PERFECT ZERO against every other arm — including the control, whose whole
// job is to catch a broken mechanism. The leg printed "pinning COLLAPSES the
// drift completely" off a garbage buffer. A comparator that cannot see NaN
// cannot see failure.
static void logit_require_finite(const std::vector<float>& v, const char* arm) {
    if (v.empty())
        throw std::runtime_error(
            std::string("pin_prefill arm '") + arm +
            "': expected a non-empty logit vector, actual 0 entries");
    for (size_t i = 0; i < v.size(); ++i)
        if (!std::isfinite(v[i]))
            throw std::runtime_error(
                std::string("pin_prefill arm '") + arm +
                "': expected finite logits, actual " + std::to_string(v[i]) +
                " at index " + std::to_string(i) + " of " + std::to_string(v.size()));
}

static double logit_maxabs(const std::vector<float>& a, const std::vector<float>& b) {
    if (a.size() != b.size())
        throw std::runtime_error(
            "logit_maxabs: expected equal logit vectors, actual " +
            std::to_string(a.size()) + " vs " + std::to_string(b.size()));
    double m = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        const double d = std::fabs((double)a[i] - (double)b[i]);
        if (!std::isfinite(d))
            throw std::runtime_error(
                "logit_maxabs: expected a finite difference, actual " +
                std::to_string(d) + " at index " + std::to_string(i));
        if (d > m) m = d;
    }
    return m;
}
static int logit_top1(const std::vector<float>& v) {
    int b = 0;
    for (int i = 1; i < (int)v.size(); ++i) if (v[i] > v[b]) b = i;
    return b;
}

static int run_pin_replay_probe(ForwardPassBase* fp, ggml_backend_sched_t sched,
                                Tokenizer* tok, const ModelMetadata& meta)
{
    int SPLIT = 10, CH = 0;
    if (const char* c = std::getenv("ATTN_BAND_SPLIT_PCT")) SPLIT = std::atoi(c);
    if (const char* c = std::getenv("ATTN_BAND_CHUNK"))     { CH = std::atoi(c); SPLIT = 0; }

    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ PINREPLAY — does pinning expert selection collapse the drift? ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");
    std::printf("  arch %s | %u blocks | arm B = %s | prefill only, last-position logits\n",
                meta.architecture.c_str(), meta.block_count,
                SPLIT > 0 ? ("warm split at " + std::to_string(SPLIT) + "%").c_str()
                          : ("chunk " + std::to_string(CH) + " tok").c_str());

    const char* TASK = "\n\nExtract every fact from the email above into a flat JSON "
        "object of \"key\": \"value\" pairs. Use short snake_case keys — prefer keys like: "
        "customer, product, quantity, unit_price, total, order_date, delivery, order_number. "
        "Copy each value verbatim from the email. Output ONLY the JSON object, nothing else.";

    int n_docs = 0, ctrl_bad = 0, det_bad = 0, bp_exact = 0, bp_top1_ok = 0, b_top1_ok = 0;
    bool is_moe = true;
    std::vector<double> dB, dBp;

    std::printf("\n  %-8s %12s %12s %12s %12s   %s\n",
                "doc", "A2 vs A", "A'vs A", "B vs A", "B' vs A", "top-1 (B / B')");
    for (const QMessy& d : qdocs_messy_corpus()) {
        const std::string prompt = qdocs_chat_prompt(d.document, TASK);
        std::vector<int32_t> toks = tok->encode(prompt);
        if (CH > 0 && (int)toks.size() <= CH) continue;
        if (const char* m = std::getenv("PINREPLAY_MAX"))
            if (n_docs >= std::atoi(m)) break;
        n_docs++;

        RoutingTrace R;
        std::vector<float> A = pin_prefill(fp, sched, meta, toks, 0, 0, nullptr, &R);
        logit_require_finite(A, "A  (single-batch, free routing)");
        is_moe = !R.empty();

        // DETERMINISM CONTROL, before anything is pinned: the SAME shape with
        // the SAME free routing, run twice. It must be bitwise zero on every
        // model. Without it, a replay arm that differs cannot be told apart
        // from a harness that simply does not reproduce itself — which is
        // exactly the ambiguity the first cross-family run left.
        std::vector<float> A2 = pin_prefill(fp, sched, meta, toks, 0, 0, nullptr, nullptr);
        logit_require_finite(A2, "A2 (single-batch, free routing, repeated)");
        const double dA2 = logit_maxabs(A, A2);

        std::vector<float> B = pin_prefill(fp, sched, meta, toks, CH, SPLIT, nullptr, nullptr);
        logit_require_finite(B, "B  (shape-changed, free routing)");
        const double db = logit_maxabs(A, B);
        dB.push_back(db);
        const int t0 = logit_top1(A);
        const bool bt = logit_top1(B) == t0;
        if (bt) b_top1_ok++;

        if (!is_moe) {   // DENSE reference: no selection exists to pin
            std::printf("  %-8s %12.3e %12s %12.3e %12s   %s / %s\n",
                        d.tag.c_str(), dA2, "n/a", db, "n/a", bt ? "same" : "DIFF", "n/a");
            std::fflush(stdout);
            continue;
        }

        std::vector<float> Ap = pin_prefill(fp, sched, meta, toks, 0, 0, &R, nullptr);
        std::vector<float> Bp = pin_prefill(fp, sched, meta, toks, CH, SPLIT, &R, nullptr);
        logit_require_finite(Ap, "A' (single-batch, replayed routing)");
        logit_require_finite(Bp, "B' (shape-changed, replayed routing)");

        const double dA  = logit_maxabs(A, Ap);
        const double dbp = logit_maxabs(A, Bp);
        dBp.push_back(dbp);
        if (dA != 0.0) ctrl_bad++;
        if (dbp == 0.0) bp_exact++;
        const bool bpt = logit_top1(Bp) == t0;
        if (bpt) bp_top1_ok++;
        std::printf("  %-8s %12.3e %12.3e %12.3e %12.3e   %s / %s%s\n",
                    d.tag.c_str(), dA2, dA, db, dbp,
                    bt ? "same" : "DIFF", bpt ? "same" : "DIFF",
                    dA2 != 0.0 ? "   <<< NOT REPRODUCIBLE"
                               : (dA != 0.0 ? "   <<< REPLAY BROKEN" : ""));
        if (dA2 != 0.0) det_bad++;
        std::fflush(stdout);
    }

    if (n_docs == 0) { std::printf("  no documents ran\n"); return 1; }

    auto med0 = [](std::vector<double> v) {
        std::sort(v.begin(), v.end()); return v.empty() ? 0.0 : v[v.size() / 2];
    };
    if (!is_moe) {
        std::printf("\n  ---- DENSE REFERENCE (%d documents, arch %s) ----\n",
                    n_docs, meta.architecture.c_str());
        std::printf("    max |dlogit| vs A, free routing : median %.3e  worst %.3e\n",
                    med0(dB), *std::max_element(dB.begin(), dB.end()));
        std::printf("    top-1 token agrees with A       : %d / %d\n", b_top1_ok, n_docs);
        std::printf("\n  This is the band a pinned MoE has to reach: a dense stack takes the\n"
                    "  SAME prefill-shape change and this is all it moves. Nothing here is\n"
                    "  pinned — a dense model has no selection to pin.\n");
        return 0;
    }

    std::printf("\n  ---- CONTROLS ----\n");
    if (det_bad) {
        std::fprintf(stderr,
            "PINREPLAY determinism: expected 0 of %d documents to differ when the SAME "
            "pass is repeated with the SAME free routing, actual %d — this harness does "
            "not reproduce itself on this model, so nothing about REPLAY can be "
            "concluded from it. Fix reproducibility before reading the pinned arms.\n",
            n_docs, det_bad);
        return 1;
    }
    std::printf("    determinism (A2, repeated free pass) : %d/%d bitwise identical\n",
                n_docs, n_docs);
    if (ctrl_bad) {
        std::fprintf(stderr,
            "PINREPLAY control: expected 0 of %d documents to differ when the SAME "
            "prefill shape replays its own routing, actual %d — the replay mechanism "
            "is not pinning what it claims to, so every number above is meaningless\n",
            n_docs, ctrl_bad);
        return 1;
    }
    std::printf("    %d/%d documents bitwise identical — the replay mechanism works\n",
                n_docs, n_docs);

    auto med = [](std::vector<double> v) {
        std::sort(v.begin(), v.end()); return v.empty() ? 0.0 : v[v.size() / 2];
    };
    const double mB = med(dB), mBp = med(dBp);
    const double xB = *std::max_element(dB.begin(), dB.end());
    const double xBp = *std::max_element(dBp.begin(), dBp.end());

    std::printf("\n  ---- does pinning collapse it? (%d documents) ----\n", n_docs);
    std::printf("    max |dlogit| vs A   free routing (B) : median %.3e  worst %.3e\n", mB, xB);
    std::printf("                        pinned     (B'): median %.3e  worst %.3e\n", mBp, xBp);
    std::printf("    reduction                            : median %.2fx  worst %.2fx\n",
                mBp > 0 ? mB / mBp : 0.0, xBp > 0 ? xB / xBp : 0.0);
    std::printf("    B' bitwise identical to A            : %d / %d\n", bp_exact, n_docs);
    std::printf("    top-1 token agrees with A            : B %d/%d | B' %d/%d\n",
                b_top1_ok, n_docs, bp_top1_ok, n_docs);

    // The bar is the FAMILY'S OWN DENSE BAND, supplied by running this leg on a
    // dense model of the same family and passing its `worst` here. A reduction
    // RATIO is the wrong criterion and said so out loud once: Gemma 4's pinned
    // arm was called "DOES NOT FIX IT" at 3.67x when it had in fact landed
    // BELOW its dense reference (0.714 vs 1.054). Raw |dlogit| is not
    // comparable across families — Gemma's dense stack drifts ~76x more than
    // Qwen's under the identical perturbation — so there is no universal
    // threshold to hard-code, and a ratio only measures how bad the unpinned
    // arm was.
    const char* dref = std::getenv("PINREPLAY_DENSE_WORST");
    std::printf("\n  VERDICT: ");
    if (bp_exact == n_docs) {
        std::printf("pinning COLLAPSES the drift completely — B' is bitwise A.\n");
    } else if (dref) {
        const double band = std::atof(dref);
        std::printf("pinned worst %.3e vs this family's DENSE band %.3e (%.2fx).\n",
                    xBp, band, band > 0 ? xBp / band : 0.0);
        std::printf("           %s\n",
                    xBp <= band
                        ? "IN THE DENSE BAND — pinning puts this MoE where dense models\n"
                          "           already sit, which is the regime that passes the drift gate."
                        : "ABOVE THE DENSE BAND — the arithmetic residue alone still moves\n"
                          "           more than a dense stack does. Pinning is not sufficient here.");
        std::printf("           (unpinned was %.3e; top-1 agreed %d/%d pinned)\n",
                    xB, bp_top1_ok, n_docs);
    } else {
        std::printf("pinned worst %.3e vs unpinned %.3e (%.2fx), top-1 %d/%d.\n"
                    "           NO VERDICT: run this leg on a DENSE model of the SAME\n"
                    "           family and pass its `worst` as PINREPLAY_DENSE_WORST.\n"
                    "           A reduction ratio cannot tell you whether this is safe.\n",
                    xBp, xB, xBp > 0 ? xB / xBp : 0.0, bp_top1_ok, n_docs);
    }
    return 0;
}

struct CovSpanRec {
    std::string tag, marker;
    bool de   = false;            // Leg C language split (COV1 records leave it false)
    int label = -1;               // 1 = consulted (positive), 0 = not (negative)
    int len   = 0;                // span length in tokens
    int lo = -1, hi = -1;         // token span in the prompt
    std::string text;             // the span's decoded text (filler audit)
    std::vector<double> peak;     // per attention-layer-slot span peak
};

// span_scalars indexes per-layer sources at sc[1+slot], so it
// can only express the first 10 tapped layers. Both calibrated Qwen models put
// attention every 4th block (8 and 10 layers), so this never fires there — it
// is the guard for the day a denser model is calibrated, because silently
// searching a truncated layer list would report a winner picked from a subset.
static void covsearch_require_expressible(const std::vector<int32_t>& attn_layers) {
    if ((int)attn_layers.size() > SC_MAX_SLOTS)
        throw std::runtime_error(
            "COVSEARCH attn_layers: expected at most " + std::to_string(SC_MAX_SLOTS) +
            " tapped attention layers (span_scalars stores per-layer sources at "
            "sc[1+slot]), actual " +
            std::to_string(attn_layers.size()) + " — widen SC_MAX_SLOTS before searching");
}

static std::vector<double> covsearch_peaks(const FreeRun& R, int lo, int hi,
                                           const std::vector<int32_t>& attn_layers) {
    double sc[SC_N][4];
    span_scalars(R, lo, hi, sc, attn_layers);
    std::vector<double> v((int)attn_layers.size());
    for (int s = 0; s < (int)attn_layers.size(); ++s) v[s] = sc[1 + s][0];
    return v;
}

// ── ARM 1 — COV1 separation curve. The only corpus with a HARD negative: a
// span the model was asked about and declined to use.
static void covsearch_arm1(ForwardPassBase* fp, ggml_backend_sched_t sched,
                           Tokenizer* tok, const ModelMetadata& meta,
                           const std::vector<int32_t>& attn_layers,
                           std::vector<CovSpanRec>& cal, std::vector<CovSpanRec>& hel) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ COVSEARCH ARM 1 — COV1 separation curve (hard negatives)      ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");
    std::vector<int> taps(attn_layers.begin(), attn_layers.end());
    auto run_set = [&](std::vector<CovPrompt> set, std::vector<CovSpanRec>& out) {
        for (auto& cp : set) {
            FreeRun R = run_freegen(fp, sched, tok, meta, cp.body, cp.instr,
                                    taps, 320, false, cp.close);
            std::string gt = R.gen_text; for (char& c : gt) if (c == '\n') c = ' ';
            if (gt.size() > 110) gt = gt.substr(0, 110) + "...";
            std::printf("[%s] gen=%zu  %s\n", cp.tag.c_str(), R.gen_tokens.size(), gt.c_str());
            for (auto& tg : cp.tg) {
                if (tg.cls != CT_TARGET) continue;   // anchors are not labelled USED/DROPPED
                int lo, hi;
                if (!find_token_span(tok, R.prompt_tokens, cp.body, tg.marker, lo, hi)) {
                    std::printf("  WARN marker not found: %s\n", tg.marker.c_str());
                    continue;
                }
                CovSpanRec r;
                r.tag = cp.tag; r.marker = tg.marker; r.len = hi - lo + 1;
                r.label = R.gen_text.find(tg.used) != std::string::npos ? 1 : 0;
                r.peak = covsearch_peaks(R, lo, hi, attn_layers);
                out.push_back(r);
            }
        }
    };
    std::printf("\n---- calib ----\n");  run_set(cov_calib(), cal);
    std::printf("---- held ----\n");     run_set(cov_held(),  hel);
}

// ── ARM 2 — Leg C ambient curve. Positives are the exact 75-span population
// the >=90% bar is quoted on. Negatives are LENGTH-MATCHED filler windows:
// the span peak sums attention mass over the span, so a longer negative scores
// higher for free, and comparing short values against whole filler lines would
// measure length, not consultation.
// ATTN_LENS_EN_ONLY=1 restricts Leg C to the English documents. NOT a
// convenience filter: the German deficit is a property of the MODEL's German
// competence, not of the lens signal, so pooling the two halves reports a
// number that is neither the lens ceiling nor the model's. English-only is the
// CEILING arm — what the omission report achieves when language competence is
// not the binding constraint. Quote it as a ceiling, never as the shipped rate.
static bool band_en_only() {
    static const bool v = std::getenv("ATTN_LENS_EN_ONLY") != nullptr;
    return v;
}

// ── The product defect (found 2026-09-13) ───────────────────────────────────
// Leg C's filler negatives are cut from any document position outside a
// LABELLED value's span. But the TASK prompt every arm uses says:
//
//   "prefer keys like: customer, PRODUCT, quantity, unit_price, total, ..."
//
// `product` is asked for and the model extracts it — correctly — yet no
// document labels it. So the product name sits in filler territory, the model
// attends to it for the right reason, and the span is scored as a FALSE
// POSITIVE. Measured on English: 3 of the incumbent's 9 filler-clears are
// product names (m_en2 0.973, m_en4 0.994, m_en6 0.994). The matched-FPR pin
// that COVSEARCH uses to select layers is therefore pinned to a partly
// fictional quantity.
//
// `product` is the ONLY such gap: every other key in the TASK list is either
// labelled where the document states it, or absent from the document entirely.
//
// OPT-IN (ATTN_PRODUCT_OCCUPIED=1) on purpose. qdocs_messy_corpus() is shared
// by leg C, the S2/S3 thread work and QKEY; editing it would silently rewrite
// their stored comparison points. With the flag off, every leg is byte-identical.
//
// Occupancy ONLY — the product is NOT added as a positive. That keeps the
// recall denominator at its published value so the change isolates the filler
// population, which is the half that is broken. English only: the flag exists
// to measure the EN ceiling (see band_en_only) and the German products were
// not transcribed.
// Mark EVERY occurrence of a labelled value occupied, not just the first
// (see qdocs_all_spans_in_prompt). Opt-in and independent of the product flag
// so the two negative-set defects can be attributed separately.
static bool all_occurrences_occupied() {
    static const bool v = std::getenv("ATTN_ALL_OCCURRENCES") != nullptr;
    return v;
}
static bool product_occupied() {
    static const bool v = std::getenv("ATTN_PRODUCT_OCCUPIED") != nullptr;
    return v;
}
static const char* qdocs_product_for(const std::string& tag) {
    if (tag == "m_en1") return "Matte Black Easel Stand";
    if (tag == "m_en2") return "Nitrile Exam Gloves";
    if (tag == "m_en3") return "galvanised coach bolt 10mm";
    if (tag == "m_en4") return "Cold-Pressed Coconut Oil";
    if (tag == "m_en5") return "Insulated Flask 750ml";
    if (tag == "m_en6") return "Stainless Cleat 6in";
    if (tag == "m_en7") return "Anti-Reflective Lens Blank";
    if (tag == "m_en8") return "Rubber Grip Tape";
    return nullptr;   // German documents: not transcribed, no extra occupancy
}

static void covsearch_arm2(ForwardPassBase* fp, ggml_backend_sched_t sched,
                           Tokenizer* tok, const ModelMetadata& meta,
                           const std::vector<int32_t>& attn_layers,
                           std::vector<CovSpanRec>& out, int& cite_n, int& cite_t1, int& cite_t3) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ COVSEARCH ARM 2 — Leg C ambient curve (length-matched filler) ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");
    const int TOL = 2;
    const std::vector<std::string>& vocab = tok->get_vocabulary();
    const uint32_t vocab_size = (uint32_t)vocab.size();
    qinf::TokenTrie trie; trie.build(vocab);
    auto gr = qinf::GrammarVocab::parse_impl(QDOCS_GBNF);
    gr->set_token_trie(&trie);
    std::vector<int> taps(attn_layers.begin(), attn_layers.end());
    // Byte-identical to run_qdocs_leg_c's TASK — Arm 2's positives must be the
    // same population leg C reports, or the gate compares two different things.
    const char* TASK = "\n\nExtract every fact from the email above into a flat JSON "
        "object of \"key\": \"value\" pairs. Use short snake_case keys — prefer keys like: "
        "customer, product, quantity, unit_price, total, order_date, delivery, order_number. "
        "Copy each value verbatim from the email. Output ONLY the JSON object, nothing else.";

    cite_n = cite_t1 = cite_t3 = 0;
    int neg_skipped = 0;
    for (const QMessy& d : qdocs_messy_corpus()) {
        if (band_en_only() && d.de) continue;   // CEILING arm — see band_en_only()
        std::string prompt = qdocs_chat_prompt(d.document, TASK);
        std::vector<GStep> tr;
        FreeRun R = run_freegen_grammar(fp, sched, tok, meta, prompt, "", taps,
                                        320, gr.get(), vocab, vocab_size, &tr);
        int doc_lo, doc_hi;
        if (!qdocs_span_in_prompt(tok, R, d.document, doc_lo, doc_hi)) { doc_lo = 0; doc_hi = R.P - 1; }

        // Positives, and the occupancy map the negatives are cut around.
        std::vector<char> occupied(R.P, 0);
        std::vector<std::pair<int,int>> pos_spans;   // (lo,hi) of every labelled value found
        std::vector<CovSpanRec> pos;
        // Keep the product out of filler territory — it is asked for by the
        // TASK prompt and extracted correctly, so a decoy cut on it is not a
        // decoy. Occupancy only: it does not become a positive.
        if (product_occupied()) {
            if (const char* prod = qdocs_product_for(d.tag)) {
                int plo, phi;
                if (qdocs_span_in_prompt(tok, R, prod, plo, phi))
                    for (int p = std::max(0, plo - TOL); p <= std::min(R.P - 1, phi + TOL); ++p)
                        occupied[p] = 1;
                if (all_occurrences_occupied())
                    for (auto& sp : qdocs_all_spans_in_prompt(tok, R, prod))
                        for (int p = std::max(0, sp.first - TOL);
                             p <= std::min(R.P - 1, sp.second + TOL); ++p) occupied[p] = 1;
            }
        }
        for (const QLabel& f : d.fields) {
            int slo, shi;
            if (!qdocs_span_in_prompt(tok, R, f.value, slo, shi)) continue;  // leg C skips these too
            for (int p = std::max(0, slo - TOL); p <= std::min(R.P - 1, shi + TOL); ++p) occupied[p] = 1;
            // The POSITIVE record still uses the first occurrence (what leg C
            // scores); only OCCUPANCY widens to every restatement.
            if (all_occurrences_occupied())
                for (auto& sp : qdocs_all_spans_in_prompt(tok, R, f.value))
                    for (int p = std::max(0, sp.first - TOL);
                         p <= std::min(R.P - 1, sp.second + TOL); ++p) occupied[p] = 1;
            pos_spans.push_back({slo, shi});
            CovSpanRec r;
            r.tag = d.tag; r.de = d.de; r.marker = f.concept; r.label = 1; r.len = shi - slo + 1;
            r.lo = slo; r.hi = shi;
            r.text = tok->decode(std::vector<int32_t>(R.prompt_tokens.begin() + slo,
                                                      R.prompt_tokens.begin() + shi + 1));
            r.peak = covsearch_peaks(R, slo, shi, attn_layers);
            pos.push_back(r);
            // Citation propagation check (plan §7 G4) — same head, same scorer
            // as leg C, so the printed top-1/top-3 must reproduce the known run.
            QFieldEval e = qdocs_eval_field(tok, R, f.value, doc_lo, doc_hi, attn_layers, TOL);
            cite_n += e.cite_n; cite_t1 += e.cite_t1; cite_t3 += e.cite_t3;
        }

        // Eligible filler = document positions inside no labelled value's span
        // (plus TOL margin). Position 0 is excluded: it is the attention sink
        // and carries mass for reasons that have nothing to do with coverage.
        std::vector<std::pair<int,int>> runs;   // (start, len) of contiguous eligible positions
        {
            int p = std::max(1, doc_lo), lim = std::min(R.P - 1, doc_hi);
            while (p <= lim) {
                if (occupied[p]) { ++p; continue; }
                int s0 = p; while (p <= lim && !occupied[p]) ++p;
                runs.push_back({s0, p - s0});
            }
        }
        // Deterministic cut: walk the runs with a cursor, never reusing a
        // position, so each positive gets its own distinct length-matched twin.
        size_t ri = 0; int roff = 0, nfiller = 0;
        for (const CovSpanRec& P : pos) {
            int L = P.len;
            while (ri < runs.size() && runs[ri].second - roff < L) { ++ri; roff = 0; }
            if (ri >= runs.size()) { neg_skipped++; continue; }
            int nlo = runs[ri].first + roff, nhi = nlo + L - 1;
            roff += L;
            CovSpanRec n;
            n.tag = d.tag; n.de = d.de; n.marker = "filler:" + P.marker; n.label = 0; n.len = L;
            n.lo = nlo; n.hi = nhi;
            n.text = tok->decode(std::vector<int32_t>(R.prompt_tokens.begin() + nlo,
                                                      R.prompt_tokens.begin() + nhi + 1));
            n.peak = covsearch_peaks(R, nlo, nhi, attn_layers);
            out.push_back(n);
            nfiller++;
        }
        for (const CovSpanRec& P : pos) out.push_back(P);
        std::printf("  [%s%s] positives %zu  filler %d  eligible runs %zu\n",
                    d.tag.c_str(), d.de ? " DE" : "", pos.size(), nfiller, runs.size());
    }
    if (neg_skipped)
        std::printf("  NOTE: %d positive(s) had no length-matched filler window available\n", neg_skipped);
}

// ═════════════════════════════════════════════════════════════════════════
// COVCOMBINE — does COMBINING tapped layers beat the best SINGLE layer?
//
// Single-layer selection has been searched to exhaustion and keeps returning
// KEEP: on English L7 is 37/40 against the incumbent L11's 36/40 (one span,
// n=40, noise) and the §7 candidate L3 buys 98% recall by taking filler-clear
// from 24% to 38%. The untried direction is combining layers, and it needs no
// engine change — the probe already taps every full-attention layer.
//
// WHY A VOTE AND NOT max/mean ACROSS LAYERS.  Per-layer peaks are on different
// scales: the matched-FPR thresholds run 0.586 (L3) to 0.919 (L27). A raw max
// across layers is therefore dominated by whichever layer runs hottest and
// collapses to L27 alone; a raw mean is dominated the same way. So every layer
// votes against ITS OWN threshold and we count votes — scale-free by
// construction, and parameter-free once (subset, k, r) are fixed.
//
// OPERATING POINT IS PINNED, NOT FITTED.  `r` is how many filler spans each
// layer admits individually; sweeping r moves all thresholds together. We keep
// the largest r whose COMBINED filler-clear stays at or below the incumbent's
// own filler count. So no combiner may buy used-clear with silent misses —
// the same discipline as the MATCHED-FPR table (plan-coverage-layer-search §6).
//
// THIS IS A SEARCH AND IT IS SCORED AS ONE.  Subsets are pre-declared (not
// swept over 2^8) and the winner must survive a DOCUMENT split-half: choose
// (k,r) on one half of the documents, score on the other. EN-only leaves no
// DE half, so the document split is the substitute for the EN/DE stability
// test. A candidate that wins pooled but not cross-half is a fit, not a find.
struct CombSpec { const char* name; std::vector<int> slots; };

static int run_coverage_combiner(ForwardPassBase* fp, ggml_backend_sched_t sched,
                                 Tokenizer* tok, const ModelMetadata& meta,
                                 const std::vector<int32_t>& attn_layers) {
    const int S = (int)attn_layers.size();
    const double THR = 0.705;
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ COVCOMBINE — multi-layer vote vs the best single layer        ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");
    if (!band_en_only())
        std::printf("  NOTE: pooled EN+DE. Set ATTN_LENS_EN_ONLY=1 for the ceiling arm.\n");

    std::vector<CovSpanRec> cal, hel, legc;
    int cite_n = 0, cite_t1 = 0, cite_t3 = 0;
    covsearch_arm2(fp, sched, tok, meta, attn_layers, legc, cite_n, cite_t1, cite_t3);

    // Incumbent's own operating point on this population — the pin.
    int target_fp = 0, n_pos = 0, n_neg = 0;
    for (auto& r : legc) {
        if (r.label == 1) { n_pos++; continue; }
        n_neg++;
        if (r.peak[L11_SLOT] >= THR) target_fp++;
    }
    int inc_used = 0;
    for (auto& r : legc) if (r.label == 1 && r.peak[L11_SLOT] >= THR) inc_used++;
    std::printf("\n  population %zu spans (%d positive / %d filler)\n", legc.size(), n_pos, n_neg);
    std::printf("  incumbent L%d @ %.3f : used %d/%d = %.0f%%   filler %d/%d = %.0f%%  << the pin\n",
                attn_layers[L11_SLOT], THR, inc_used, n_pos, 100.0 * inc_used / n_pos,
                target_fp, n_neg, 100.0 * target_fp / n_neg);

    // Per-layer thresholds admitting exactly r fillers, from the filler
    // distribution of whichever span set is in scope.
    auto thresholds_for = [&](const std::vector<CovSpanRec>& v, int slot, int r) {
        std::vector<double> f;
        for (auto& x : v) if (x.label == 0) f.push_back(x.peak[slot]);
        std::sort(f.begin(), f.end(), std::greater<double>());
        if (r <= 0) return 1e9;
        if (r > (int)f.size()) return -1e9;
        return f[r - 1];
    };
    // Evaluate one (subset,k,r) on a span set: {used, filler}.
    auto eval = [&](const std::vector<CovSpanRec>& v, const std::vector<CovSpanRec>& fit,
                    const std::vector<int>& slots, int k, int r) {
        std::vector<double> t;
        for (int sl : slots) t.push_back(thresholds_for(fit, sl, r));
        int u = 0, fl = 0;
        for (auto& x : v) {
            int votes = 0;
            for (size_t i = 0; i < slots.size(); ++i)
                if (x.peak[slots[i]] >= t[i]) votes++;
            const bool on = votes >= k;
            if (x.label == 1) { if (on) u++; }
            else              { if (on) fl++; }
        }
        return std::pair<int,int>(u, fl);
    };

    auto slot_of = [&](int layer) {
        for (int i = 0; i < S; ++i) if (attn_layers[i] == layer) return i;
        return -1;
    };
    std::vector<CombSpec> specs = {
        {"L11 (control)",      {slot_of(11)}},
        {"L7+L11",             {slot_of(7), slot_of(11)}},
        {"L3+L11",             {slot_of(3), slot_of(11)}},
        {"L3+L7+L11",          {slot_of(3), slot_of(7), slot_of(11)}},
        {"L3+L7+L11+L23",      {slot_of(3), slot_of(7), slot_of(11), slot_of(23)}},
        {"all attention",      {}},
    };
    for (int i = 0; i < S; ++i) specs.back().slots.push_back(i);
    for (auto& sp : specs)
        for (int sl : sp.slots)
            if (sl < 0) throw std::runtime_error("COVCOMBINE: a named layer is not tapped by this model");

    // Pick (k,r) maximising used-clear subject to filler <= the incumbent's.
    auto best_kr = [&](const std::vector<CovSpanRec>& fitset, const std::vector<int>& slots,
                       int cap, int& bk, int& br) {
        int bu = -1; bk = 1; br = 0;
        for (int k = 1; k <= (int)slots.size(); ++k)
            for (int r = 0; r <= n_neg; ++r) {
                auto uf = eval(fitset, fitset, slots, k, r);
                if (uf.second > cap) continue;
                if (uf.first > bu) { bu = uf.first; bk = k; br = r; }
            }
        return bu;
    };

    // Dump the scored spans so validation design can be iterated WITHOUT
    // re-running inference. One corpus pass, then arbitrary offline analysis —
    // the split-half defect below is exactly the kind of thing that needs
    // several attempts to get right, and each attempt should not cost a GPU run.
    if (const char* dp = std::getenv("COVCOMBINE_DUMP")) {
        FILE* f = std::fopen(dp, "w");
        if (!f) throw std::runtime_error(std::string("COVCOMBINE_DUMP: cannot open ") + dp);
        std::fprintf(f, "tag,marker,de,label,len,lo,hi,text");
        for (int i = 0; i < S; ++i) std::fprintf(f, ",L%d", attn_layers[i]);
        std::fprintf(f, "\n");
        for (auto& r : legc) {
            std::string tx = r.text;
            for (char& c : tx) if (c == ',' || c == '\n' || c == '\r') c = ' ';
            std::fprintf(f, "%s,%s,%d,%d,%d,%d,%d,%s", r.tag.c_str(), r.marker.c_str(),
                         r.de ? 1 : 0, r.label, r.len, r.lo, r.hi, tx.c_str());
            for (int i = 0; i < S; ++i) std::fprintf(f, ",%.6f", r.peak[i]);
            std::fprintf(f, "\n");
        }
        std::fclose(f);
        std::printf("\n  [dump] %zu spans -> %s\n", legc.size(), dp);
    }

    std::printf("\n  ---- pooled (fit and scored on the same %zu spans) ----\n", legc.size());
    std::printf("  %-18s %3s %4s %14s %14s\n", "combiner", "k", "r", "used-clear", "filler-clear");
    for (auto& sp : specs) {
        int k, r;
        best_kr(legc, sp.slots, target_fp, k, r);
        auto uf = eval(legc, legc, sp.slots, k, r);
        std::printf("  %-18s %3d %4d %7d/%-3d %3.0f%% %7d/%-3d %3.0f%%%s\n",
                    sp.name, k, r, uf.first, n_pos, 100.0 * uf.first / n_pos,
                    uf.second, n_neg, 100.0 * uf.second / n_neg,
                    uf.first > inc_used ? "   << beats incumbent" : "");
    }

    // ── DOCUMENT SPLIT-HALF: choose on one half, score on the other ──────────
    std::vector<std::string> tags;
    for (auto& r : legc)
        if (std::find(tags.begin(), tags.end(), r.tag) == tags.end()) tags.push_back(r.tag);
    std::sort(tags.begin(), tags.end());
    std::vector<CovSpanRec> hA, hB;
    for (auto& r : legc) {
        size_t i = (size_t)(std::find(tags.begin(), tags.end(), r.tag) - tags.begin());
        (i % 2 ? hB : hA).push_back(r);
    }
    auto npos_of = [](const std::vector<CovSpanRec>& v) {
        int n = 0; for (auto& r : v) if (r.label == 1) n++; return n; };
    auto nneg_of = [](const std::vector<CovSpanRec>& v) {
        int n = 0; for (auto& r : v) if (r.label == 0) n++; return n; };
    auto cap_of = [&](const std::vector<CovSpanRec>& v) {
        int n = 0; for (auto& r : v) if (r.label == 0 && r.peak[L11_SLOT] >= THR) n++; return n; };

    std::printf("\n  ---- DOCUMENT split-half: FIT on one half, SCORE on the other ----\n");
    std::printf("  half A %zu spans (%d pos) | half B %zu spans (%d pos)  [%zu documents]\n",
                hA.size(), npos_of(hA), hB.size(), npos_of(hB), tags.size());
    std::printf("  %-18s %16s %16s\n", "combiner", "fit A -> score B", "fit B -> score A");
    for (auto& sp : specs) {
        int ka, ra, kb, rb;
        best_kr(hA, sp.slots, cap_of(hA), ka, ra);
        best_kr(hB, sp.slots, cap_of(hB), kb, rb);
        auto ab = eval(hB, hA, sp.slots, ka, ra);
        auto ba = eval(hA, hB, sp.slots, kb, rb);
        std::printf("  %-18s   %4d/%-3d f%-3d   %4d/%-3d f%-3d\n",
                    sp.name, ab.first, npos_of(hB), ab.second,
                    ba.first, npos_of(hA), ba.second);
    }
    std::printf("\n  read: a combiner is REAL only if it beats the incumbent pooled AND\n"
                "  holds up in BOTH out-of-sample columns. Beating pooled alone is a fit.\n"
                "  (f = filler spans admitted out-of-sample; compare against %d/%d pooled.)\n",
                target_fp, n_neg);
    return 0;
}

static int run_coverage_layer_search(ForwardPassBase* fp, ggml_backend_sched_t sched,
                                     Tokenizer* tok, const ModelMetadata& meta,
                                     const std::vector<int32_t>& attn_layers) {
    covsearch_require_expressible(attn_layers);
    const int S = (int)attn_layers.size();
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ COVSEARCH — coverage layer x threshold search                 ║\n");
    std::printf("║ docs/plan-coverage-layer-search.md — selection rule is §6      ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");
    if (band_en_only())
        std::printf("  *** ENGLISH-ONLY (ATTN_LENS_EN_ONLY=1) — CEILING ARM, not the shipped rate ***\n");
    std::printf("  candidate layers (%d):", S);
    for (int s = 0; s < S; ++s) std::printf(" %d", attn_layers[s]);
    std::printf("   |  incumbent: layer %d @ 0.705 (slot %d)\n", attn_layers[L11_SLOT], L11_SLOT);

    std::vector<CovSpanRec> cal, hel, legc;
    int cite_n = 0, cite_t1 = 0, cite_t3 = 0;
    covsearch_arm1(fp, sched, tok, meta, attn_layers, cal, hel);
    covsearch_arm2(fp, sched, tok, meta, attn_layers, legc, cite_n, cite_t1, cite_t3);

    auto pairs = [&](const std::vector<CovSpanRec>& v, int s) {
        std::vector<std::pair<double, bool>> d;
        for (auto& r : v) d.push_back({r.peak[s], r.label == 1});
        return d;
    };
    auto med_of = [&](const std::vector<CovSpanRec>& v, int s, int lab) {
        std::vector<double> x; for (auto& r : v) if (r.label == lab) x.push_back(r.peak[s]);
        return median(x);
    };
    auto npos = [&](const std::vector<CovSpanRec>& v) {
        int n = 0; for (auto& r : v) if (r.label == 1) n++; return n; };

    std::vector<CovSpanRec> cov_all = cal; cov_all.insert(cov_all.end(), hel.begin(), hel.end());
    std::printf("\n  COV1  calib %zu spans (%d USED)  held %zu (%d USED)   |   "
                "Leg C %zu spans (%d positive)\n",
                cal.size(), npos(cal), hel.size(), npos(hel), legc.size(), npos(legc));

    // ── Arm 1 curve ──────────────────────────────────────────────────────────
    std::printf("\n---- ARM 1: COV1 separation per layer (hard negatives) ----\n");
    std::printf("  %-7s %9s %9s %9s   %9s %9s\n",
                "layer", "AUC calib", "AUC held", "AUC pool", "med USED", "med DROP");
    std::vector<double> auc_held(S), auc_pool(S);
    for (int s = 0; s < S; ++s) {
        auc_held[s] = auc_of(pairs(hel, s));
        auc_pool[s] = auc_of(pairs(cov_all, s));
        std::printf("  L%-6d %9.3f %9.3f %9.3f   %9.3f %9.3f%s\n",
                    attn_layers[s], auc_of(pairs(cal, s)), auc_held[s], auc_pool[s],
                    med_of(cov_all, s, 1), med_of(cov_all, s, 0),
                    s == L11_SLOT ? "   << incumbent" : "");
    }

    // ── Arm 2 curve ──────────────────────────────────────────────────────────
    std::printf("\n---- ARM 2: Leg C separation per layer (ambient, length-matched) ----\n");
    std::printf("  %-7s %9s   %9s %9s\n", "layer", "AUC legC", "med value", "med filler");
    std::vector<double> auc_legc(S);
    for (int s = 0; s < S; ++s) {
        auc_legc[s] = auc_of(pairs(legc, s));
        std::printf("  L%-6d %9.3f   %9.3f %9.3f%s\n",
                    attn_layers[s], auc_legc[s], med_of(legc, s, 1), med_of(legc, s, 0),
                    s == L11_SLOT ? "   << incumbent" : "");
    }

    // ── The decisive comparison: used-clear at MATCHED filler-clear ──────────
    // AUC ranks layers over every operating point at once, and the two rate
    // columns above are each read at a DIFFERENT point, so neither answers the
    // only question that moves a constant: at the incumbent's own false-positive
    // rate, does any layer report more of the genuinely-consulted spans? The
    // operating point here is PINNED by the incumbent (admit exactly as many
    // filler spans as layer 11 @ 0.705 does) and is therefore not fitted — no
    // layer gets to buy used-clear with silent misses, which is exactly how the
    // §7 candidate reached 99%.
    int inc_fp = 0, n_neg = 0, n_pos = 0;
    for (auto& r : legc) {
        if (r.label == 1) { n_pos++; continue; }
        n_neg++;
        if (r.peak[L11_SLOT] >= 0.705) inc_fp++;
    }
    std::printf("\n---- MATCHED-FPR: used-clear when every layer admits %d/%d filler spans ----\n",
                inc_fp, n_neg);
    std::printf("  (operating point pinned by the incumbent, not fitted)\n");
    std::printf("  %-7s %10s %14s %14s\n", "layer", "threshold", "filler-clear", "used-clear");
    int best_m = -1, best_m_clear = -1;
    std::vector<int> mfpr_uc((size_t)S, 0);      // pooled matched-FPR used-clear, per layer
    for (int s = 0; s < S; ++s) {
        std::vector<double> neg;
        for (auto& r : legc) if (r.label == 0) neg.push_back(r.peak[s]);
        std::sort(neg.begin(), neg.end(), std::greater<double>());
        // Admit the inc_fp highest-scoring filler spans; ties can push the
        // realised count above inc_fp, so the achieved rate is printed, never assumed.
        double t = (inc_fp > 0 && inc_fp <= (int)neg.size()) ? neg[inc_fp - 1]
                 : (neg.empty() ? 0.0 : neg.front() + 1e-6);
        int fc = 0, uc = 0;
        for (auto& r : legc) {
            if (r.peak[s] < t) continue;
            if (r.label == 1) uc++; else fc++;
        }
        std::printf("  L%-6d %10.3f %9d/%-4d %9d/%-4d  %5.0f%%%s\n",
                    attn_layers[s], t, fc, n_neg, uc, n_pos, n_pos ? 100.0 * uc / n_pos : 0,
                    s == L11_SLOT ? "   << incumbent" : "");
        mfpr_uc[(size_t)s] = uc;
        if (uc > best_m_clear) { best_m_clear = uc; best_m = s; }
    }
    std::printf("  >>> best at matched FPR: layer %d (%d/%d = %.0f%%)   incumbent layer %d\n",
                attn_layers[best_m], best_m_clear, n_pos,
                n_pos ? 100.0 * best_m_clear / n_pos : 0, attn_layers[L11_SLOT]);

    // ── Split-half stability. The winner above was chosen on Leg C and scored
    // on Leg C: 8 candidates against 75 positives, which is far better than the
    // incumbent's 48-against-12 but is still selection and evaluation on one
    // corpus. EN (8 docs) and DE (7 docs) are disjoint halves of it, so a layer
    // that wins BOTH independently is not a fluke of which spans we happened to
    // have. Each half re-pins its own operating point to the incumbent's rate on
    // that half — comparing halves at a shared threshold would smuggle the
    // pooled fit back in.
    std::printf("\n---- MATCHED-FPR split-half stability (EN %d docs / DE %d docs) ----\n", 8, 7);
    std::printf("  %-7s %18s %18s\n", "layer", "EN used-clear", "DE used-clear");
    int win_en = -1, win_de = -1, bc_en = -1, bc_de = -1;
    std::vector<int> uc_en((size_t)S, 0), uc_de((size_t)S, 0);
    int np_en = 0, np_de = 0;
    for (int s = 0; s < S; ++s) {
        int uc[2] = {0, 0}, np[2] = {0, 0};
        for (int half = 0; half < 2; ++half) {
            const bool want_de = (half == 1);
            std::vector<double> neg;
            int fp_here = 0;
            for (auto& r : legc) {
                if (r.de != want_de) continue;
                if (r.label == 1) { np[half]++; continue; }
                neg.push_back(r.peak[s]);
                if (r.peak[L11_SLOT] >= 0.705) fp_here++;
            }
            std::sort(neg.begin(), neg.end(), std::greater<double>());
            double t = (fp_here > 0 && fp_here <= (int)neg.size()) ? neg[fp_here - 1]
                     : (neg.empty() ? 0.0 : neg.front() + 1e-6);
            for (auto& r : legc)
                if (r.de == want_de && r.label == 1 && r.peak[s] >= t) uc[half]++;
        }
        std::printf("  L%-6d %11d/%-4d %11d/%-4d   %3.0f%% / %3.0f%%%s\n",
                    attn_layers[s], uc[0], np[0], uc[1], np[1],
                    np[0] ? 100.0 * uc[0] / np[0] : 0, np[1] ? 100.0 * uc[1] / np[1] : 0,
                    s == L11_SLOT ? "   << incumbent" : "");
        uc_en[(size_t)s] = uc[0]; uc_de[(size_t)s] = uc[1];
        np_en = np[0]; np_de = np[1];
        if (uc[0] > bc_en) { bc_en = uc[0]; win_en = s; }
        if (uc[1] > bc_de) { bc_de = uc[1]; win_de = s; }
    }
    std::printf("  >>> EN winner: layer %d    DE winner: layer %d    => %s\n",
                attn_layers[win_en], attn_layers[win_de],
                win_en == win_de ? "AGREE (the winner survives a disjoint split)"
                                 : "DISAGREE — the pooled winner is not stable across halves");

    // ── §6 selection — rebuilt 2026-09-14, because the old one could not fail ─
    //
    // It used to select on Arm 1 HELD AUC and require a neighbour to beat the
    // median AUC. Run bilingually on the corrected negatives, both calibrated
    // models printed `best held AUC 1.000, median 1.000`: the metric is
    // SATURATED, so no layer can strictly beat the median and the plateau test
    // failed by construction — on the candidate AND on every alternative. A
    // test whose outcome is fixed by its metric's ceiling is not a test, and it
    // was reporting FAIL for a reason that had nothing to do with the layer.
    //
    // The replacement uses the split the corpus already has. EN (8 documents)
    // and DE (7 documents) are disjoint, each re-pins its own operating point
    // to the incumbent's filler rate on that half, and each carries enough
    // positives (40 / 35) not to saturate. So:
    //
    //   SELECT on one language, SCORE on the other, in BOTH directions.
    //
    // That is genuinely out-of-sample, it cannot be satisfied by a layer that
    // wins on one language and collapses on the other — which is exactly what
    // the 9B's L7 does (98% EN, 51% DE) and what an English-only harness said
    // was a win — and it is STRICTER than what it replaces, not looser. The
    // AUC line is still printed, as a diagnostic, labelled for what it is.
    const int inc_pool = mfpr_uc[(size_t)L11_SLOT];
    int best = best_m;                       // pooled matched-FPR winner
    double med_auc = median(auc_held);
    std::printf("\n---- §6 SELECTION (matched-FPR, cross-language) ----\n");
    int auc_best = 0;
    for (int s = 1; s < S; ++s) if (auc_held[s] > auc_held[auc_best]) auc_best = s;
    std::printf("  diagnostic only, NOT a gate: best held AUC layer %d (%.3f), median %.3f%s\n",
                attn_layers[auc_best], auc_held[auc_best], med_auc,
                (auc_held[auc_best] >= 0.999 && med_auc >= 0.999)
                    ? "  << SATURATED — this is why it is no longer a criterion" : "");

    // Cross-half generalisation: the layer chosen on one language must beat the
    // incumbent ON THE OTHER, both ways, and the two halves must choose the
    // same layer.
    const bool en_to_de = uc_de[(size_t)win_en] > uc_de[(size_t)L11_SLOT];
    const bool de_to_en = uc_en[(size_t)win_de] > uc_en[(size_t)L11_SLOT];
    const bool halves_agree = (win_en == win_de);
    std::printf("  select on EN (L%d) -> score on DE: %d/%d vs incumbent %d/%d  %s\n",
                attn_layers[win_en], uc_de[(size_t)win_en], np_de,
                uc_de[(size_t)L11_SLOT], np_de, en_to_de ? "BEATS" : "does not beat");
    std::printf("  select on DE (L%d) -> score on EN: %d/%d vs incumbent %d/%d  %s\n",
                attn_layers[win_de], uc_en[(size_t)win_de], np_en,
                uc_en[(size_t)L11_SLOT], np_en,
                de_to_en ? "BEATS"
                         : (win_de == L11_SLOT ? "does not beat (this half's winner IS the incumbent"
                                                 " — it fields no challenger)"
                                               : "does not beat"));
    std::printf("  the two halves %s on a winner\n",
                halves_agree ? "AGREE" : "DISAGREE");

    // Plateau, re-based on the same quantity the decision is made on: an
    // ADJACENT layer must also beat the incumbent at the matched budget. A real
    // signal occupies a region of the stack; one layer alone on 75 spans is a
    // coincidence until a neighbour corroborates it.
    const bool nb_lo = best > 0     && mfpr_uc[(size_t)best - 1] > inc_pool;
    const bool nb_hi = best + 1 < S && mfpr_uc[(size_t)best + 1] > inc_pool;
    const bool plateau = nb_lo || nb_hi;
    {
        std::string nb;
        if (nb_lo) nb += "L" + std::to_string(attn_layers[best - 1]);
        if (nb_hi) { if (!nb.empty()) nb += " and "; nb += "L" + std::to_string(attn_layers[best + 1]); }
        std::printf("  plateau (a neighbour of L%d must also beat the incumbent at matched FPR): %s%s%s\n",
                    attn_layers[best], plateau ? "PASS — " : "FAIL",
                    plateau ? nb.c_str() : " — lone spike",
                    plateau ? "" : "");
    }

    Thr thr = best_threshold(pairs(cal, best));   // calib split ONLY
    std::printf("  threshold on the COV1 CALIB split only: %.3f dir%+d (calib acc %.0f%%)\n",
                thr.t, thr.dir, 100 * thr.acc);

    // ── §7 gate, scored on Arm 2 (which chose nothing) ───────────────────────
    auto rates = [&](int s, double t, int dir, int& pc, int& pn, int& nc, int& nn) {
        pc = pn = nc = nn = 0;
        for (auto& r : legc) {
            bool clear = dir > 0 ? r.peak[s] >= t : r.peak[s] <= t;
            if (r.label == 1) { pn++; if (clear) pc++; } else { nn++; if (clear) nc++; }
        }
    };
    int cpc, cpn, cnc, cnn, fpc, fpn, fnc, fnn;
    rates(best,      thr.t, thr.dir, cpc, cpn, cnc, cnn);
    rates(L11_SLOT,  0.705, +1,      fpc, fpn, fnc, fnn);
    auto pc100 = [](int a, int b) { return b ? 100.0 * a / b : 0.0; };
    std::printf("\n---- §7 GATE — out-of-sample on Leg C ----\n");
    std::printf("  %-34s %14s %14s\n", "", "used-clear", "filler-clear");
    std::printf("  incumbent  L%-2d @ 0.705          %9d/%-4d %9d/%-4d\n",
                attn_layers[L11_SLOT], fpc, fpn, fnc, fnn);
    std::printf("  %-34s %11.0f%%   %11.0f%%\n", "", pc100(fpc, fpn), pc100(fnc, fnn));
    std::printf("  candidate  L%-2d @ %.3f dir%+d     %9d/%-4d %9d/%-4d\n",
                attn_layers[best], thr.t, thr.dir, cpc, cpn, cnc, cnn);
    std::printf("  %-34s %11.0f%%   %11.0f%%\n", "", pc100(cpc, cpn), pc100(cnc, cnn));

    // ── The criteria ─────────────────────────────────────────────────────────
    // G2 changed 2026-09-14. It used to compare the candidate's filler-clear at
    // its FITTED threshold against the incumbent's at 0.705 — two different
    // operating points, so a candidate was penalised for where its threshold
    // happened to land rather than for what it can do. The matched-FPR table
    // above already pins both to the same filler budget; G2 now reads that,
    // and demands the win survive being chosen on one language and scored on
    // the other. Strictly harder than what it replaces: the old G2 could be
    // passed by a layer that never generalises across the split.
    bool g1 = pc100(cpc, cpn) >= 90.0;
    bool g2 = halves_agree && en_to_de && de_to_en;
    bool g3 = plateau;
    double t3 = pc100(cite_t3, cite_n);
    std::printf("\n  G1 used-clear >=90%%            : %s (%.0f%%)\n", g1 ? "PASS" : "FAIL", pc100(cpc, cpn));
    std::printf("  G2 beats incumbent at matched FPR, cross-language : %s\n", g2 ? "PASS" : "FAIL");
    std::printf("       (pooled: candidate L%d %d/%d vs incumbent L%d %d/%d)\n",
                attn_layers[best], mfpr_uc[(size_t)best], n_pos,
                attn_layers[L11_SLOT], inc_pool, n_pos);
    std::printf("  G3 plateau at matched FPR      : %s\n", g3 ? "PASS" : "FAIL");
    std::printf("  G4 citation unchanged (L%dH%d)  : top1 %.1f%%  top3 %.1f%%  over %d value tokens\n"
                "     (propagation check — compare against the known leg C run for this model)\n",
                attn_layers[FROZEN_SLOT], FROZEN_HEAD, pc100(cite_t1, cite_n), t3, cite_n);
    std::printf("\n── COVSEARCH VERDICT: %s ──\n",
                (g1 && g2 && g3) ? "candidate clears G1-G3 — record it, then re-run on the other "
                                   "calibrated model AND through the drift gate "
                                   "(BANDDRIFT, plan-lens-server-shape.md §4.4) before moving "
                                   "any constant"
                                 : "KEEP layer 11 @ 0.705 — the candidate did not clear the gate");

    // ── BAND COST — what decision stability costs at the shipped threshold ────
    // The v5 "decision stability" proposal publishes a BAND around the coverage
    // threshold inside which our own arithmetic cannot resolve the span:
    //     |peak - 0.705| <= band  =>  "borderline", not "skipped"/"consulted".
    //
    // That question has two halves and they are separable:
    //   COST        how many of the report's decisions a band of width w
    //               withdraws. Needs NO config change — measured here.
    //   REQUIREMENT how far peaks actually MOVE under a config change we intend
    //               to permit (flash prefill, batch shape, driver). Needs a
    //               perturbation; measured separately.
    //
    // The decisive number is the ZERO-COST BAND: the smallest |peak - 0.705|
    // over all scored spans. Any band narrower than that withdraws nothing at
    // all, so it is exactly the drift we can absorb for free. If it is wide, we
    // can pick a generous band NOW and be safe against drift not yet measured.
    //
    // Population is Leg C (out-of-sample: labelled values + length-matched
    // filler negatives), scored at the incumbent slot — the same spans and the
    // same scalar the §7 gate above reports.
    {
        const double THR = 0.705;
        std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
        std::printf("║ BAND COST — decision stability at L%-2d @ %.3f                  ║\n",
                    attn_layers[L11_SLOT], THR);
        std::printf("╚══════════════════════════════════════════════════════════════╝\n");

        struct BRec { double peak, dist; int label; const char* tag; const char* marker; bool de; };
        std::vector<BRec> br;
        for (auto& r : legc)
            br.push_back({r.peak[L11_SLOT], std::fabs(r.peak[L11_SLOT] - THR),
                          r.label, r.tag.c_str(), r.marker.c_str(), r.de});
        std::sort(br.begin(), br.end(),
                  [](const BRec& a, const BRec& b) { return a.dist < b.dist; });

        int tot = (int)br.size(), P = 0, N = 0, cur_skipped = 0;
        for (auto& b : br) { if (b.label == 1) P++; else N++; if (b.peak < THR) cur_skipped++; }
        std::printf("  population: %d spans (%d positive / %d filler) | currently in skipped[] : %d\n",
                    tot, P, N, cur_skipped);

        // Peak distribution — is the mass bimodal AROUND the threshold, or piled ON it?
        auto qtile = [&](int lab, double q) {
            std::vector<double> x;
            for (auto& r : legc) if (r.label == lab) x.push_back(r.peak[L11_SLOT]);
            if (x.empty()) return 0.0;
            std::sort(x.begin(), x.end());
            size_t i = (size_t)(q * (x.size() - 1));
            return x[i];
        };
        std::printf("\n  peak distribution at L%d           p05     p25     p50     p75     p95\n",
                    attn_layers[L11_SLOT]);
        std::printf("    positive (consulted)         %7.3f %7.3f %7.3f %7.3f %7.3f\n",
                    qtile(1, 0.05), qtile(1, 0.25), qtile(1, 0.50), qtile(1, 0.75), qtile(1, 0.95));
        std::printf("    filler   (not consulted)     %7.3f %7.3f %7.3f %7.3f %7.3f\n",
                    qtile(0, 0.05), qtile(0, 0.25), qtile(0, 0.50), qtile(0, 0.75), qtile(0, 0.95));

        std::printf("\n  ZERO-COST BAND = %.4f   (nearest span to the threshold)\n",
                    br.empty() ? 0.0 : br[0].dist);

        std::printf("\n  ---- the %d spans closest to %.3f (these flip first) ----\n",
                    (int)std::min<size_t>(12, br.size()), THR);
        std::printf("  %-8s %-3s %-18s %-9s %7s %8s\n", "tag", "lg", "marker", "label", "peak", "dist");
        for (size_t i = 0; i < br.size() && i < 12; ++i)
            std::printf("  %-8s %-3s %-18s %-9s %7.4f %8.4f\n",
                        br[i].tag, br[i].de ? "de" : "en", br[i].marker,
                        br[i].label == 1 ? "positive" : "filler", br[i].peak, br[i].dist);

        // Recall without its false-positive rate is not a ceiling. The
        // split-half table above splits used-clear by language but NOT
        // filler-clear, so this is the missing half.
        {
            int up = 0, un = 0, fpn = 0, fnn = 0;
            for (auto& r : legc) {
                const bool clear = r.peak[L11_SLOT] >= THR;
                if (r.label == 1) { un++; if (clear) up++; }
                else              { fnn++; if (clear) fpn++; }
            }
            std::printf("\n  operating point L%d @ %.3f on THIS population:\n",
                        attn_layers[L11_SLOT], THR);
            std::printf("    used-clear   %3d/%-3d = %3.0f%%   (recall)\n",
                        up, un, un ? 100.0 * up / un : 0.0);
            std::printf("    filler-clear %3d/%-3d = %3.0f%%   (false-positive rate)\n",
                        fpn, fnn, fnn ? 100.0 * fpn / fnn : 0.0);
        }

        std::printf("\n  ---- cost curve: what a band of width w withdraws ----\n");
        std::printf("  %8s %10s %10s %10s   %12s\n",
                    "band w", "borderln", "of which+", "of which f", "% of skipped[]");
        const double ws[] = {0.005, 0.010, 0.020, 0.030, 0.050, 0.075, 0.100, 0.150};
        for (double w : ws) {
            int nb = 0, nbp = 0, nbf = 0, nbs = 0;
            for (auto& b : br) {
                if (b.dist > w) continue;
                nb++;
                if (b.label == 1) nbp++; else nbf++;
                if (b.peak < THR) nbs++;
            }
            std::printf("  %8.3f %6d/%-4d %10d %10d   %11.0f%%\n",
                        w, nb, tot, nbp, nbf, cur_skipped ? 100.0 * nbs / cur_skipped : 0.0);
        }
        std::printf("\n  read: a band of width w is AFFORDABLE if the right-hand column stays\n"
                    "  small — that is the fraction of today's omission claims it withdraws.\n"
                    "  It is SUFFICIENT if w exceeds the measured drift (not measured here).\n");
    }

    return 0;
}

// ═════════════════════════════════════════════════════════════════════════
// GEMMA4 candidate-space SEARCH — every (layer,head) candidate scored on the
// Leg C messy corpus DIRECTLY, Metric A and Metric B in the same pass. Gated
// GEMMA4_SEARCH_DUAL=1. docs/note-lens-gemma-norm-weighted.md.
//
// This does NOT select on Prompt A/B/C and confirm on the messy corpus
// afterward -- note-lens-gemma4-probe.md §2 found that procedure has almost
// no discriminating power on Gemma (ranks 1-4 tied at exactly 75.0%). Every
// candidate here is scored directly against the same 15-doc EN+DE messy
// corpus and grammar/task Leg C uses, so a reproduction of L4H7's documented
// 41%/51% under Metric A is the plumbing sanity check (§6 of that note).
//
// Metric B needs ||V_j|| per candidate, and Gemma 4 splits attention across
// TWO disjoint KV caches with DIFFERENT (n_kv_heads, head_dim) shapes: global
// layers (V==K, no attn_v.weight, wide head_dim, few KV heads) and sliding
// layers (separate V, narrow head_dim, more KV heads). Neither the per-layer
// kind nor the two caches are reachable through the single-cache accessor
// every other leg in this file uses (snapshot_kv_cache() returns nullptr on
// gemma4 -- gemma4.h overrides the MULTI-cache snapshot_kv_caches() instead).
// The per-layer kind is derived here from tensor-inventory presence of
// blk.<il>.attn_v.weight -- the exact same test Gemma4Config::from_metadata
// (gemma4.cpp) uses internally. This file does not include gemma4.h, so the
// derivation is reproduced against meta.raw_kv / meta.tensor_inventory
// rather than reached through the recipe's own config object; the two caches
// snapshot_kv_caches() returns are then matched to (global, swa) by SHAPE
// (n_layers, V ne[0]) rather than trusted by the documented return order --
// "derive it, do not assume it" applied to a second, harder cache-layer trap
// than the single-cache one the brief named.
// ═════════════════════════════════════════════════════════════════════════

// ||V_j|| for every kv_head of one (cache, cache_layer) in ONE tensor read.
// The single-head value_norms() above would re-read the same layer's full V
// tensor once per kv_head; at 48 candidate slots (vs. the 1-2 frozen slots
// every other leg reads) that redundancy is worth avoiding. Runs the exact
// same checks (type, ne[0], row stride) value_norms() runs, so this is not
// more trusting of the tensor than the reader it stands in for.
static std::vector<std::vector<float>> value_norms_all_heads(
        simple_kv_cache* kv, int cache_layer, int head_dim, int n_head_kv, int n_kv) {
    ggml_tensor* vt = kv->get_v_cache_tensor(cache_layer);
    if (!vt)
        throw std::runtime_error("value_norms_all_heads: expected a V cache tensor for cache layer " +
                                 std::to_string(cache_layer) + ", actual nullptr");
    if (vt->type != GGML_TYPE_F32 && vt->type != GGML_TYPE_F16)
        throw std::runtime_error("value_norms_all_heads: expected V cache type f32 or f16, actual " +
            std::string(ggml_type_name(vt->type)));
    const int n_embd_v = n_head_kv * head_dim;
    if ((int)vt->ne[0] != n_embd_v)
        throw std::runtime_error("value_norms_all_heads: expected V cache ne[0]=" +
            std::to_string(n_embd_v) + " (n_head_kv*head_dim), actual " + std::to_string(vt->ne[0]));
    const size_t elem = ggml_type_size(vt->type);
    if (vt->nb[1] != (size_t)n_embd_v * elem)
        throw std::runtime_error("value_norms_all_heads: expected V cache row stride " +
            std::to_string((size_t)n_embd_v * elem) + " bytes (contiguous), actual " +
            std::to_string(vt->nb[1]));
    std::vector<uint8_t> raw((size_t)n_kv * n_embd_v * elem);
    ggml_backend_tensor_get(vt, raw.data(), 0, raw.size());

    std::vector<std::vector<float>> out(n_head_kv, std::vector<float>(n_kv, 0.0f));
    for (int j = 0; j < n_kv; ++j) {
        const uint8_t* rowb = raw.data() + (size_t)j * n_embd_v * elem;
        for (int kh = 0; kh < n_head_kv; ++kh) {
            double ss = 0;
            if (vt->type == GGML_TYPE_F32) {
                const float* row = reinterpret_cast<const float*>(rowb);
                for (int d = 0; d < head_dim; ++d) { double x = row[(size_t)kh * head_dim + d]; ss += x * x; }
            } else {
                const ggml_fp16_t* row = reinterpret_cast<const ggml_fp16_t*>(rowb);
                for (int d = 0; d < head_dim; ++d) {
                    double x = ggml_fp16_to_fp32(row[(size_t)kh * head_dim + d]);
                    ss += x * x;
                }
            }
            out[kh][j] = (float)std::sqrt(ss);
        }
    }
    return out;
}

// Allocation-free top-3-in-span scan. topk_head/topk_head_weighted above
// build+partial_sort a vector per call; this leg calls a per-position scan
// ~48 slots x 16 heads x ~400 scored tokens x 2 metrics times (~600K calls),
// where a heap allocation per call would dominate wall time. Position 0 (the
// BOS-sink) is excluded, matching topk_head's own convention, for the same
// reason: an attention sink would otherwise win top-1 by construction.
static void top3_positions(const float* r, int n_kv, int& p1, int& p2, int& p3) {
    p1 = p2 = p3 = -1;
    float v1 = -1e30f, v2 = -1e30f, v3 = -1e30f;
    for (int j = 1; j < n_kv; ++j) {
        float x = r[j];
        if (x > v1)      { v3 = v2; p3 = p2; v2 = v1; p2 = p1; v1 = x; p1 = j; }
        else if (x > v2) { v3 = v2; p3 = p2; v2 = x;  p2 = j; }
        else if (x > v3) { v3 = x;  p3 = j; }
    }
}
// Metric B's analogue: ranks by alpha_j * ||V_j|| instead of alpha_j.
// Unnormalized -- renormalizing by the row's total is a positive rescale
// that cannot change which positions are top-1/top-3 (see topk_head_weighted's
// own comment), so the normalization that matters for honest score PRINTING
// is skipped here on purpose; only membership is accumulated at this scale.
static void top3_positions_weighted(const float* r, const float* vnorm, int n_kv,
                                    int& p1, int& p2, int& p3) {
    p1 = p2 = p3 = -1;
    float v1 = -1e30f, v2 = -1e30f, v3 = -1e30f;
    for (int j = 1; j < n_kv; ++j) {
        float x = r[j] * vnorm[j];
        if (x > v1)      { v3 = v2; p3 = p2; v2 = v1; p2 = p1; v1 = x; p1 = j; }
        else if (x > v2) { v3 = v2; p3 = p2; v2 = x;  p2 = j; }
        else if (x > v3) { v3 = x;  p3 = j; }
    }
}

struct Gemma4KvLayout {
    std::vector<bool> is_global;      // size block_count
    std::vector<int>  cache_idx;      // per-layer index WITHIN its own cache
    uint32_t head_dim_swa = 0, head_dim_global = 0;
    uint32_t n_kv_heads_swa = 0, n_kv_heads_global = 0;
    uint32_t n_swa_layers = 0, n_global_layers = 0;
};

// Reproduces Gemma4Config::from_metadata's per-layer-kind derivation
// (gemma4.cpp) read-only, from meta.raw_kv / meta.tensor_inventory, so this
// probe stays out of src/ and does not include gemma4.h.
static Gemma4KvLayout resolve_gemma4_kv_layout(const ModelMetadata& meta) {
    if (meta.architecture.rfind("gemma4", 0) != 0)
        throw std::runtime_error("resolve_gemma4_kv_layout: expected arch 'gemma4*', actual '" +
                                 meta.architecture + "'");
    Gemma4KvLayout L;
    const auto& inv = meta.tensor_inventory;
    L.is_global.assign(meta.block_count, false);
    L.cache_idx.assign(meta.block_count, -1);
    int swa_idx = 0, glb_idx = 0;
    for (uint32_t il = 0; il < meta.block_count; ++il) {
        const std::string vk = "blk." + std::to_string(il) + ".attn_v.weight";
        bool has_v = inv.find(vk) != inv.end();
        L.is_global[il] = !has_v;
        L.cache_idx[il] = has_v ? swa_idx++ : glb_idx++;
    }
    L.n_swa_layers    = (uint32_t)swa_idx;
    L.n_global_layers = (uint32_t)glb_idx;
    L.head_dim_global = meta.raw_kv.get_uint32("gemma4.attention.key_length");
    L.head_dim_swa    = meta.raw_kv.get_uint32("gemma4.attention.key_length_swa");
    auto k_out_dim = [&](uint32_t il) -> uint64_t {
        const std::string kk = "blk." + std::to_string(il) + ".attn_k.weight";
        auto it = inv.find(kk);
        if (it == inv.end() || it->second.shape.size() < 2)
            throw std::runtime_error("resolve_gemma4_kv_layout: tensor '" + kk +
                                     "' missing or rank-deficient");
        return it->second.shape[1];
    };
    bool seen_swa = false, seen_glb = false;
    for (uint32_t il = 0; il < meta.block_count && !(seen_swa && seen_glb); ++il) {
        if (!seen_swa && !L.is_global[il]) {
            L.n_kv_heads_swa = (uint32_t)(k_out_dim(il) / L.head_dim_swa); seen_swa = true;
        }
        if (!seen_glb && L.is_global[il]) {
            L.n_kv_heads_global = (uint32_t)(k_out_dim(il) / L.head_dim_global); seen_glb = true;
        }
    }
    if (L.n_swa_layers && !L.n_kv_heads_swa)
        throw std::runtime_error("resolve_gemma4_kv_layout: n_kv_heads_swa expected >0, actual 0");
    if (L.n_global_layers && !L.n_kv_heads_global)
        throw std::runtime_error("resolve_gemma4_kv_layout: n_kv_heads_global expected >0, actual 0");
    return L;
}

// Matches fp->snapshot_kv_caches() to (global, swa) by SHAPE (n_layers, V
// ne[0]) rather than by the documented return order -- see the section
// banner above.
struct Gemma4Caches { simple_kv_cache* global = nullptr; simple_kv_cache* swa = nullptr; };
static Gemma4Caches resolve_gemma4_caches(ForwardPassBase* fp, const Gemma4KvLayout& L) {
    auto caches = fp->snapshot_kv_caches();
    Gemma4Caches out;
    for (simple_kv_cache* kv : caches) {
        if (!kv) continue;
        uint32_t nl = kv->get_n_layers();
        ggml_tensor* v0 = nl ? kv->get_v_cache_tensor(0) : nullptr;
        uint32_t ne0 = v0 ? (uint32_t)v0->ne[0] : 0;
        bool matches_global = L.n_global_layers && nl == L.n_global_layers &&
                              ne0 == L.n_kv_heads_global * L.head_dim_global;
        bool matches_swa    = L.n_swa_layers && nl == L.n_swa_layers &&
                              ne0 == L.n_kv_heads_swa * L.head_dim_swa;
        if (matches_global && matches_swa)
            throw std::runtime_error("resolve_gemma4_caches: a cache matches BOTH global and swa "
                "shapes (n_layers=" + std::to_string(nl) + " ne0=" + std::to_string(ne0) +
                ") -- ambiguous, refusing to guess");
        if (matches_global) {
            if (out.global) throw std::runtime_error("resolve_gemma4_caches: two caches match global shape");
            out.global = kv;
        } else if (matches_swa) {
            if (out.swa) throw std::runtime_error("resolve_gemma4_caches: two caches match swa shape");
            out.swa = kv;
        } else {
            throw std::runtime_error("resolve_gemma4_caches: cache (n_layers=" + std::to_string(nl) +
                " ne0=" + std::to_string(ne0) + ") matches neither global nor swa shape");
        }
    }
    if (L.n_global_layers && !out.global)
        throw std::runtime_error("resolve_gemma4_caches: expected a global-shaped cache, found none");
    if (L.n_swa_layers && !out.swa)
        throw std::runtime_error("resolve_gemma4_caches: expected a swa-shaped cache, found none");
    return out;
}

// Average-rank (ties share the mean rank), rank 1 = highest score.
static std::vector<double> rank_desc_avg(const std::vector<double>& v) {
    int n = (int)v.size();
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) idx[i] = i;
    std::sort(idx.begin(), idx.end(), [&](int a, int b) { return v[a] > v[b]; });
    std::vector<double> rank(n);
    int i = 0;
    while (i < n) {
        int j = i;
        while (j < n && v[idx[j]] == v[idx[i]]) j++;
        double avg = (i + j - 1) / 2.0 + 1.0;
        for (int k2 = i; k2 < j; ++k2) rank[idx[k2]] = avg;
        i = j;
    }
    return rank;
}
static double pearson(const std::vector<double>& a, const std::vector<double>& b) {
    int n = (int)a.size();
    double ma = 0, mb = 0;
    for (int i = 0; i < n; ++i) { ma += a[i]; mb += b[i]; }
    ma /= n; mb /= n;
    double num = 0, da = 0, db = 0;
    for (int i = 0; i < n; ++i) {
        double xa = a[i] - ma, xb = b[i] - mb;
        num += xa * xb; da += xa * xa; db += xb * xb;
    }
    return (da > 0 && db > 0) ? num / std::sqrt(da * db) : 0.0;
}

static int run_gemma4_search_dual(ForwardPassBase* fp, ggml_backend_sched_t sched,
                                  Tokenizer* tok, const ModelMetadata& meta,
                                  const std::vector<int32_t>& attn_layers) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ GEMMA4 SEARCH — all (layer,head) candidates, Leg C corpus, A/B ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");

    const int TOL = 2;
    const std::vector<std::string>& vocab = tok->get_vocabulary();
    const uint32_t vocab_size = (uint32_t)vocab.size();
    qinf::TokenTrie trie; trie.build(vocab);
    auto gr = qinf::GrammarVocab::parse_impl(QDOCS_GBNF);
    gr->set_token_trie(&trie);
    std::vector<int> taps(attn_layers.begin(), attn_layers.end());
    // Byte-identical to run_qdocs_leg_c's TASK — the L4H7 41%/51% reproduction
    // check below is only meaningful if every setting matches that leg.
    const char* TASK = "\n\nExtract every fact from the email above into a flat JSON "
        "object of \"key\": \"value\" pairs. Use short snake_case keys — prefer keys like: "
        "customer, product, quantity, unit_price, total, order_date, delivery, order_number. "
        "Copy each value verbatim from the email. Output ONLY the JSON object, nothing else.";

    auto corpus = qdocs_messy_corpus();

    const int S = (int)attn_layers.size();
    const int H = (int)meta.attention_head_count;
    const int C = S * H;
    std::printf("candidates: %d slots x %d heads = %d\n", S, H, C);

    Gemma4KvLayout L = resolve_gemma4_kv_layout(meta);
    Gemma4Caches   K = resolve_gemma4_caches(fp, L);
    std::printf("kv layout: swa layers=%u kv_heads=%u head_dim=%u | global layers=%u kv_heads=%u head_dim=%u\n",
                L.n_swa_layers, L.n_kv_heads_swa, L.head_dim_swa,
                L.n_global_layers, L.n_kv_heads_global, L.head_dim_global);

    std::vector<simple_kv_cache*> slot_cache(S);
    std::vector<int> slot_cache_layer(S), slot_head_dim(S), slot_n_kv_heads(S), slot_group(S);
    for (int s = 0; s < S; ++s) {
        int il = attn_layers[s];
        bool g = L.is_global[il];
        slot_cache[s]       = g ? K.global : K.swa;
        slot_cache_layer[s] = L.cache_idx[il];
        slot_head_dim[s]    = g ? (int)L.head_dim_global   : (int)L.head_dim_swa;
        slot_n_kv_heads[s]  = g ? (int)L.n_kv_heads_global : (int)L.n_kv_heads_swa;
        if (H % slot_n_kv_heads[s] != 0)
            throw std::runtime_error("run_gemma4_search_dual: expected n_head (" + std::to_string(H) +
                ") a multiple of n_kv_heads (" + std::to_string(slot_n_kv_heads[s]) + ") at il=" +
                std::to_string(il));
        slot_group[s] = H / slot_n_kv_heads[s];
    }

    std::vector<long> t1A_en(C, 0), t3A_en(C, 0), t1A_de(C, 0), t3A_de(C, 0);
    std::vector<long> t1B_en(C, 0), t3B_en(C, 0), t1B_de(C, 0), t3B_de(C, 0);
    int cite_n_en = 0, cite_n_de = 0;

    for (const QMessy& d : corpus) {
        std::string prompt = qdocs_chat_prompt(d.document, TASK);
        std::vector<GStep> tr;
        FreeRun R = run_freegen_grammar(fp, sched, tok, meta, prompt, "", taps,
                                        320, gr.get(), vocab, vocab_size, &tr);
        std::printf("\n[%s%s] %s\n", d.tag.c_str(), d.de ? " DE" : "", R.gen_text.c_str());

        int n_kv_final = R.n_kv_at_step.empty() ? R.P : R.n_kv_at_step.back();
        std::vector<std::vector<std::vector<float>>> vnorm_by_slot(S);
        for (int s = 0; s < S; ++s) {
            vnorm_by_slot[s] = value_norms_all_heads(slot_cache[s], slot_cache_layer[s],
                                                     slot_head_dim[s], slot_n_kv_heads[s], n_kv_final);
            for (auto& v : vnorm_by_slot[s]) sanity_check_norms(v, "gemma4-search value-norm layer");
        }
        // Diagnostic (first doc only): ||V_j|| spread for the eventual winner
        // (L7H13, a sliding layer) and for the first global layer found --
        // gemma4.cpp RMS-norms V with NO learned weight before it is cached
        // ("Vcur = ggml_rms_norm(ctx0, Vcur, eps)"), which forces every V_j to
        // a near-constant L2 norm BY CONSTRUCTION. If that is why Metric A/B
        // tie, this spread should be tiny relative to the mean.
        if (&d == &corpus.front()) {
            auto stats = [&](int s, int kh) {
                const auto& v = vnorm_by_slot[s][kh];
                double mn = 1e30, mx = -1e30, sum = 0, sumsq = 0; int n = 0;
                for (size_t j = 1; j + 1 < v.size(); ++j) {  // skip BOS + tail, as sanity_check_norms does
                    double x = v[j]; mn = std::min(mn, x); mx = std::max(mx, x);
                    sum += x; sumsq += x * x; n++;
                }
                double mean = n ? sum / n : 0;
                double var = n ? sumsq / n - mean * mean : 0;
                double sd = var > 0 ? std::sqrt(var) : 0;
                std::printf("  ||V|| slot=%d kv_head=%d: n=%d min=%.4f mean=%.4f max=%.4f sd=%.4f cv=%.4f%%\n",
                            s, kh, n, mn, mean, mx, sd, mean ? 100.0 * sd / mean : 0);
            };
            std::printf("\n── ||V_j|| SPREAD (doc 1 only, sanity for the A/B tie) ──\n");
            for (int s = 0; s < S; ++s) if (attn_layers[s] == 7) { stats(s, 13 / slot_group[s]); break; }
            for (int s = 0; s < S; ++s) if (L.is_global[attn_layers[s]]) { stats(s, 0); break; }
        }

        std::vector<size_t> gcum = cum_bytes(tok, R.gen_tokens);
        for (const QLabel& f : d.fields) {
            int slo, shi;
            if (!qdocs_span_in_prompt(tok, R, f.value, slo, shi)) continue;
            size_t gb = R.gen_text.find(f.value);
            if (gb == std::string::npos) continue;   // normalized away, unscoreable
            size_t ge = gb + f.value.size();
            auto in = [&](int p) { return p >= 1 && p >= slo - TOL && p <= shi + TOL; };

            for (int g = 0; g < (int)R.gen_tokens.size(); ++g) {
                if (!(gcum[g] < ge && gcum[g + 1] > gb)) continue;
                if (g < 1 || g - 1 >= (int)R.rows.size()) continue;
                int n_kv = R.n_kv_at_step[g - 1];
                if (d.de) cite_n_de++; else cite_n_en++;
                for (int s = 0; s < S; ++s) {
                    const float* rowBase = R.rows[g - 1][s].data();
                    int group = slot_group[s];
                    for (int h = 0; h < H; ++h) {
                        int cand = s * H + h;
                        const float* r = rowBase + (size_t)h * n_kv;
                        int a1, a2, a3; top3_positions(r, n_kv, a1, a2, a3);
                        bool a1in = in(a1), a3in = in(a1) || in(a2) || in(a3);
                        int b1, b2, b3;
                        top3_positions_weighted(r, vnorm_by_slot[s][h / group].data(), n_kv, b1, b2, b3);
                        bool b1in = in(b1), b3in = in(b1) || in(b2) || in(b3);
                        if (d.de) {
                            if (a1in) t1A_de[cand]++; if (a3in) t3A_de[cand]++;
                            if (b1in) t1B_de[cand]++; if (b3in) t3B_de[cand]++;
                        } else {
                            if (a1in) t1A_en[cand]++; if (a3in) t3A_en[cand]++;
                            if (b1in) t1B_en[cand]++; if (b3in) t3B_en[cand]++;
                        }
                    }
                }
            }
        }
    }

    const int cite_n = cite_n_en + cite_n_de;
    std::printf("\nscored value tokens: EN %d  DE %d  combined %d\n", cite_n_en, cite_n_de, cite_n);

    // Rank all C candidates under each metric: primary=top1 combined count,
    // tie-break=top3 combined count (same convention main()'s Prompt-A
    // "global best" search below uses).
    std::vector<double> compA(C), compB(C);
    std::vector<long> t1A(C), t3A(C), t1B(C), t3B(C);
    for (int c = 0; c < C; ++c) {
        t1A[c] = t1A_en[c] + t1A_de[c]; t3A[c] = t3A_en[c] + t3A_de[c];
        t1B[c] = t1B_en[c] + t1B_de[c]; t3B[c] = t3B_en[c] + t3B_de[c];
        compA[c] = (double)t1A[c] * (cite_n + 1) + (double)t3A[c];
        compB[c] = (double)t1B[c] * (cite_n + 1) + (double)t3B[c];
    }
    // Diagnostic: how many of the 768 candidates does Metric B actually move
    // at the raw hit-count level (before any ranking/tie-break)? Spearman
    // alone cannot distinguish "every candidate identical" from "a few tiny,
    // rank-order-preserving nudges" at 4-decimal printing precision.
    int diff_t1 = 0, diff_t3 = 0; long max_abs_t1_diff = 0, max_abs_t3_diff = 0;
    for (int c = 0; c < C; ++c) {
        if (t1A[c] != t1B[c]) { diff_t1++; max_abs_t1_diff = std::max(max_abs_t1_diff, std::abs(t1A[c] - t1B[c])); }
        if (t3A[c] != t3B[c]) { diff_t3++; max_abs_t3_diff = std::max(max_abs_t3_diff, std::abs(t3A[c] - t3B[c])); }
    }
    std::printf("\n── METRIC A vs B, RAW HIT-COUNT DIFFERENCES (of %d candidates) ──\n", C);
    std::printf("  top1 differs on %d candidates (max |delta|=%ld)\n", diff_t1, max_abs_t1_diff);
    std::printf("  top3 differs on %d candidates (max |delta|=%ld)\n", diff_t3, max_abs_t3_diff);

    std::vector<double> rankA = rank_desc_avg(compA);
    std::vector<double> rankB = rank_desc_avg(compB);
    double spearman = pearson(rankA, rankB);

    int bestA = 0, bestB = 0;
    for (int c = 1; c < C; ++c) {
        if (compA[c] > compA[bestA]) bestA = c;
        if (compB[c] > compB[bestB]) bestB = c;
    }

    auto layer_of = [&](int c) { return attn_layers[c / H]; };
    auto head_of  = [&](int c) { return c % H; };
    auto pct = [&](long n) { return cite_n ? 100.0 * n / cite_n : 0.0; };
    auto printCand = [&](const std::string& label, int c) {
        std::printf("  %-14s L%dH%-3d  A: top1 %ld/%d (%.1f%%) top3 %ld/%d (%.1f%%)  |  "
                    "B: top1 %ld/%d (%.1f%%) top3 %ld/%d (%.1f%%)  |  rankA=%.1f rankB=%.1f\n",
                    label.c_str(), layer_of(c), head_of(c),
                    t1A[c], cite_n, pct(t1A[c]), t3A[c], cite_n, pct(t3A[c]),
                    t1B[c], cite_n, pct(t1B[c]), t3B[c], cite_n, pct(t3B[c]), rankA[c], rankB[c]);
    };
    std::printf("\n── BEST CANDIDATES ──\n");
    printCand("best under A", bestA);
    printCand("best under B", bestB);

    int clearA70 = 0, clearA80 = 0, clearA90 = 0, clearB70 = 0, clearB80 = 0, clearB90 = 0;
    for (int c = 0; c < C; ++c) {
        double t3a = pct(t3A[c]), t3b = pct(t3B[c]);
        if (t3a >= 70) clearA70++; if (t3a >= 80) clearA80++; if (t3a >= 90) clearA90++;
        if (t3b >= 70) clearB70++; if (t3b >= 80) clearB80++; if (t3b >= 90) clearB90++;
    }
    std::printf("\n── CLEAR-RATE COUNTS (top3, of %d candidates) ──\n", C);
    std::printf("  metric A: >=70%% %d   >=80%% %d   >=90%% %d\n", clearA70, clearA80, clearA90);
    std::printf("  metric B: >=70%% %d   >=80%% %d   >=90%% %d\n", clearB70, clearB80, clearB90);

    std::printf("\n── SPEARMAN(rankA, rankB) over all %d candidates: %.4f ──\n", C, spearman);

    std::vector<int> orderA(C), orderB(C);
    for (int c = 0; c < C; ++c) { orderA[c] = c; orderB[c] = c; }
    std::sort(orderA.begin(), orderA.end(), [&](int a, int b) { return compA[a] > compA[b]; });
    std::sort(orderB.begin(), orderB.end(), [&](int a, int b) { return compB[a] > compB[b]; });
    std::printf("\n── TOP 10 UNDER METRIC A ──\n");
    for (int i = 0; i < 10 && i < C; ++i) printCand("#" + std::to_string(i + 1), orderA[i]);
    std::printf("\n── TOP 10 UNDER METRIC B ──\n");
    for (int i = 0; i < 10 && i < C; ++i) printCand("#" + std::to_string(i + 1), orderB[i]);

    // BROKEN check: metric A at L4H7 must reproduce the documented 41%/51%
    // baseline (note-lens-gemma4-probe.md §6), or this leg's plumbing -- not
    // the metric -- is what is wrong.
    for (int c = 0; c < C; ++c) {
        if (layer_of(c) == 4 && head_of(c) == 7) {
            std::printf("\n── L4H7 REPRODUCTION CHECK (metric A only, vs note-lens-gemma4-probe.md §6) ──\n");
            std::printf("  documented: top1 161/397 (41%%)  top3 204/397 (51%%)\n");
            std::printf("  this run:   top1 %ld/%d (%.1f%%)  top3 %ld/%d (%.1f%%)\n",
                        t1A[c], cite_n, pct(t1A[c]), t3A[c], cite_n, pct(t3A[c]));
            break;
        }
    }
    return 0;
}

// ═════════════════════════════════════════════════════════════════════════
// MLXCMP — cross-RUNTIME head-survival dump. Does the frozen citation head
// found under ggml stay the best head under MLX's kernels?
//
// The lens ships a single (layer, head) coordinate per calibrated model. That
// coordinate was found under ggml+Metal. Porting the tap to MLX (docs: the
// iPhone envelope) replaces every kernel upstream of the softmax — RoPE,
// q/k-norm, the projections, matmul order — so the coordinate is only portable
// if head IDENTITY is a property of the weights rather than of the kernels.
//
// This probe dumps everything the MLX side needs to recompute the SAME metric
// on the SAME tokens, plus the ggml-side per-(layer,head) table to compare
// against. It TEACHER-FORCES: the MLX run consumes the exact prompt+generated
// ids recorded here, so tokenizer differences, sampling and grammar divergence
// are all removed as variables and the only thing left is numerics.
//
// Scorer is qdocs_eval_field's verbatim: topk_head (position 0 excluded — the
// attention sink), in-span with TOL=2, top-1 and top-3. cite_n is reported per
// the §4.2 rule, because a field the model got WRONG leaves the denominator.
//
// Gated MLXCMP=1; MLXCMP_OUT names the JSON (default mlxcmp.json).
// ═════════════════════════════════════════════════════════════════════════
static int run_mlx_compare_dump(ForwardPassBase* fp, ggml_backend_sched_t sched,
                                Tokenizer* tok, const ModelMetadata& meta,
                                const std::vector<int32_t>& attn_layers) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ MLXCMP — cross-runtime head-survival dump (ggml reference)    ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");

    const int TOL = 2;
    const int S = (int)attn_layers.size();
    const int H = (int)meta.attention_head_count;
    std::printf("tapped layers=%d heads=%d candidates=%d\n", S, H, S * H);

    const std::vector<std::string>& vocab = tok->get_vocabulary();
    const uint32_t vocab_size = (uint32_t)vocab.size();
    qinf::TokenTrie trie; trie.build(vocab);
    auto gr = qinf::GrammarVocab::parse_impl(QDOCS_GBNF);
    gr->set_token_trie(&trie);
    std::vector<int> taps(attn_layers.begin(), attn_layers.end());

    // Byte-identical TASK to run_qdocs_leg_c / run_head_aggregation_probe, so
    // the ggml table below is comparable to the published ARM A numbers.
    const char* TASK = "\n\nExtract every fact from the email above into a flat JSON "
        "object of \"key\": \"value\" pairs. Use short snake_case keys — prefer keys like: "
        "customer, product, quantity, unit_price, total, order_date, delivery, order_number. "
        "Copy each value verbatim from the email. Output ONLY the JSON object, nothing else.";

    nlohmann::json out;
    out["arch"]        = g_arch;
    out["n_head"]      = H;
    out["attn_layers"] = attn_layers;
    out["tol"]         = TOL;
    out["docs"]        = nlohmann::json::array();

    // ggml-side per-(layer,head) citation table.
    std::vector<std::vector<long>> t1(S, std::vector<long>(H, 0));
    std::vector<std::vector<long>> t3(S, std::vector<long>(H, 0));
    int cite_n = 0, fields_total = 0, fields_dropped = 0;

    for (const QMessy& d : qdocs_messy_corpus()) {
        std::string prompt = qdocs_chat_prompt(d.document, TASK);
        std::vector<GStep> tr;
        FreeRun R = run_freegen_grammar(fp, sched, tok, meta, prompt, "", taps,
                                        320, gr.get(), vocab, vocab_size, &tr);
        int doc_lo, doc_hi;
        if (!qdocs_span_in_prompt(tok, R, d.document, doc_lo, doc_hi)) { doc_lo = 0; doc_hi = R.P - 1; }

        nlohmann::json jd;
        jd["tag"]        = d.tag;
        jd["de"]         = d.de;
        jd["P"]          = R.P;
        jd["prompt_ids"] = R.prompt_tokens;
        jd["gen_ids"]    = R.gen_tokens;
        jd["gen_text"]   = R.gen_text;
        jd["doc_lo"]     = doc_lo;
        jd["doc_hi"]     = doc_hi;
        jd["n_kv_at_step"] = R.n_kv_at_step;
        jd["fields"]     = nlohmann::json::array();

        std::vector<size_t> gcum = cum_bytes(tok, R.gen_tokens);
        int doc_cite = 0;
        for (const QLabel& f : d.fields) {
            fields_total++;
            int slo, shi;
            if (!qdocs_span_in_prompt(tok, R, f.value, slo, shi)) { fields_dropped++; continue; }
            size_t gb = R.gen_text.find(f.value);
            if (gb == std::string::npos) { fields_dropped++; continue; }  // §4.2: leaves the denominator
            size_t ge = gb + f.value.size();

            std::vector<int> gpos;
            for (int g = 0; g < (int)R.gen_tokens.size(); ++g) {
                if (!(gcum[g] < ge && gcum[g + 1] > gb)) continue;
                if (g < 1 || g - 1 >= (int)R.rows.size()) continue;
                gpos.push_back(g);
                const int n_kv = R.n_kv_at_step[g - 1];
                cite_n++; doc_cite++;
                auto in = [&](int p) { return p >= slo - TOL && p <= shi + TOL; };
                for (int s = 0; s < S; ++s) {
                    for (int h = 0; h < H; ++h) {
                        auto tk = topk_head(R.rows[g - 1][s], h, n_kv, 3);
                        if (!tk.empty() && in(tk[0].first)) t1[s][h]++;
                        for (auto& pr : tk) if (in(pr.first)) { t3[s][h]++; break; }
                    }
                }
            }
            nlohmann::json jf;
            jf["concept"] = f.concept;
            jf["value"]   = f.value;
            jf["slo"]     = slo;
            jf["shi"]     = shi;
            jf["gpos"]    = gpos;
            jd["fields"].push_back(jf);
        }
        // Coverage spans, built by covsearch_arm2's rule verbatim: positives are
        // every labelled value found in the prompt (NOT conditioned on the model
        // emitting it — coverage is not subject to §4.2), negatives are
        // length-matched filler windows cut deterministically from the document
        // positions no value occupies. The MLX legs need these to recompute the
        // coverage span-peak, which is a MAGNITUDE, unlike the citation rank.
        {
            std::vector<char> occupied(R.P, 0);
            std::vector<std::pair<int,int>> pos;   // (lo,hi)
            for (const QLabel& f : d.fields) {
                int slo, shi;
                if (!qdocs_span_in_prompt(tok, R, f.value, slo, shi)) continue;
                for (int p = std::max(0, slo - TOL); p <= std::min(R.P - 1, shi + TOL); ++p)
                    occupied[p] = 1;
                pos.push_back({slo, shi});
            }
            std::vector<std::pair<int,int>> runs;
            {
                int p = std::max(1, doc_lo), lim = std::min(R.P - 1, doc_hi);
                while (p <= lim) {
                    if (occupied[p]) { ++p; continue; }
                    int s0 = p; while (p <= lim && !occupied[p]) ++p;
                    runs.push_back({s0, p - s0});
                }
            }
            jd["cov_spans"] = nlohmann::json::array();
            for (auto& pr : pos) {
                nlohmann::json j; j["lo"] = pr.first; j["hi"] = pr.second; j["label"] = 1;
                jd["cov_spans"].push_back(j);
            }
            size_t ri = 0; int roff = 0;
            for (auto& pr : pos) {
                int L = pr.second - pr.first + 1;
                while (ri < runs.size() && runs[ri].second - roff < L) { ++ri; roff = 0; }
                if (ri >= runs.size()) continue;
                int nlo = runs[ri].first + roff;
                roff += L;
                nlohmann::json j; j["lo"] = nlo; j["hi"] = nlo + L - 1; j["label"] = 0;
                jd["cov_spans"].push_back(j);
            }
            // ggml's own per-layer span peak for each span, by span_scalars'
            // definition — the reference the MLX legs' magnitudes are compared
            // against. The shipped coverage constant was measured on THIS side.
            for (auto& j : jd["cov_spans"]) {
                double sc[SC_N][4];
                span_scalars(R, j["lo"].get<int>(), j["hi"].get<int>(), sc, attn_layers);
                std::vector<double> per_layer;
                for (int s2 = 0; s2 < S; ++s2) per_layer.push_back(sc[1 + s2][0]);
                j["ggml_peak"] = per_layer;
            }
        }
        std::printf("  [%-6s%s] P=%4d G=%3zu fields=%2zu scored_pos=%3d cov_spans=%zu\n",
                    d.tag.c_str(), d.de ? " DE" : "   ", R.P, R.gen_tokens.size(),
                    d.fields.size(), doc_cite, jd["cov_spans"].size());
        out["docs"].push_back(jd);
    }

    out["ggml"]["cite_n"]          = cite_n;
    out["ggml"]["fields_total"]    = fields_total;
    out["ggml"]["fields_dropped"]  = fields_dropped;
    out["ggml"]["t1"]              = t1;
    out["ggml"]["t3"]              = t3;

    // ── ggml reference table ────────────────────────────────────────────────
    std::printf("\n---- ggml per-(layer,head) top-3 in-span, over %d scored value tokens ----\n", cite_n);
    std::printf("  (%d of %d labelled fields left the denominator — §4.2)\n",
                fields_dropped, fields_total);
    std::printf("  %-7s", "layer");
    for (int h = 0; h < H; ++h) std::printf(" %5s%-2d", "H", h);
    std::printf("\n");
    int bs = 0, bh = 0; long bt3 = -1;
    for (int s = 0; s < S; ++s) {
        std::printf("  L%-6d", attn_layers[s]);
        for (int h = 0; h < H; ++h) {
            std::printf(" %6.1f%%", cite_n ? 100.0 * t3[s][h] / cite_n : 0.0);
            if (t3[s][h] > bt3) { bt3 = t3[s][h]; bs = s; bh = h; }
        }
        std::printf("\n");
    }
    std::printf("  >>> ggml argmax head: L%dH%d  top3 %.1f%%  top1 %.1f%%\n",
                attn_layers[bs], bh, cite_n ? 100.0 * bt3 / cite_n : 0.0,
                cite_n ? 100.0 * t1[bs][bh] / cite_n : 0.0);
    out["ggml"]["argmax_slot"] = bs;
    out["ggml"]["argmax_head"] = bh;

    const char* op = std::getenv("MLXCMP_OUT");
    std::string path = op ? op : "mlxcmp.json";
    std::ofstream os(path);
    if (!os) {
        std::fprintf(stderr, "MLXCMP: cannot open output path '%s' for writing\n", path.c_str());
        return 1;
    }
    os << out.dump();
    os.close();
    std::printf("\n  wrote %s\n", path.c_str());
    return 0;
}

// ═════════════════════════════════════════════════════════════════════════
// HEAD AGGREGATION PROBE — does a parameter-free aggregation over attention
// heads recover the citation signal where per-head search failed (Gemma 4:
// best single head L4H7 41%/51% vs a >=90% bar; docs/note-lens-gemma4-probe.md
// §6)? Reuses the same corpus/task/scorer as run_qdocs_leg_c and
// run_gemma4_search_dual verbatim (same TOL=2, same in-span definition, same
// 15-doc EN+DE messy corpus, same top3_positions scan) but replaces the
// per-(layer,head) CANDIDATE search with FOUR aggregation arms computed on
// the raw attention weights alpha (Metric A shape only -- no ||V||):
//   A: max over the H heads within a layer, swept over every tapped layer.
//   B: mean over the H heads within a layer, swept over every tapped layer.
//   C: max over every (layer,head) pair. Zero parameters.
//   D: mean over every (layer,head) pair. Zero parameters.
// Architecture-agnostic by construction: it reads R.rows[step][slot], the
// tap output every FreeRun already carries via run_freegen_grammar (which
// goes through qdocs_chat_prompt/prompt_with_bos, so Gemma 4's leading BOS
// and Gemma4ChatTemplate are honoured exactly as run_gemma4_search_dual's
// setup path honours them -- this function calls the same helper, not a
// reimplementation). It never touches a KV-cache tensor, so it needs none of
// run_gemma4_search_dual's gemma4-only global/swa cache-splitting -- that
// machinery exists only for Metric B's ||V||, which this probe does not
// compute. Gated ATTN_HEAD_AGG=1.
// ═════════════════════════════════════════════════════════════════════════
static int run_head_aggregation_probe(ForwardPassBase* fp, ggml_backend_sched_t sched,
                                      Tokenizer* tok, const ModelMetadata& meta,
                                      const std::vector<int32_t>& attn_layers) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ HEAD AGGREGATION PROBE -- max/mean over heads, per-layer+global ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");

    const int TOL = 2;
    const std::vector<std::string>& vocab = tok->get_vocabulary();
    const uint32_t vocab_size = (uint32_t)vocab.size();
    qinf::TokenTrie trie; trie.build(vocab);
    auto gr = qinf::GrammarVocab::parse_impl(QDOCS_GBNF);
    gr->set_token_trie(&trie);
    std::vector<int> taps(attn_layers.begin(), attn_layers.end());
    // Byte-identical TASK to run_qdocs_leg_c / run_gemma4_search_dual.
    const char* TASK = "\n\nExtract every fact from the email above into a flat JSON "
        "object of \"key\": \"value\" pairs. Use short snake_case keys — prefer keys like: "
        "customer, product, quantity, unit_price, total, order_date, delivery, order_number. "
        "Copy each value verbatim from the email. Output ONLY the JSON object, nothing else.";

    auto corpus = qdocs_messy_corpus();

    const int S = (int)attn_layers.size();
    const int H = (int)meta.attention_head_count;
    std::printf("layers=%d heads=%d\n", S, H);

    std::vector<long> t1_max(S, 0), t3_max(S, 0), t1_mean(S, 0), t3_mean(S, 0);
    long t1_gmax = 0, t3_gmax = 0, t1_gmean = 0, t3_gmean = 0;
    int cite_n = 0;

    std::vector<float> rowMax, rowMean, gRowMax, gRowMean;

    for (const QMessy& d : corpus) {
        std::string prompt = qdocs_chat_prompt(d.document, TASK);
        std::vector<GStep> tr;
        FreeRun R = run_freegen_grammar(fp, sched, tok, meta, prompt, "", taps,
                                        320, gr.get(), vocab, vocab_size, &tr);
        std::printf("\n[%s%s] %s\n", d.tag.c_str(), d.de ? " DE" : "", R.gen_text.c_str());

        std::vector<size_t> gcum = cum_bytes(tok, R.gen_tokens);
        for (const QLabel& f : d.fields) {
            int slo, shi;
            if (!qdocs_span_in_prompt(tok, R, f.value, slo, shi)) continue;
            size_t gb = R.gen_text.find(f.value);
            if (gb == std::string::npos) continue;   // normalized away, unscoreable
            size_t ge = gb + f.value.size();
            auto in = [&](int p) { return p >= 1 && p >= slo - TOL && p <= shi + TOL; };

            for (int g = 0; g < (int)R.gen_tokens.size(); ++g) {
                if (!(gcum[g] < ge && gcum[g + 1] > gb)) continue;
                if (g < 1 || g - 1 >= (int)R.rows.size()) continue;
                int n_kv = R.n_kv_at_step[g - 1];
                cite_n++;

                gRowMax.assign(n_kv, -1e30f);
                gRowMean.assign(n_kv, 0.0f);
                for (int s = 0; s < S; ++s) {
                    const float* rowBase = R.rows[g - 1][s].data();
                    rowMax.assign(n_kv, -1e30f);
                    rowMean.assign(n_kv, 0.0f);
                    for (int h = 0; h < H; ++h) {
                        const float* r = rowBase + (size_t)h * n_kv;
                        for (int j = 0; j < n_kv; ++j) {
                            float x = r[j];
                            if (x > rowMax[j]) rowMax[j] = x;
                            rowMean[j] += x;
                        }
                    }
                    for (int j = 0; j < n_kv; ++j) rowMean[j] /= H;

                    int a1, a2, a3;
                    top3_positions(rowMax.data(), n_kv, a1, a2, a3);
                    if (in(a1)) t1_max[s]++;
                    if (in(a1) || in(a2) || in(a3)) t3_max[s]++;

                    int b1, b2, b3;
                    top3_positions(rowMean.data(), n_kv, b1, b2, b3);
                    if (in(b1)) t1_mean[s]++;
                    if (in(b1) || in(b2) || in(b3)) t3_mean[s]++;

                    for (int j = 0; j < n_kv; ++j) {
                        if (rowMax[j] > gRowMax[j]) gRowMax[j] = rowMax[j];
                        gRowMean[j] += rowMean[j];
                    }
                }
                for (int j = 0; j < n_kv; ++j) gRowMean[j] /= S;

                int c1, c2, c3;
                top3_positions(gRowMax.data(), n_kv, c1, c2, c3);
                if (in(c1)) t1_gmax++;
                if (in(c1) || in(c2) || in(c3)) t3_gmax++;

                int e1, e2, e3;
                top3_positions(gRowMean.data(), n_kv, e1, e2, e3);
                if (in(e1)) t1_gmean++;
                if (in(e1) || in(e2) || in(e3)) t3_gmean++;
            }
        }
    }

    auto pct = [&](long n) { return cite_n ? 100.0 * n / cite_n : 0.0; };
    std::printf("\nscored value tokens: %d\n", cite_n);

    std::printf("\n── ARM A: max over heads, per layer (FULL CURVE, %d layers) ──\n", S);
    int bestA = 0;
    for (int s = 0; s < S; ++s) {
        std::printf("  L%-3d  top1 %ld/%d (%.1f%%)  top3 %ld/%d (%.1f%%)\n",
                    attn_layers[s], t1_max[s], cite_n, pct(t1_max[s]), t3_max[s], cite_n, pct(t3_max[s]));
        if (t3_max[s] > t3_max[bestA]) bestA = s;
    }
    std::printf("  >>> best layer under A (FITTED: 1 parameter chosen over %d layers): L%d  "
                "top1 %.1f%%  top3 %.1f%%\n", S, attn_layers[bestA], pct(t1_max[bestA]), pct(t3_max[bestA]));

    std::printf("\n── ARM B: mean over heads, per layer (FULL CURVE, %d layers) ──\n", S);
    int bestB = 0;
    for (int s = 0; s < S; ++s) {
        std::printf("  L%-3d  top1 %ld/%d (%.1f%%)  top3 %ld/%d (%.1f%%)\n",
                    attn_layers[s], t1_mean[s], cite_n, pct(t1_mean[s]), t3_mean[s], cite_n, pct(t3_mean[s]));
        if (t3_mean[s] > t3_mean[bestB]) bestB = s;
    }
    std::printf("  >>> best layer under B (FITTED: 1 parameter chosen over %d layers): L%d  "
                "top1 %.1f%%  top3 %.1f%%\n", S, attn_layers[bestB], pct(t1_mean[bestB]), pct(t3_mean[bestB]));

    std::printf("\n── ARM C: max over ALL (layer,head) pairs -- ZERO PARAMETERS ──\n");
    std::printf("  top1 %ld/%d (%.1f%%)  top3 %ld/%d (%.1f%%)\n",
                t1_gmax, cite_n, pct(t1_gmax), t3_gmax, cite_n, pct(t3_gmax));

    std::printf("\n── ARM D: mean over ALL (layer,head) pairs -- ZERO PARAMETERS ──\n");
    std::printf("  top1 %ld/%d (%.1f%%)  top3 %ld/%d (%.1f%%)\n",
                t1_gmean, cite_n, pct(t1_gmean), t3_gmean, cite_n, pct(t3_gmean));

    return 0;
}

// ── Leg A — fixed grammar × tap sanity (the everything-stops leg) ────────────
static int run_qdocs_leg_a(ForwardPassBase* fp, ggml_backend_sched_t sched,
                           Tokenizer* tok, const ModelMetadata& meta,
                           const std::vector<int32_t>& attn_layers) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ QEMMI-DOCS LEG A — fixed grammar × tap sanity                 ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");

    const int TOL = 2;
    const std::vector<std::string>& vocab = tok->get_vocabulary();
    const uint32_t vocab_size = (uint32_t)vocab.size();
    std::printf("vocab_size=%u\n", vocab_size);

    // Build the trie once (production narrows LITERAL candidates through it).
    qinf::TokenTrie trie;
    trie.build(vocab);
    std::printf("trie tokens indexed=%zu\n", trie.token_count());

    auto gr = qinf::GrammarVocab::parse_impl(QDOCS_GBNF);
    gr->set_token_trie(&trie);
    std::printf("grammar parsed OK (root/pair/key/value/ws)\n");

    // One grounded order email, rendered through the production chat template
    // (thinking off). The grammar emits the '{' opener itself — no prime.
    std::string document =
        "From: purchasing@globex.example\nSubject: New Order\n\n"
        "Hi team,\n\n"
        "Kindly arrange an order for customer Globex Industries.\n"
        "Order date: 2025-11-02.\n"
        "We require a quantity of 875 units.\n"
        "The unit price is 47.30 EUR.\n"
        "The order total comes to 41387.50 EUR.\n\n"
        "Regards.\n";
    std::string body = qdocs_chat_prompt(document);
    std::string instr = "";
    std::vector<std::string> values = {
        "Globex Industries", "2025-11-02", "875", "47.30", "41387.50"};
    const std::string filler = "Hi team,";

    std::vector<int> taps10(attn_layers.begin(), attn_layers.end());  // all 10 attn layers

    // ── Constrained arm (KV grammar, sparse head) ──
    std::vector<GStep> trace;
    FreeRun G = run_freegen_grammar(fp, sched, tok, meta, body, instr, taps10,
                                    220, gr.get(), vocab, vocab_size, &trace);
    std::printf("\n[constrained] gen (%zu tok): %s\n", G.gen_tokens.size(), G.gen_text.c_str());

    // Q1 — rows exist under the sparse-head graph and sum to 1.0.
    std::printf("\n── Q1: kq_soft rows under sparse head ──\n");
    int rows_bad = 0; double worst = 1.0; int checked = 0;
    for (int t = 0; t < (int)G.rows.size(); ++t) {
        int n_kv = G.n_kv_at_step[t];
        for (int slot = 0; slot < (int)taps10.size(); ++slot) {
            for (int h = 0; h < G.n_head; ++h) {
                double s = 0; const float* rr = G.rows[t][slot].data() + (size_t)h * n_kv;
                for (int j = 0; j < n_kv; ++j) s += rr[j];
                checked++;
                if (std::fabs(s - 1.0) > 1e-3) { rows_bad++; if (std::fabs(s - 1.0) > std::fabs(worst - 1.0)) worst = s; }
            }
        }
    }
    int n_sparse_steps = 0; for (auto& g : trace) if (g.sparse) n_sparse_steps++;
    std::printf("  rows checked=%d  bad(|sum-1|>1e-3)=%d  worst_sum=%.6f\n", checked, rows_bad, worst);
    std::printf("  sparse-head steps=%d / %zu decode steps  (rest dense)\n",
                n_sparse_steps, trace.size());
    std::printf("  => rows %s under sparse head\n", rows_bad == 0 ? "MATERIALIZE & sum to 1.0 (PASS)"
                                                                  : "CORRUPT (KILL)");

    // Q2 — signals match constrained vs unconstrained.
    std::printf("\n── Q2: signals constrained vs unconstrained ──\n");
    FreeRun U = run_freegen(fp, sched, tok, meta, body, instr, taps10, 220, false, '}');
    std::printf("[unconstrained] gen (%zu tok): %s\n", U.gen_tokens.size(), U.gen_text.c_str());

    QCite cg = qdocs_cite(tok, G, values, TOL);
    QCite cu = qdocs_cite(tok, U, values, TOL);
    auto pct = [](int a, int b) { return b ? 100.0 * a / b : 0.0; };
    std::printf("\n  citation (frozen L3H13) on value tokens:\n");
    std::printf("    constrained : top1 %d/%d (%.0f%%)  top3 %d/%d (%.0f%%)\n",
                cg.top1, cg.n, pct(cg.top1, cg.n), cg.top3, cg.n, pct(cg.top3, cg.n));
    std::printf("    unconstr.   : top1 %d/%d (%.0f%%)  top3 %d/%d (%.0f%%)\n",
                cu.top1, cu.n, pct(cu.top1, cu.n), cu.top3, cu.n, pct(cu.top3, cu.n));
    double d_top3 = pct(cg.top3, cg.n) - pct(cu.top3, cu.n);
    std::printf("    Δtop3 = %+.0f points  (bar: within 5)  => %s\n", d_top3,
                std::fabs(d_top3) <= 5.0 ? "MATCH" : "DIVERGE");

    std::printf("\n  coverage (frozen layer-11 max-heads peak, thr 0.705):\n");
    auto band = [](double p) { return p < 0 ? "n/a" : (p >= 0.705 ? "USED" : "DROPPED/FILLER"); };
    bool bands_ok = true;
    for (const std::string& v : values) {
        double pg = qdocs_cov_peak(G, v, tok, attn_layers);
        double pu = qdocs_cov_peak(U, v, tok, attn_layers);
        bool same = (pg >= 0.705) == (pu >= 0.705);
        if (!same) bands_ok = false;
        std::printf("    %-20s constrained %.3f [%s]  unconstr %.3f [%s]  %s\n",
                    v.c_str(), pg, band(pg), pu, band(pu), same ? "" : "<< BAND FLIP");
    }
    {
        double pg = qdocs_cov_peak(G, filler, tok, attn_layers);
        double pu = qdocs_cov_peak(U, filler, tok, attn_layers);
        std::printf("    %-20s constrained %.3f [%s]  unconstr %.3f [%s]  (FILLER anchor)\n",
                    filler.c_str(), pg, band(pg), pu, band(pu));
    }
    std::printf("    => coverage band assignments %s\n", bands_ok ? "UNCHANGED (PASS)" : "CHANGED (FAIL)");

    // Eyeball: 3 value tokens under the grammar → frozen L3H13 top-3 attended.
    std::printf("\n  === eyeball (constrained, frozen L3H13): value token → top-3 attended ===\n");
    {
        std::vector<size_t> gcum = cum_bytes(tok, G.gen_tokens);
        std::vector<int32_t> seq = G.prompt_tokens;
        seq.insert(seq.end(), G.gen_tokens.begin(), G.gen_tokens.end());
        int shown = 0;
        for (const std::string& v : {std::string("Globex Industries"),
                                     std::string("2025-11-02"), std::string("47.30")}) {
            size_t gb = G.gen_text.find(v); if (gb == std::string::npos) continue;
            for (int g = 0; g < (int)G.gen_tokens.size(); ++g) {
                if (!(gcum[g] < gb + v.size() && gcum[g + 1] > gb)) continue;
                if (g < 1 || g - 1 >= (int)G.rows.size()) break;
                auto tk = topk_head(G.rows[g - 1][L3H13_SLOT], FROZEN_HEAD, G.n_kv_at_step[g - 1], 3);
                std::string vt = tok->decode(G.gen_tokens[g]);
                for (char& c : vt) if (c == '\n') c = ' ';
                std::printf("  «%s» (value «%s»)\n", vt.c_str(), v.c_str());
                for (int r = 0; r < (int)tk.size(); ++r)
                    std::printf("    #%d pos %3d m%.3f | %s\n", r + 1, tk[r].first, tk[r].second,
                                ctx_around(tok, seq, tk[r].first, 3).c_str());
                break;
            }
            if (++shown >= 3) break;
        }
    }

    // Q3 — elision-hole analysis: which token classes collapse to one legal token?
    std::printf("\n── Q3: forced-token-elision holes ──\n");
    auto is_structural = [](const std::string& s) {
        for (char c : s) if (c != '{' && c != '}' && c != '"' && c != ':' &&
                             c != ',' && c != ' ' && c != '\n' && c != '\t') return false;
        return !s.empty();
    };
    int n_forced = 0, n_forced_value = 0;
    std::printf("  forced (|valid|==1) steps — the elision candidates (no attention row):\n");
    for (int t = 0; t < (int)trace.size(); ++t) {
        if (!trace[t].forced) continue;
        n_forced++;
        bool structural = is_structural(trace[t].forced_tok);
        if (!structural) n_forced_value++;
        std::string vis = trace[t].forced_tok;
        for (char& c : vis) if (c == '\n') c = ' ';
        std::printf("    step %-3d forced=\"%s\" %s\n", t, vis.c_str(),
                    structural ? "[structural]" : "[NON-STRUCTURAL — audit hole!]");
    }
    std::printf("  forced steps=%d  non-structural(value/key)=%d\n", n_forced, n_forced_value);
    std::printf("  => %s\n", n_forced_value == 0
                ? "only structural tokens elide — NO value/key elided (PASS)"
                : "a VALUE/KEY token is elidable — audit hole reported");

    // ── Verdict ──
    std::printf("\n── LEG A VERDICT ──\n");
    bool kill = (rows_bad != 0);
    std::printf("  Q1 rows: %s | Q2 Δtop3=%+.0f, bands %s | Q3 non-struct elisions=%d\n",
                rows_bad == 0 ? "OK" : "CORRUPT", d_top3,
                bands_ok ? "unchanged" : "changed", n_forced_value);
    if (kill) std::printf("  => KILL (rows missing/corrupt under sparse head) — STOP\n");
    else if (std::fabs(d_top3) <= 5.0 && bands_ok)
        std::printf("  => PASS — grammar path preserves the tap and the frozen signals\n");
    else
        std::printf("  => PASS-with-caveat — rows intact; signal drift noted above\n");
    return 0;
}

// ── S1 — STAGE 1 GATE: does the trust layer still tell the truth free-form? ──
// The fixed KV grammar is refuted by measurement on extraction quality
// (docs/note-nogrammar-refutation.md). Before removing it, ONE load-bearing
// question remains: the lens tap math parses the emitted JSON to locate value
// spans, and it has only ever been measured over grammar-shaped output. If
// free-form output breaks the receipts, the grammar has found a real
// justification and Stage 2 is off (docs/handoff-nogrammar-stages.md §S1.2).
//
// Both arms drive the SHIPPED run_lens_extract + compute_lens_report over the
// canonical Leg C corpus, differing ONLY by the grammar pointer (nullptr =
// free). Hint = each document's own labelled (truly present) concepts PLUS two
// concepts verified absent from all 15, exactly as the refutation measured.
//
// THE GATE (re-specified 2026-07-17 — see below for why the original bar could
// not discriminate). It splits TRUTHFULNESS from USEFULNESS:
//
//  - TRUTHFULNESS ("the lens never lies about where the model looked") is gated
//    at ZERO by the DETERMINISTIC LensFidelityGate in tests/unit/test_server_lens.cpp
//    — model-free, synthesized rows, and it has teeth (FiresOnConfidentMisattribution).
//    That is the real instrument; a live corpus cannot gate a by-construction property.
//  - USEFULNESS is what this live probe gates:
//      (a) free-arm top-3 in-span == 100% — the value's own source appears in the
//          reported citation SET (the format ships citations[], not one citation), and
//      (b) LIKE-FOR-LIKE: on fields where BOTH arms emit the SAME value, free's
//          top-1 is never worse than constrained's.
//
// Why not the original "zero top-1 false receipts, free-form"? Measured, it
// rejects the SHIPPED constrained path too (1), so it discriminates nothing:
//  1. Every free-arm miss is ONE characterised class — a `customer` value cited to
//     the sender's email DOMAIN (customer="Harbour Point Marine" → "point" inside
//     sam@harbourpoint.example). The model really did read the domain to get the
//     company name, so the receipt is FAITHFUL; it just is not the verbatim body
//     occurrence. Top-3 contains that occurrence in every case.
//  2. The constrained arm shows the IDENTICAL case on m_en6 (mass 0.216 vs 0.213)
//     ⇒ the phenomenon is grammar-independent. It is the model, not the constraint.
//  3. The bar REWARDS COLLAPSE: under the grammar m_de7 collapses to 67 junk `", "`
//     fields, which are not verbatim in the document and are therefore excluded —
//     a DESTROYED document scores zero false receipts. Absolute counts across
//     different claim sets are confounded; (b) fixes that by construction.
// (plan-qemmi-lens.md §5 scoped A5.4's zero to the FIXTURE corpus all along; the
// handoff extended it to a live corpus without measuring that the claim held.)
//
//   QDOCS_S1=1 ./bin/attn-provenance
static int run_qdocs_s1(ForwardPassBase* fp, ggml_backend_sched_t sched,
                        Tokenizer* tok, const ModelMetadata& meta, uint32_t n_ctx) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ STAGE 1 GATE — the trust layer over FREE-FORM output (15 docs)║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");

    const int TOL = 2;
    // Verified absent from all 15 Leg C documents — any value for either is a
    // fabrication (mirrors py/lens_legc_nogrammar.py ABSENT).
    const std::vector<std::string> ABSENT = {"payment_terms", "warranty_period"};

    const std::vector<std::string>& vocab = tok->get_vocabulary();
    const uint32_t vocab_size = (uint32_t)vocab.size();
    qinf::TokenTrie trie; trie.build(vocab);
    auto gr = qinf::GrammarVocab::parse_impl(qinf::lens_grammar_gbnf());
    gr->set_token_trie(&trie);

    auto corpus = qdocs_messy_corpus();
    std::printf("corpus=%zu docs  eos_id=%d  ctx=%u\n",
                corpus.size(), (int)tok->get_eos_token_id(), n_ctx);

    // One emitted field, kept per doc/key so the two arms can be compared
    // LIKE-FOR-LIKE (same key, same value) instead of by confounded totals.
    // top1_mass vs in_span_mass is the MARGIN: how decisively the out-of-span
    // citation beat the value's own source. A hair-thin margin means the two
    // arms flipped a near-tie, not that the grammar bought anything.
    struct FieldRec {
        std::string value;
        bool   checked = false, top1 = false, top3 = false;
        double top1_mass = 0.0;     // mass of citations[0]
        double in_span_mass = 0.0;  // mass of the best citation that IS in-span (0 = none)
        int    in_span_rank = -1;   // its rank in citations[] (0-based)
    };
    struct Arm {
        int docs = 0, fields_located = 0;
        int receipts = 0, top1 = 0, top3 = 0, false_receipts = 0;
        int fid_ok = 0, fid_tot = 0, absent_ok = 0, absent_tot = 0;
        std::vector<std::string> fabricated, empty_docs, false_docs, unparseable;
        std::vector<std::map<std::string, FieldRec>> per_doc;  // [doc index][key]
    };

    // Does any of the top-n citations land on a real source of the value?
    auto cited_in_span = [&](const qinf::LensField& f, const std::string& doc, int topn) {
        for (int i = 0; i < (int)f.citations.size() && i < topn; ++i)
            if (qinf::lens_cites_a_real_source(doc, f.value, f.citations[i].byte_lo,
                                                  f.citations[i].byte_hi, TOL))
                return true;
        return false;
    };
    auto norm = [](std::string s) {
        std::string o; bool sp = false;
        for (char c : s) {
            if (std::isspace((unsigned char)c)) { sp = !o.empty(); continue; }
            if (sp) { o += ' '; sp = false; }
            o += (char)std::tolower((unsigned char)c);
        }
        return o;
    };
    // A DECLINE is the model saying "not stated". `","` is NOT a decline — it is
    // the collapse (m_de7 emits it for every key, present ones included), i.e.
    // garbage. Counting it as declined FLATTERS the grammar's absent score. The
    // list matches py/lens_legc_nogrammar.py exactly: the two probes must never
    // score the same event differently.
    auto declined = [&](const std::string& v) {
        const std::string n = norm(v);
        return n.empty() || n == "null" || n == "none" || n == "n/a" || n == "-";
    };

    auto run_arm = [&](const char* tag, qinf::GrammarVocab* grammar) -> Arm {
        Arm A;
        std::printf("\n%s\n ARM: %s\n%s\n", std::string(72, '=').c_str(),
                    grammar ? "FIXED KV GRAMMAR" : "NO GRAMMAR (free decode)",
                    std::string(72, '=').c_str());
        for (const QMessy& d : corpus) {
            std::vector<qinf::LensConcept> concepts;
            for (const QLabel& f : d.fields) concepts.push_back({f.concept, ""});
            for (const std::string& a : ABSENT) concepts.push_back({a, ""});

            qinf::LensExtractOptions opts;
            opts.max_new_tokens = 400;
            // `grammar` is the CONTROL ARM seam (null ⇒ the shipped free path).
            // Both arms run the same driver, which is the whole point: the grammar
            // is the only variable, and the free arm under test is product code.
            qinf::LensReport r;
            try {
                r = qinf::run_lens_extract(
                    fp, sched, tok, meta, vocab_size, n_ctx, d.document, concepts,
                    opts, qinf::LensConstants{}, grammar, grammar ? &vocab : nullptr);
            } catch (const qinf::LensUnparseableError& e) {
                // The shape contract firing. Report it as the loud refusal it is —
                // do NOT skip the doc silently, that would flatter the arm.
                A.docs++;
                A.unparseable.push_back(d.tag);
                A.fid_tot += (int)d.fields.size();
                A.absent_tot += (int)ABSENT.size();
                A.per_doc.emplace_back();
                std::printf("\n[%s%s] 422 UNPARSEABLE — extraction refused\n  %.140s\n",
                            d.tag.c_str(), d.de ? " DE" : "", e.raw.c_str());
                continue;
            }

            A.docs++;
            A.fields_located += (int)r.fields.size();
            if (r.fields.empty()) A.empty_docs.push_back(d.tag);

            const int fr = qinf::lens_count_confident_false_receipts(r, TOL);
            A.false_receipts += fr;
            if (fr) A.false_docs.push_back(d.tag);

            // Header first — the diagnostics below belong to THIS document.
            std::printf("\n[%s%s] fields=%zu false_receipts=%d\n  %s\n",
                        d.tag.c_str(), d.de ? " DE" : "", r.fields.size(), fr,
                        r.raw_json.substr(0, 160).c_str());

            // A gate that fails must say WHY, or it cannot be acted on. For each
            // false receipt print the value, where the receipt points, and where
            // the value actually occurs — enough to tell a LIE (the lens claims a
            // source the model never read) from a DEFINITION artifact (the model
            // truly read that span, but it sits outside this value's occurrence).
            for (const auto& f : r.fields) {
                if (!f.grounded || !f.found_in_document) continue;
                if (qinf::lens_value_tier(f.value) != "distinctive") continue;
                if (f.citations.empty()) { std::printf("    !! %s: NO CITATIONS\n", f.key.c_str()); continue; }
                if (cited_in_span(f, r.document_text, 1)) continue;
                const auto& c = f.citations[0];
                std::string at = c.byte_lo < r.document_text.size()
                    ? r.document_text.substr(c.byte_lo, std::min<size_t>(c.byte_hi - c.byte_lo, 24))
                    : std::string("<out of doc>");
                std::printf("    !! FALSE RECEIPT %s=\"%s\"\n", f.key.c_str(), f.value.c_str());
                std::printf("       top-1 cites [%zu,%zu) = \"%s\" (mass %.3f)\n",
                            c.byte_lo, c.byte_hi, at.c_str(), c.mass);
                std::printf("       value occurs at:");
                for (size_t o = r.document_text.find(f.value); o != std::string::npos;
                     o = r.document_text.find(f.value, o + 1))
                    std::printf(" [%zu,%zu)", o, o + f.value.size());
                std::printf("\n       top-3:");
                for (int i = 0; i < (int)f.citations.size() && i < 3; ++i) {
                    const auto& ci = f.citations[i];
                    std::string t = ci.byte_lo < r.document_text.size()
                        ? r.document_text.substr(ci.byte_lo, std::min<size_t>(ci.byte_hi - ci.byte_lo, 16))
                        : std::string("?");
                    std::printf("  [%zu)=\"%s\"", ci.byte_lo, t.c_str());
                }
                std::printf("\n");
            }

            // In-span citation rate over the fields the format makes a claim for.
            A.per_doc.emplace_back();
            for (const auto& f : r.fields) {
                FieldRec rec; rec.value = f.value;
                if (f.grounded && f.found_in_document &&
                    qinf::lens_value_tier(f.value) == "distinctive") {
                    rec.checked = true;
                    rec.top1 = cited_in_span(f, r.document_text, 1);
                    rec.top3 = cited_in_span(f, r.document_text, 3);
                    if (!f.citations.empty()) rec.top1_mass = f.citations[0].mass;
                    for (int i = 0; i < (int)f.citations.size(); ++i)
                        if (qinf::lens_cites_a_real_source(r.document_text, f.value,
                                f.citations[i].byte_lo, f.citations[i].byte_hi, TOL)) {
                            rec.in_span_mass = f.citations[i].mass;
                            rec.in_span_rank = i;
                            break;  // citations are mass-sorted: first hit is the best
                        }
                    A.receipts++;
                    A.top1 += rec.top1;
                    A.top3 += rec.top3;
                }
                A.per_doc.back().emplace(f.key, rec);  // first wins (a collapse repeats keys)
            }
            // Fidelity vs the corpus labels; absent handling on the two planted keys.
            auto value_of = [&](const std::string& key) -> const qinf::LensField* {
                for (const auto& f : r.fields) if (f.key == key) return &f;
                return nullptr;
            };
            for (const QLabel& lf : d.fields) {
                A.fid_tot++;
                const qinf::LensField* got = value_of(lf.concept);
                if (!got) continue;
                const std::string t = norm(lf.value), g = norm(got->value);
                if (!g.empty() && (t.find(g) != std::string::npos || g.find(t) != std::string::npos))
                    A.fid_ok++;
            }
            for (const std::string& key : ABSENT) {
                A.absent_tot++;
                const qinf::LensField* got = value_of(key);
                if (!got || declined(got->value)) A.absent_ok++;
                else A.fabricated.push_back(d.tag + ":" + key + "=\"" + got->value + "\"");
            }
        }
        return A;
    };

    Arm ng = run_arm("NG", nullptr);
    Arm gp = run_arm("GR", gr.get());

    auto pct = [](int a, int b) { return b ? 100.0 * a / b : 0.0; };
    auto report = [&](const char* name, const Arm& A) {
        std::printf("\n  -- %s --\n", name);
        // NOT the gate (see the header): counts the customer→sender-domain class,
        // where the lens is truthful and top-3 finds the body mention. Reported
        // because it is the number the original, mis-specified bar looked at.
        std::printf("     confident false receipts  %d        <- reported, NOT gated\n",
                    A.false_receipts);
        std::printf("     in-span citation  top-1   %d/%d (%.0f%%)   top-3 %d/%d (%.0f%%)\n",
                    A.top1, A.receipts, pct(A.top1, A.receipts),
                    A.top3, A.receipts, pct(A.top3, A.receipts));
        std::printf("     fields located            %d\n", A.fields_located);
        std::printf("     value fidelity            %d/%d\n", A.fid_ok, A.fid_tot);
        std::printf("     absent handled            %d/%d\n", A.absent_ok, A.absent_tot);
        if (!A.fabricated.empty()) {
            std::printf("     FABRICATED (%zu):\n", A.fabricated.size());
            for (size_t i = 0; i < A.fabricated.size() && i < 6; ++i)
                std::printf("       %s\n", A.fabricated[i].c_str());
        }
        if (!A.empty_docs.empty()) {
            std::printf("     NO FIELDS LOCATED:");
            for (const auto& t : A.empty_docs) std::printf(" %s", t.c_str());
            std::printf("\n");
        }
        if (!A.false_docs.empty()) {
            std::printf("     FALSE-RECEIPT DOCS:");
            for (const auto& t : A.false_docs) std::printf(" %s", t.c_str());
            std::printf("\n");
        }
        if (!A.unparseable.empty()) {
            std::printf("     422 UNPARSEABLE (refused, not partially reported):");
            for (const auto& t : A.unparseable) std::printf(" %s", t.c_str());
            std::printf("\n");
        }
    };
    report("NO GRAMMAR (free)", ng);
    report("FIXED KV GRAMMAR", gp);

    std::printf("\n%s\n", std::string(72, '=').c_str());
    std::printf("%-26s%14s%14s\n", "axis", "no grammar", "grammar");
    std::printf("%-26s%14d%14d\n", "confident false receipts", ng.false_receipts, gp.false_receipts);
    std::printf("%-26s%13.0f%%%13.0f%%\n", "in-span top-1", pct(ng.top1, ng.receipts), pct(gp.top1, gp.receipts));
    std::printf("%-26s%13.0f%%%13.0f%%\n", "in-span top-3", pct(ng.top3, ng.receipts), pct(gp.top3, gp.receipts));
    std::printf("%-26s%14d%14d\n", "fields located", ng.fields_located, gp.fields_located);
    std::printf("%-26s%9d/%-4d%9d/%-4d\n", "value fidelity", ng.fid_ok, ng.fid_tot, gp.fid_ok, gp.fid_tot);
    std::printf("%-26s%9d/%-4d%9d/%-4d\n", "absent handled", ng.absent_ok, ng.absent_tot, gp.absent_ok, gp.absent_tot);

    // ── LIKE-FOR-LIKE: only fields where both arms emit the SAME value ────────
    // Absolute totals are confounded — the arms make different claims on
    // different values, and a collapsed doc silently drops out of the denominator.
    // Comparing identical (key, value) pairs removes both effects.
    // (b) is RANK-FREE: it asks the question the rank flip only proxied — did
    // removing the grammar make the value's OWN source less attended? Rank order
    // between two genuine sources turns on hundredths of mass, and handoff §4 is
    // explicit: Metal is token-stable-not-byte-identical, gate on structure and
    // rates, NOT exact masses. A rank-flip gate resolves exactly the tie-breaks
    // that invariant forbids. Mass retention does not.
    //
    // Teeth: if free-form broke the value-span location (the S1.2 fear), in-span
    // mass COLLAPSES toward zero — a −100% move, not a wobble.
    //
    // MEASURED (2026-07-17): the per-pair cross-arm spread on IDENTICAL values is
    // min −31.3% / mean −1.0% / max +10.8% over 42 pairs — so no useful per-pair
    // tolerance fits under the noise, and a threshold tuned to pass would be
    // circular. The spread is also partly an artifact: citations[].mass is
    // normalized by the value's token count, and the arms tokenize the same value
    // differently (`": "` vs `":"`), so per-pair masses are not strictly
    // commensurable across arms. Hence the criterion is applied to the MEAN — a
    // rate, which is what handoff §4 permits — with the distribution always
    // printed so a real collapse (−100%) is unmissable, plus a constant-free
    // structural check (every like-for-like field must cite a real source at all).
    const double MEAN_TOL = 0.10;   // mean retention floor; measured mean is −1.0%
    const double REPORT_AT = 0.20;  // per-pair outliers listed for inspection, NOT gated
    int lfl = 0, outliers = 0, no_source = 0;
    double rel_min = 1e9, rel_max = -1e9, rel_sum = 0.0; int rel_n = 0;
    std::vector<std::string> detail;
    for (size_t i = 0; i < corpus.size() && i < ng.per_doc.size() && i < gp.per_doc.size(); ++i) {
        for (const auto& kv : ng.per_doc[i]) {
            auto it = gp.per_doc[i].find(kv.first);
            if (it == gp.per_doc[i].end()) continue;
            const FieldRec& nf = kv.second;
            const FieldRec& gf = it->second;
            if (!nf.checked || !gf.checked || nf.value != gf.value) continue;
            lfl++;
            // Structural, constant-free: the value's own source must be cited AT ALL.
            if (nf.in_span_rank < 0) {
                no_source++;
                char b[256];
                std::snprintf(b, sizeof(b), "\n     %s:%s = \"%s\" — free cites NO real source",
                              corpus[i].tag.c_str(), kv.first.c_str(), nf.value.c_str());
                detail.push_back(b);
                continue;
            }
            if (gf.in_span_mass <= 0.0) continue;  // no grammar baseline to compare against
            const double rel = (nf.in_span_mass - gf.in_span_mass) / gf.in_span_mass;
            rel_min = std::min(rel_min, rel); rel_max = std::max(rel_max, rel);
            rel_sum += rel; rel_n++;
            if (rel < -REPORT_AT) {
                outliers++;  // reported, not gated — see MEAN_TOL above
                char b[384];
                std::snprintf(b, sizeof(b),
                    "\n     %s:%s = \"%s\" — in-span mass free %.4f vs grammar %.4f (%+.1f%%)",
                    corpus[i].tag.c_str(), kv.first.c_str(), nf.value.c_str(),
                    nf.in_span_mass, gf.in_span_mass, 100.0 * rel);
                detail.push_back(b);
            }
        }
    }
    std::printf("\nlike-for-like (same key AND same value, both checked): %d pairs\n", lfl);
    std::printf("   in-span MASS retention, free vs grammar (rank-free):\n");
    std::printf("     min %+.1f%%   mean %+.1f%%   max %+.1f%%   over %d pairs\n",
                100.0 * rel_min, 100.0 * (rel_n ? rel_sum / rel_n : 0.0), 100.0 * rel_max, rel_n);
    std::printf("     GATED on the mean (floor -%.0f%%); a broken value-span location reads -100%%\n",
                100.0 * MEAN_TOL);
    std::printf("   free cites no real source: %d (gated)  |  per-pair outliers below -%.0f%%: %d (reported only)",
                no_source, 100.0 * REPORT_AT, outliers);
    for (const auto& s : detail) std::printf("%s", s.c_str());
    std::printf("\n");

    // Stage 1 exit criteria, re-specified 2026-07-17 (see the header block).
    const double rel_mean = rel_n ? rel_sum / rel_n : 0.0;
    const bool gate_top3 = (ng.receipts > 0) && (ng.top3 == ng.receipts);
    const bool gate_lfl  = (lfl > 0) && (no_source == 0) && (rel_mean >= -MEAN_TOL);
    std::printf("\nSTAGE 1 GATE (a): free top-3 in-span == 100%%       : %s (%d/%d)\n",
                gate_top3 ? "PASS" : "FAIL", ng.top3, ng.receipts);
    std::printf("STAGE 1 GATE (b): free retains in-span mass       : %s (%d pairs, mean %+.1f%%, %d unsourced)\n",
                gate_lfl ? "PASS" : "FAIL", lfl, 100.0 * rel_mean, no_source);
    std::printf("\nFYI (not a gate): top-1 absolute %.0f%% free vs %.0f%% grammar — confounded,\n"
                "  the arms claim different values and a collapsed doc scores no false receipts.\n",
                pct(ng.top1, ng.receipts), pct(gp.top1, gp.receipts));
    std::printf("\n%s\n", (gate_top3 && gate_lfl)
                ? "STAGE 1 (S1.2) GREEN — free-form does not degrade the receipts."
                : "STAGE 1 (S1.2) RED — the grammar may have a real justification; record it.");
    return (gate_top3 && gate_lfl) ? 0 : 1;
}

// ── CAND — candidate-set cheap-kill gate (docs/plan-candidate-set.md) ────────
// Tests Gate 2 of the plan BEFORE any format/endpoint/schema work: does a cold
// two-pass candidate finder emit exactly one span per UNCONTESTED key, or does
// it over-report type-matches? Gates 1 (human precision) and 3 (seeded-conflict
// recall) are out of scope here — see the plan and the task brief.
//
// Pass 1 is the shipped free-decode extraction path, byte-identical to the NG
// arm of QDOCS_S1: run_lens_extract() with no grammar, on the same per-doc key
// vocabulary (qdocs_messy_corpus() labels + the two verified-absent probes).
// Pass 2 is a SEPARATE cold inference over the same document — fresh slot, full
// prefill, a different instruction, taps DISARMED (run_freegen with an empty
// tap_layers list — no kq_soft capture, which is also what makes flash
// attention available in the real design). It asks the model to list every
// span answering each hinted key, quoted verbatim from the document.
static const char* CAND_PASS2_TASK_PREFIX =
    "\n\nFor each of the following keys, list every span in the document above "
    "that could answer it — for example a clause and a later amendment that both "
    "give an amount are TWO spans for the same key, not one. Quote each span "
    "EXACTLY as it appears in the document above: do not paraphrase, reformat, "
    "translate, or combine spans. Write one span per line, in the exact form "
    "key: \"span\". A key may have zero, one, or several spans; if it has none, "
    "write key: (none). List every span for one key before moving to the next "
    "key. Output only the list, nothing else. Keys: ";

// Permissive line parser for pass 2's free-form output — not a grammar, so this
// tolerates bullets/numbering and only requires `known_key: "span"` somewhere
// on the line. Returns (key, span) pairs in EMISSION order; the caller dedups
// and sorts into document order.
static std::vector<std::pair<std::string, std::string>>
cand_parse_pass2(const std::string& text, const std::vector<std::string>& keys) {
    std::vector<std::pair<std::string, std::string>> out;
    std::set<std::string> keyset(keys.begin(), keys.end());
    std::istringstream iss(text);
    std::string line;
    while (std::getline(iss, line)) {
        size_t b = 0;
        while (b < line.size() &&
               (std::isspace((unsigned char)line[b]) || line[b] == '-' || line[b] == '*' ||
                std::isdigit((unsigned char)line[b]) || line[b] == '.' || line[b] == ')'))
            b++;
        std::string rest = line.substr(b);
        size_t colon = rest.find(':');
        if (colon == std::string::npos) continue;
        std::string key = rest.substr(0, colon);
        while (!key.empty() && std::isspace((unsigned char)key.back())) key.pop_back();
        if (!keyset.count(key)) continue;
        std::string val = rest.substr(colon + 1);
        std::string span;
        size_t q1 = val.find('"');
        if (q1 != std::string::npos) {
            size_t q2 = val.find('"', q1 + 1);
            if (q2 == std::string::npos) continue;   // unterminated quote — malformed
            span = val.substr(q1 + 1, q2 - q1 - 1);
        } else {
            // TOLERANT PARSE. The strict version required key: "span" and dropped
            // any unquoted line. The model honours the requested format on most
            // documents but not all — m_en1 emitted EVERY line unquoted, all of
            // them correct, and the strict parser silently discarded the lot. The
            // probe then reported "(no candidates)", which is indistinguishable
            // from "this document offers no answers" — a producer defect wearing
            // the costume of a fact about the document. Same lesson the fixed KV
            // grammar taught (docs/note-nogrammar-refutation.md): free decode does
            // not reliably emit one shape, so the parse must be tolerant.
            span = val;
            size_t a = 0;
            while (a < span.size() && std::isspace((unsigned char)span[a])) a++;
            span.erase(0, a);
            while (!span.empty() && std::isspace((unsigned char)span.back())) span.pop_back();
            // "(none)" is a real ANSWER (this key has no candidate), not a parse
            // failure — must not be counted as either a span or a malformed line.
            if (span == "(none)" || span == "none" || span == "-") continue;
        }
        if (!span.empty()) out.emplace_back(key, span);
    }
    return out;
}

// ── QKEY — question-key probe (docs/plan-question-keys.md §4) ───────────────
// Matched pairs, the design that caught what coverage could not in SS3: same
// documents, same expected values, same taps, same calibrated head, same
// max_new_tokens, same greedy decode. The ONLY variable is whether a
// vocabulary entry is an identifier (Arm K, control) or a question (Arm Q).
// Byte-inert when QKEY is unset (this function is only ever reached from the
// QKEY dispatch below). Arm S (the 768-head sweep) is explicitly OUT OF SCOPE
// here — if Arm Q fails its bar, the report says Arm S is indicated and stops.
// GGUF general.file_type — third field of the lens calibration key.
// Same contract as http_server.cpp's copy: absent matches no PINNED row.
static uint32_t probe_lens_file_type(const ModelMetadata& meta) {
    const std::optional<uint32_t> ft = meta.raw_kv.get_uint32_opt("general.file_type");
    return ft ? *ft : qinf::kLensAnyFileType;
}

static int run_qkey_probe(ForwardPassBase* fp, ggml_backend_sched_t sched,
                          Tokenizer* tok, const ModelMetadata& meta, uint32_t n_ctx) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ QKEY — question-key probe (docs/plan-question-keys.md §4)      ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");

    // This model's own calibrated citation coordinates — NOT the global
    // FROZEN_SLOT/HEAD defaults (those are Qwen 3.6 L3H13 unless overridden by
    // ATTN_FROZEN_SLOT/HEAD, which this run does not set). Looking the model up
    // in the same table production uses means the probe is correct regardless
    // of env state, and fails loud instead of silently scoring the wrong head.
    const qinf::LensCalibration* calib =
        qinf::lens_calibration_for(meta.architecture, meta.block_count,
                                   probe_lens_file_type(meta));
    if (!calib) {
        std::fprintf(stderr, "QKEY: expected a calibrated lens entry for arch '%s' "
                             "block_count %u, actual none present — %s\n",
                     meta.architecture.c_str(), meta.block_count,
                     qinf::lens_calibration_refusal(meta.architecture, meta.block_count,
                                                    probe_lens_file_type(meta)).c_str());
        return 1;
    }
    const int qkey_layer = calib->constants.citation_layer;
    const int qkey_head  = calib->constants.citation_head;
    int qkey_slot = -1;
    for (size_t i = 0; i < g_attn_layers->size(); ++i)
        if ((*g_attn_layers)[i] == qkey_layer) { qkey_slot = (int)i; break; }
    if (qkey_slot < 0) {
        std::fprintf(stderr, "QKEY: expected citation_layer %d among the %zu discovered "
                             "attention layers, actual not found\n",
                     qkey_layer, g_attn_layers->size());
        return 1;
    }
    // Leg C's scoring (qdocs_eval_field) reads the FROZEN_SLOT/HEAD globals,
    // not parameters — point them at THIS model's calibration once, up front,
    // so both arms score against the identical, correct head.
    L3H13_SLOT  = qkey_slot;
    FROZEN_SLOT = qkey_slot;
    FROZEN_HEAD = qkey_head;
    std::printf("calibration: %s — citation L%dH%d (tap slot %d)\n",
                calib->model, qkey_layer, qkey_head, qkey_slot);

    // Mechanical concept -> question rewrite table, shared with LOCHEAD's
    // question arm so the two cannot drift onto different wordings.
    const std::map<std::string, std::string>& QUESTION_FOR = lens_concept_questions();

    const int TOL = 2;
    const int MAX_NEW = 400;   // same budget as the CAND pass-1 extraction
    auto corpus = qdocs_messy_corpus();
    std::vector<int> taps(g_attn_layers->begin(), g_attn_layers->end());

    struct Acc { int cite_n = 0, t1 = 0, t3 = 0, labeled = 0, extractive = 0; };
    Acc armK, armQ;
    std::map<int, int> head_hist;   // Arm Q argmax-head distribution, over fields
    int head_fields = 0;

    // TASK wording is IDENTICAL between arms; only the key list differs — that
    // is the one variable plan §4 requires.
    auto build_task = [](const std::vector<std::string>& keys) {
        std::string t = "\n\nExtract the following from the email above into a flat JSON "
            "object of \"key\": \"value\" pairs, using EXACTLY these keys, verbatim. "
            "Copy each value verbatim from the email. Output ONLY the JSON object, "
            "nothing else. Keys: ";
        for (size_t i = 0; i < keys.size(); ++i) t += (i ? ", " : "") + keys[i];
        return t;
    };
    auto ws_normalize = [](const std::string& s) {
        std::string out; bool sp = false;
        for (char c : s) {
            if (std::isspace((unsigned char)c)) { sp = true; continue; }
            if (sp && !out.empty()) out += ' ';
            sp = false; out += c;
        }
        return out;
    };

    for (const QMessy& d : corpus) {
        for (int arm = 0; arm < 2; ++arm) {   // 0 = K (control, identifiers), 1 = Q (questions)
            std::vector<std::string> keys;
            for (const QLabel& f : d.fields)
                keys.push_back(arm == 0 ? f.concept : QUESTION_FOR.at(f.concept));
            std::string prompt = qdocs_chat_prompt(d.document, build_task(keys));
            FreeRun R = run_freegen(fp, sched, tok, meta, prompt, "", taps, MAX_NEW);

            int doc_lo, doc_hi;
            if (!qdocs_span_in_prompt(tok, R, d.document, doc_lo, doc_hi)) { doc_lo = 0; doc_hi = R.P - 1; }

            Acc& A = arm == 0 ? armK : armQ;
            for (const QLabel& f : d.fields) {
                A.labeled++;
                QFieldEval e = qdocs_eval_field(tok, R, f.value, doc_lo, doc_hi, *g_attn_layers, TOL);
                if (e.found_verbatim) {
                    A.extractive++;
                    A.cite_n += e.cite_n; A.t1 += e.cite_t1; A.t3 += e.cite_t3;
                } else if (arm == 1) {
                    // whitespace-normalized-exact fallback — extractiveness bar only.
                    std::string nv = ws_normalize(f.value), ng = ws_normalize(R.gen_text);
                    if (!nv.empty() && ng.find(nv) != std::string::npos) A.extractive++;
                }
                // Head agreement (Arm Q only): among ALL heads at the calibrated
                // citation LAYER, which one has the single sharpest (highest
                // top-1 weight) attention at the first gen step overlapping the
                // true value? This is a within-layer check, not the 768-head
                // sweep (Arm S) — it answers "did the SAME head stay sharpest",
                // not "is some other layer's head now sharper".
                if (arm == 1 && e.found_verbatim) {
                    std::vector<size_t> gcum = cum_bytes(tok, R.gen_tokens);
                    size_t gb = R.gen_text.find(f.value);
                    if (gb != std::string::npos) {
                        size_t ge = gb + f.value.size();
                        for (int g = 0; g < (int)R.gen_tokens.size(); ++g) {
                            if (!(gcum[g] < ge && gcum[g + 1] > gb)) continue;
                            if (g < 1 || g - 1 >= (int)R.rows.size()) continue;
                            int n_kv = R.n_kv_at_step[g - 1];
                            const auto& row = R.rows[g - 1][qkey_slot];
                            int n_head = n_kv ? (int)(row.size() / n_kv) : 0;
                            int best_h = -1; float best_w = -1.f;
                            for (int h = 0; h < n_head; ++h) {
                                auto tk = topk_head(row, h, n_kv, 1);
                                if (!tk.empty() && tk[0].second > best_w) { best_w = tk[0].second; best_h = h; }
                            }
                            if (best_h >= 0) { head_hist[best_h]++; head_fields++; }
                            break;   // first overlapping gen step only
                        }
                    }
                }
            }
        }
    }

    auto pct = [](int a, int b) { return b ? 100.0 * a / b : 0.0; };

    // ── 1. Extractiveness (Arm Q) — the cheapest kill; print it first ────────
    double extr = pct(armQ.extractive, armQ.labeled);
    bool bar_extr = extr >= 90.0;
    std::printf("\n================ 1. EXTRACTIVENESS — Arm Q (CHEAPEST KILL) ================\n");
    std::printf("byte-exact or whitespace-normalized-exact slices of the document: %d/%d (%.0f%%)  [bar >= 90%%]\n",
                armQ.extractive, armQ.labeled, extr);
    std::printf("VERDICT: %s\n", bar_extr ? "PASS"
                : "FAIL — questions pull the model off extraction; nothing below can be trusted to matter");

    // ── 2/3. Citation top-1 / top-3, Arm K vs Arm Q ──────────────────────────
    double k1 = pct(armK.t1, armK.cite_n), k3 = pct(armK.t3, armK.cite_n);
    double q1 = pct(armQ.t1, armQ.cite_n), q3 = pct(armQ.t3, armQ.cite_n);
    std::printf("\n================ 2. CITATION — Arm K (control, identifier keys) ================\n");
    std::printf("top1 %d/%d (%.0f%%)  top3 %d/%d (%.0f%%)  [scoreable/verbatim fields: %d/%d]\n",
                armK.t1, armK.cite_n, k1, armK.t3, armK.cite_n, k3, armK.extractive, armK.labeled);
    std::printf("\n================ 3. CITATION — Arm Q (question keys) ================\n");
    std::printf("top1 %d/%d (%.0f%%)  top3 %d/%d (%.0f%%)  [scoreable/verbatim fields: %d/%d]\n",
                armQ.t1, armQ.cite_n, q1, armQ.t3, armQ.cite_n, q3, armQ.extractive, armQ.labeled);

    // ── Reproduction check — Arm K must land near the published 89%/98% ──────
    bool repro = std::fabs(k1 - 89.0) <= 2.0 && std::fabs(k3 - 98.0) <= 2.0;
    std::printf("\n================ REPRODUCTION CHECK — Arm K vs published Qwen3.8-9B (89%%/98%%) ================\n");
    std::printf("Arm K top1 %.0f%% (published 89%%, delta %+.1f)  top3 %.0f%% (published 98%%, delta %+.1f)\n",
                k1, k1 - 89.0, k3, k3 - 98.0);
    std::printf("VERDICT: %s\n", repro ? "PASS — probe is correctly configured"
                : "FAIL — probe is MISCONFIGURED; treat every other number here with suspicion");

    // ── 4. Head agreement, Arm Q ──────────────────────────────────────────────
    int on_head = head_hist.count(qkey_head) ? head_hist[qkey_head] : 0;
    std::printf("\n================ 4. HEAD AGREEMENT — Arm Q (calibrated head L%dH%d) ================\n",
                qkey_layer, qkey_head);
    std::printf("argmax head stayed H%d: %d/%d fields (%.0f%%)\n",
                qkey_head, on_head, head_fields, pct(on_head, head_fields));
    std::printf("distribution over heads (head:count of fields where it was sharpest):\n  ");
    for (auto& kv : head_hist) std::printf("H%d:%d  ", kv.first, kv.second);
    std::printf("\n");

    // ── 5. Delta — Arm K top3 minus Arm Q top3 ───────────────────────────────
    double delta = k3 - q3;
    bool bar_delta = delta <= 5.0;
    std::printf("\n================ 5. DELTA — Arm K top3 minus Arm Q top3 ================\n");
    std::printf("%.1f points  [bar <= 5.0]\n", delta);
    std::printf("VERDICT: %s\n", bar_delta ? "PASS" : "FAIL — the prompt shape moves the head; constants are task-shaped");

    bool bar2 = q3 >= 90.0;
    std::printf("\n================ SUMMARY ================\n");
    std::printf("bar1 Arm K reproduces published numbers (within 2pt): %s\n", repro ? "PASS" : "FAIL");
    std::printf("bar2 Arm Q citation top3 >= 90%%:                      %s (%.0f%%)\n", bar2 ? "PASS" : "FAIL", q3);
    std::printf("bar3 Arm K - Arm Q top3 <= 5pt:                       %s (%.1f)\n", bar_delta ? "PASS" : "FAIL", delta);
    std::printf("bar4 Arm Q extractiveness >= 90%%:                     %s (%.0f%%)\n", bar_extr ? "PASS" : "FAIL", extr);
    if (!bar2)
        std::printf("Arm Q failed its bar — Arm S (the 768-head sweep) is indicated as the next step; NOT implemented here.\n");

    return (repro && bar2 && bar_delta && bar_extr) ? 0 : 1;
}

static int run_cand_probe(ForwardPassBase* fp, ggml_backend_sched_t sched,
                          Tokenizer* tok, const ModelMetadata& meta, uint32_t n_ctx) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ CAND — candidate-set cheap-kill gate (plan-candidate-set.md)   ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");

    const std::vector<std::string> ABSENT = {"payment_terms", "warranty_period"};
    const std::vector<std::string>& vocab = tok->get_vocabulary();
    const uint32_t vocab_size = (uint32_t)vocab.size();
    auto corpus = qdocs_messy_corpus();
    int n_unparseable = 0;   // producer failures — see the FAIL LOUD block below
    std::printf("corpus=%zu docs  ctx=%u\n", corpus.size(), n_ctx);

    struct CandSet {
        std::string p1_value;
        bool p1_grounded = false;
        bool p1_present  = false;
        std::vector<std::string> cands;  // deduped, document order (found-in-doc first)
    };
    struct DocOut { std::string tag, document; bool de; std::map<std::string, CandSet> per_key;
                    std::set<std::string> uncontested; double p2_latency_s = 0; };
    std::vector<DocOut> docs_out;

    for (const QMessy& d : corpus) {
        std::vector<qinf::LensConcept> concepts;
        for (const QLabel& f : d.fields) concepts.push_back({f.concept, ""});
        for (const std::string& a : ABSENT) concepts.push_back({a, ""});
        std::vector<std::string> keys;
        for (auto& c : concepts) keys.push_back(c.key);

        // ── Pass 1 — unchanged extraction (shipped free path, no grammar) ────
        qinf::LensExtractOptions opts; opts.max_new_tokens = 400;
        qinf::LensReport r;
        try {
            r = qinf::run_lens_extract(fp, sched, tok, meta, vocab_size, n_ctx, d.document,
                                       concepts, opts, qinf::LensConstants{});
        } catch (const qinf::LensUnparseableError& e) {
            std::printf("\n[%s%s] PASS1 422 UNPARSEABLE — doc skipped\n  %.140s\n",
                        d.tag.c_str(), d.de ? " DE" : "", e.raw.c_str());
            continue;
        }

        DocOut out; out.tag = d.tag; out.de = d.de; out.document = d.document;
        for (auto& k : keys) out.per_key[k];  // every hinted key gets an entry, even []
        for (const auto& f : r.fields) {
            auto it = out.per_key.find(f.key);
            if (it == out.per_key.end()) continue;
            if (!it->second.p1_present && f.present) {  // first occurrence wins
                it->second.p1_value    = f.value;
                it->second.p1_grounded = f.grounded;
                it->second.p1_present  = true;
            }
        }

        // ── Pass 2 — cold, separate inference, taps DISARMED ─────────────────
        std::string task = CAND_PASS2_TASK_PREFIX;
        for (size_t i = 0; i < keys.size(); ++i) task += (i ? ", " : "") + keys[i];
        std::string prompt = qdocs_chat_prompt(d.document, task);
        auto p2_t0 = std::chrono::steady_clock::now();
        FreeRun P2 = run_freegen(fp, sched, tok, meta, prompt, "", /*tap_layers=*/{},
                                 700, /*capture_conf=*/false, /*close_char=*/'\x01');
        double p2_latency_s = std::chrono::duration<double>(
            std::chrono::steady_clock::now() - p2_t0).count();
        if (std::getenv("CAND_DEBUG"))
            std::printf("\n[%s%s] PASS2 raw (%zu gen tok):\n%s\n", d.tag.c_str(),
                        d.de ? " DE" : "", P2.gen_tokens.size(), P2.gen_text.c_str());

        // FAIL LOUD on a producer failure. An empty parse over a NON-empty
        // generation means the finder produced output we could not read — which
        // is a different fact from "the document offers nothing", and must never
        // render as an empty candidate set. This is the gap the plan's own states
        // table does not yet cover (docs/plan-candidate-set.md §"The states it
        // must express"): it separates absence from recall failure, but not
        // either of those from PRODUCER failure.
        // THE SHIPPED PRODUCER, not a lookalike. This gate previously ran the
        // harness's own parse-and-accumulate (cand_parse_pass2 + a raw-string
        // dedup + a document.find() sort), which is NOT what the server does:
        // the server resolves each quoted span to a byte range, tolerating the
        // hard-wrap newline and a trailing sentence period, emits the DOCUMENT's
        // bytes, and dedups by RANGE. Measuring the copy is exactly the failure
        // tests/CMakeLists.txt warns about for QDOCS_S1 ("the gate would be
        // worthless against a lookalike") — a gate that cannot see a producer
        // change cannot gate it. Calling the shipped function makes CAND
        // measure what ships, and makes the byte-exactness line below a real
        // check rather than a tautology.
        qinf::LensReport prep;
        qinf::lens_apply_pass2_candidates(d.document, P2.gen_text, keys, prep);
        if (prep.candidates_producer_failed) {
            n_unparseable++;
            std::printf("  !! [%s] PASS2 UNPARSEABLE — %zu gen tokens produced 0 readable "
                        "candidate lines. This is a PRODUCER failure, not an empty document.\n",
                        d.tag.c_str(), P2.gen_tokens.size());
        }
        // Already deduped by byte range and sorted byte_lo-ascending by the
        // shipped function; no re-sort here, and no string dedup — two spans
        // with identical text at different offsets are two candidates on the
        // wire, so they must be two here.
        for (auto& kv : prep.key_candidates) {
            auto& cs = out.per_key[kv.first].cands;
            for (const qinf::LensCandidate& c : kv.second) cs.push_back(c.value);
        }

        // Uncontested keys: the corpus labels EXACTLY ONE true value for this
        // doc's concept. Concepts with 0 or ≥2 labels are excluded from Gate 2.
        std::map<std::string, int> truth_count;
        for (auto& f : d.fields) truth_count[f.concept]++;
        for (auto& kv : truth_count) if (kv.second == 1) out.uncontested.insert(kv.first);

        out.p2_latency_s = p2_latency_s;
        docs_out.push_back(std::move(out));
    }

    // ── CAND_PRED — dump pass-2's own candidate spans as a span-tagger-probe
    // prediction file (docs/note-span-tagger-probe.md shape), so the shipped
    // finder can be scored by the SAME unmodified scorer used for GLiNER/QA.
    // Pass 2 emits no confidence, so every span gets score=1.0 (only the
    // th=0.1 row of the scorer's threshold sweep is meaningful for this file).
    // Text is the document-order span "text" already resolved by the shipped
    // qinf::lens_apply_pass2_candidates() against the ORIGINAL document bytes
    // (d.document, same corpus text run_cand_probe always used) — no new
    // extraction or matching logic here, just a serializer over docs_out.
    if (const char* pred_path = std::getenv("CAND_PRED")) {
        std::ofstream pf(pred_path);
        if (!pf) throw std::runtime_error("CAND_PRED: cannot open " + std::string(pred_path));
        pf << "{\n  \"model_id\": \"pass2-cand-finder\",\n  \"per_doc\": {\n";
        for (size_t i = 0; i < docs_out.size(); ++i) {
            const DocOut& d = docs_out[i];
            pf << "    \"" << jesc(d.tag) << "\": {\n"
               << "      \"de\": " << (d.de ? "true" : "false") << ",\n"
               << "      \"latency_s\": " << d.p2_latency_s << ",\n"
               << "      \"spans\": [\n";
            bool first = true;
            for (auto& kv : d.per_key) {
                for (auto& c : kv.second.cands) {
                    if (!first) pf << ",\n";
                    first = false;
                    pf << "        {\"concept\": \"" << jesc(kv.first) << "\", \"text\": \""
                       << jesc(c) << "\", \"score\": 1.0}";
                }
            }
            pf << (first ? "" : "\n") << "      ]\n"
               << "    }" << (i + 1 < docs_out.size() ? "," : "") << "\n";
        }
        pf << "  }\n}\n";
        pf.close();
        std::printf("\nCAND_PRED: wrote %zu docs to %s\n", docs_out.size(), pred_path);
    }

    // ── 1. THE KILL GATE — median candidate-set size on uncontested keys ─────
    std::vector<int> sizes; std::map<int, int> hist;
    for (auto& d : docs_out)
        for (auto& kv : d.per_key)
            if (d.uncontested.count(kv.first)) {
                int n = (int)kv.second.cands.size();
                sizes.push_back(n);
                hist[n >= 3 ? 3 : n]++;
            }
    std::sort(sizes.begin(), sizes.end());
    double median = 0;
    if (!sizes.empty()) {
        size_t mid = sizes.size() / 2;
        median = (sizes.size() % 2) ? sizes[mid] : (sizes[mid - 1] + sizes[mid]) / 2.0;
    }
    std::printf("\n================ 1. GATE 2 — median candidate-set size, UNCONTESTED keys ================\n");
    std::printf("keys scored: %zu\n", sizes.size());
    std::printf("producer failures (pass-2 output unreadable): %d  "
                "[these are NOT empty documents — see the !! lines above]\n", n_unparseable);
    std::printf("median: %.1f   (BAR: exactly 1 — above 1 means type-matches, not answers; KILLS the feature)\n", median);
    std::printf("distribution: 0=%d  1=%d  2=%d  3+=%d\n", hist[0], hist[1], hist[2], hist[3]);
    std::printf("VERDICT: %s\n", (!sizes.empty() && median == 1.0) ? "PASS" : "KILL");

    // ── 2. Byte-exactness ─────────────────────────────────────────────────────
    int be_ok = 0, be_tot = 0;
    for (auto& d : docs_out)
        for (auto& kv : d.per_key)
            for (auto& c : kv.second.cands) {
                be_tot++;
                if (d.document.find(c) != std::string::npos) be_ok++;
            }
    std::printf("\n================ 2. byte-exactness ================\n");
    std::printf("%d/%d candidates are a byte-exact slice of their document (%.0f%%)\n",
                be_ok, be_tot, be_tot ? 100.0 * be_ok / be_tot : 0.0);

    // ── 3. returned_as coverage (recall proxy) ────────────────────────────────
    int rc_ok = 0, rc_tot = 0;
    for (auto& d : docs_out)
        for (auto& kv : d.per_key) {
            const CandSet& cs = kv.second;
            if (!cs.p1_grounded || cs.p1_value.empty()) continue;
            rc_tot++;
            if (std::find(cs.cands.begin(), cs.cands.end(), cs.p1_value) != cs.cands.end())
                rc_ok++;
        }
    std::printf("\n================ 3. returned_as coverage ================\n");
    std::printf("%d/%d pass-1 grounded values also appear among pass-2 candidates (%.0f%%)\n",
                rc_ok, rc_tot, rc_tot ? 100.0 * rc_ok / rc_tot : 0.0);

    // ── 4. Every candidate set, for eyeball scoring (Gate 1 needs a human) ────
    std::printf("\n================ 4. candidate sets (document order) ================\n");
    for (auto& d : docs_out) {
        std::printf("\n[%s%s]\n", d.tag.c_str(), d.de ? " DE" : "");
        for (auto& kv : d.per_key) {
            bool unc = d.uncontested.count(kv.first) != 0;
            std::printf("  %-16s p1=\"%s\"%s\n", kv.first.c_str(), kv.second.p1_value.c_str(),
                        unc ? "  [UNCONTESTED]" : "");
            if (kv.second.cands.empty()) { std::printf("      (no candidates)\n"); continue; }
            for (auto& c : kv.second.cands) std::printf("      - \"%s\"\n", c.c_str());
        }
    }

    return (!sizes.empty() && median == 1.0) ? 0 : 1;
}

// ═════════════════════════════════════════════════════════════════════════
// WARM1/WARM2 — docs/plan-lens-warm-document.md probes. Harness-only, no
// server/engine changes: both reuse qdocs_messy_corpus() and the existing
// pass-1 (QKEY-style citation scoring, qdocs_eval_field) / pass-2 (CAND's
// lens_apply_pass2_candidates) machinery. Byte-inert when WARM1/WARM2 unset.
// ═════════════════════════════════════════════════════════════════════════

enum class SplitMode { ONESHOT, SPLIT_COLD, SPLIT_WARM };

static double ms_since(std::chrono::steady_clock::time_point t0) {
    return std::chrono::duration<double, std::milli>(
               std::chrono::steady_clock::now() - t0).count();
}

// Same free-greedy tapped generation as run_freegen (identical decode loop),
// generalized with a document/instruction split mode. `document` + `task` are
// rendered through the production chat template exactly as qdocs_chat_prompt
// already does for QKEY/CAND/Leg C. The split point is the document's own
// byte span within that ONE rendered+tokenized text (the same boundary
// run_lens_tapped_decode computes as doc_hi), not a second, independently
// tokenized concatenation — this keeps the split token-boundary-safe.
static FreeRun run_freegen_split(ForwardPassBase* fp, ggml_backend_sched_t sched,
                                 Tokenizer* tok, const ModelMetadata& meta,
                                 const std::string& document, const std::string& task,
                                 const std::vector<int>& tap_layers, int max_new,
                                 SplitMode mode, bool capture_conf = false,
                                 char close_char = '}',
                                 double* prefill_ms = nullptr, double* decode_ms = nullptr) {
    FreeRun R;
    std::string prompt_text = qdocs_chat_prompt(document, task);
    R.body_text = prompt_text;
    R.n_head = (int)meta.attention_head_count;
    R.prompt_tokens = encode_prompt(tok, prompt_text);
    if (tok->decode(R.prompt_tokens) != prompt_text)
        throw std::runtime_error("run_freegen_split: prompt roundtrip mismatch");
    R.P = (int)R.prompt_tokens.size();

    size_t doc_pos = prompt_text.find(document);
    if (doc_pos == std::string::npos)
        throw std::runtime_error("run_freegen_split: document expected verbatim in "
                                 "rendered prompt, actual not found");
    size_t doc_end = doc_pos + document.size();
    std::vector<size_t> cum = cum_bytes(tok, R.prompt_tokens);
    int split_idx = R.P;
    for (int k = 0; k < R.P; ++k) if (cum[k] >= doc_end) { split_idx = k; break; }
    R.instr_tok = split_idx;   // reused field: document/suffix boundary

    auto tpre0 = std::chrono::steady_clock::now();
    std::vector<float> logits;
    if (mode == SplitMode::ONESHOT) {
        fp->clear_slot(0); fp->set_cache_pos(0, 0);
        logits = fp->run_prefill(R.prompt_tokens, 0, 0, sched);
    } else {
        std::vector<int32_t> chunk1(R.prompt_tokens.begin(), R.prompt_tokens.begin() + split_idx);
        std::vector<int32_t> chunk2(R.prompt_tokens.begin() + split_idx, R.prompt_tokens.end());
        if (mode == SplitMode::SPLIT_COLD) {
            fp->clear_slot(0); fp->set_cache_pos(0, 0);
            fp->run_prefill(chunk1, 0, 0, sched);
        }
        // SPLIT_WARM: the caller has already primed slot 0 with this exact
        // chunk 1 (qdocs_prime_chunk1_chat, same document+task ⇒ identical
        // tokenization) — resume from its cache position instead of redoing it.
        int pos2 = (int)fp->get_cache_pos(0);
        logits = fp->run_prefill(chunk2, pos2, 0, sched);
    }
    if (prefill_ms) *prefill_ms = ms_since(tpre0);

    int32_t next = 0;
    for (int j = 1; j < (int)logits.size(); ++j) if (logits[j] > logits[next]) next = j;

    auto tdec0 = std::chrono::steady_clock::now();
    const int32_t eos = tok->get_eos_token_id();
    for (int t = 0; t < max_new; ++t) {
        if (next == eos) break;
        int32_t cur = next;
        R.gen_tokens.push_back(cur);
        std::string ct = tok->decode(cur);
        bool closed = ct.find(close_char) != std::string::npos;

        std::vector<int32_t>  tks = {cur};
        std::vector<uint32_t> slots = {0};
        std::vector<int32_t>  positions = {(int)fp->get_cache_pos(0)};
        ggml_cgraph* gf = fp->build_decoding_graph(tks, slots, positions);

        std::vector<ggml_tensor*> taps;
        for (int il : tap_layers) {
            std::string nm = "kq_soft." + std::to_string(il);
            ggml_tensor* ts = ggml_graph_get_tensor(gf, nm.c_str());
            if (!ts) throw std::runtime_error("freegen_split tap missing: " + nm);
            ggml_set_output(ts); ggml_build_forward_expand(gf, ts); taps.push_back(ts);
        }
        ggml_backend_sched_reset(sched);
        ggml_backend_sched_alloc_graph(sched, gf);
        fp->set_decode_inputs(gf, tks, slots, positions);
        ggml_backend_sched_graph_compute(sched, gf);

        std::vector<std::vector<float>> layer_rows; int n_kv = 0;
        for (ggml_tensor* ts : taps) {
            n_kv = (int)ts->ne[0]; int nh = (int)ts->ne[2];
            std::vector<float> buf((size_t)n_kv * nh);
            ggml_backend_tensor_get(ts, buf.data(), 0, ggml_nbytes(ts));
            layer_rows.push_back(std::move(buf));
        }
        R.rows.push_back(std::move(layer_rows));
        R.n_kv_at_step.push_back(n_kv);

        std::vector<float> lg = fp->get_output_logits(gf);
        if (capture_conf) R.conf.push_back(conf_from_logits(lg));
        next = 0; for (int j = 1; j < (int)lg.size(); ++j) if (lg[j] > lg[next]) next = j;
        fp->advance_cache(1, 0);
        if (closed) break;
    }
    if (decode_ms) *decode_ms = ms_since(tdec0);
    R.gen_text = tok->decode(R.gen_tokens);
    return R;
}

// Prefill ONLY the document-boundary prefix (chunk 1 = chat header + document)
// on a freshly cleared slot 0, for reuse by a subsequent run_freegen_split
// SPLIT_WARM call over the SAME (document, task). `task` only determines
// where the split point falls when re-tokenized — the resulting chunk-1
// TOKENS are identical for any task (chat header + document precede it, and a
// causal model's earlier K/V never depend on later tokens), so priming under
// one task's rendering and resuming decode under a DIFFERENT task (WARM2's
// pass-2 task vs pass-1's) is safe as long as `document` is unchanged.
// `arm_taps` mirrors run_lens_tapped_decode's real pass-1 behaviour, which
// arms attention taps BEFORE its prefill (forcing the non-flash path) — WARM2
// needs this to faithfully reuse a prefix computed the way real pass 1
// computes it; WARM1 does not (all three of its arms stay on one consistent,
// disarmed policy, isolating the chunking question from the arming question).
static void qdocs_prime_chunk1_chat(ForwardPassBase* fp, ggml_backend_sched_t sched,
                                    Tokenizer* tok, const std::string& document,
                                    const std::string& task, bool arm_taps,
                                    int citation_layer, int coverage_layer,
                                    double* prefill_ms = nullptr) {
    std::string prompt_text = qdocs_chat_prompt(document, task);
    std::vector<int32_t> toks = encode_prompt(tok, prompt_text);
    if (tok->decode(toks) != prompt_text)
        throw std::runtime_error("qdocs_prime_chunk1_chat: prompt roundtrip mismatch");
    size_t doc_pos = prompt_text.find(document);
    if (doc_pos == std::string::npos)
        throw std::runtime_error("qdocs_prime_chunk1_chat: document expected verbatim "
                                 "in rendered prompt, actual not found");
    size_t doc_end = doc_pos + document.size();
    std::vector<size_t> cum = cum_bytes(tok, toks);
    int split_idx = (int)toks.size();
    for (int k = 0; k < (int)toks.size(); ++k) if (cum[k] >= doc_end) { split_idx = k; break; }
    std::vector<int32_t> chunk1(toks.begin(), toks.begin() + split_idx);

    if (arm_taps) fp->set_attention_taps({citation_layer, coverage_layer});
    auto t0 = std::chrono::steady_clock::now();
    fp->clear_slot(0); fp->set_cache_pos(0, 0);
    fp->run_prefill(chunk1, 0, 0, sched);
    if (prefill_ms) *prefill_ms = ms_since(t0);
    if (arm_taps) fp->set_attention_taps({});  // disarm before the caller's own suffix prefill
}

// ── WARMPERF — does the warm prefix actually SAVE anything? ─────────────────
// The correctness probes (WARM1/WARM2) passed; the speed question was left
// unanswered because WARM2's timers disagreed with each other (a "suffix-only"
// prefill timed SLOWER than the full-document prefill it replaces) and because
// the messy corpus is short business email, which is the wrong instrument: a
// warm prefix removes document-proportional work, so the saving only appears on
// documents long enough for prefill to matter.
//
// This arm fixes both. Identical timer scope for every arm (strictly around
// run_prefill, nothing else), a warmup iteration before any measurement so
// graph build and kernel compile are not attributed to the first sample,
// medians rather than means, and synthetic documents at controlled lengths.
//
// Measures PASS 1 ONLY — the pass that runs on every request (candidates are
// opt-in) and the one a key-editing loop actually repeats.
static int run_warmperf_probe(ForwardPassBase* fp, ggml_backend_sched_t sched,
                              Tokenizer* tok, uint32_t n_ctx) {
    std::printf("\n+==============================================================+\n");
    std::printf("| WARMPERF - warm-prefix prefill saving, pass 1, by doc length  |\n");
    std::printf("+==============================================================+\n");

    auto corpus = qdocs_messy_corpus();
    const std::vector<std::string> keys = {"customer", "quantity", "unit_price",
                                           "total", "order_date", "delivery_date"};
    const std::string task = qinf::lens_build_instruction(keys);

    auto make_doc = [&](int target_tok) {
        std::string doc;
        for (size_t i = 0; i < 400; ++i) {
            doc += corpus[i % corpus.size()].document;
            doc += "\n\n---\n\n";
            if ((int)tok->encode(doc).size() >= target_tok) break;
        }
        return doc;
    };

    const int REPS = 5;
    std::printf("\n%-8s %-8s | %-24s | %-24s | %s\n", "target", "Ptok",
                "COLD full prefill", "WARM suffix prefill", "saving");
    std::printf("%s\n", std::string(96, '-').c_str());

    for (int target : {1000, 2000, 4000, 8000}) {
        const std::string document = make_doc(target);
        const std::string prompt   = qdocs_chat_prompt(document, task);
        std::vector<int32_t> toks  = tok->encode(prompt);
        if ((uint32_t)toks.size() + 8 >= n_ctx) {
            std::printf("%-8d  (skipped - %zu tokens exceeds ctx %u)\n",
                        target, toks.size(), n_ctx);
            continue;
        }
        const size_t doc_end_byte = prompt.find(document) + document.size();
        const std::vector<size_t> cum = cum_bytes(tok, toks);
        size_t split = toks.size();
        for (size_t i = 0; i < toks.size(); ++i)
            if (cum[i + 1] >= doc_end_byte) { split = i + 1; break; }
        if (split >= toks.size()) { std::printf("%-8d  (split not found)\n", target); continue; }
        const std::vector<int32_t> pre(toks.begin(), toks.begin() + (long)split);
        const std::vector<int32_t> suf(toks.begin() + (long)split, toks.end());

        auto median = [](std::vector<double> v) {
            std::sort(v.begin(), v.end());
            return v.empty() ? 0.0 : v[v.size() / 2];
        };
        auto ms_since = [](std::chrono::steady_clock::time_point t0) {
            return std::chrono::duration<double, std::milli>(
                       std::chrono::steady_clock::now() - t0).count();
        };

        // COLD - today's path: clear, rewind, prefill everything.
        std::vector<double> cold;
        for (int r = 0; r <= REPS; ++r) {
            fp->clear_slot(0);
            fp->set_cache_pos(0, 0);
            auto t0 = std::chrono::steady_clock::now();
            fp->run_prefill(toks, 0, 0, sched);
            const double ms = ms_since(t0);
            if (r) cold.push_back(ms);          // r == 0 is the untimed warmup
        }

        // WARM - prime the document ONCE, untimed (a real restore is a copy,
        // not a recompute), then pay only the instruction on every edit.
        fp->clear_slot(0);
        fp->set_cache_pos(0, 0);
        fp->run_prefill(pre, 0, 0, sched);
        std::vector<double> warm;
        for (int r = 0; r <= REPS; ++r) {
            // Rewind to the document boundary: the suffix is rewritten at the
            // same positions every time, exactly as a re-extraction would.
            fp->set_cache_pos((uint32_t)split, 0);
            auto t0 = std::chrono::steady_clock::now();
            fp->run_prefill(suf, (uint32_t)split, 0, sched);
            const double ms = ms_since(t0);
            if (r) warm.push_back(ms);
        }

        const double c = median(cold), w = median(warm);
        std::printf("%-8d %-8zu | %10.1f ms (%5zu tok) | %10.1f ms (%5zu tok) | %5.1f%%  (%.1fx)\n",
                    target, split, c, toks.size(), w, suf.size(),
                    c > 0 ? 100.0 * (c - w) / c : 0.0, w > 0 ? c / w : 0.0);
    }

    std::printf("\nPrefill only. Decode is unchanged by warming and costs the same in both\n"
                "arms, so the end-to-end saving on one edit is this saving over\n"
                "(prefill + decode) at the caller's own generation length.\n");
    fp->clear_slot(0);
    fp->set_cache_pos(0, 0);
    return 0;
}

// ── WARM1 — pass-1 split-prefill probe (plan-lens-warm-document.md §4) ──────
// Three arms over qdocs_messy_corpus, reusing QKEY's exact task/instruction
// and qdocs_eval_field citation-scoring machinery — QKEY's Arm K IS the
// "92%/99% under the QKEY control arm" baseline §4's gate 2 is measured
// against, so Arm O below reproduces that same measurement rather than
// re-approximating it.
//   Arm O — one-shot prefill (today's path, unchanged).
//   Arm S — split prefill (P as chunk 1, suffix as chunk 2), cold: chunk 1 is
//           recomputed fresh, in-line, via clear_slot+run_prefill.
//   Arm W — split prefill, chunk 1 "restored": primed in its OWN call
//           (qdocs_prime_chunk1_chat) immediately before chunk 2 is
//           prefilled, rather than inline within one uninterrupted call like
//           Arm S. Per plan §2.1 the two are claimed to be the identical
//           computation on identical tokens; this measures whether that
//           claim holds byte-for-byte on this engine — not a real
//           snapshot/PrefixLibrary restore (recompute stands in for it, per
//           the task brief: "simulate however is simplest in-process").
static int run_warm1_probe(ForwardPassBase* fp, ggml_backend_sched_t sched,
                           Tokenizer* tok, const ModelMetadata& meta, uint32_t n_ctx) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ WARM1 — pass-1 split-prefill probe (plan-lens-warm-document §4)║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");

    const qinf::LensCalibration* calib =
        qinf::lens_calibration_for(meta.architecture, meta.block_count,
                                   probe_lens_file_type(meta));
    if (!calib) {
        std::fprintf(stderr, "WARM1: expected a calibrated lens entry for arch '%s' "
                             "block_count %u, actual none — %s\n",
                    meta.architecture.c_str(), meta.block_count,
                    qinf::lens_calibration_refusal(meta.architecture, meta.block_count,
                                                   probe_lens_file_type(meta)).c_str());
        return 1;
    }
    const int layer = calib->constants.citation_layer;
    const int head  = calib->constants.citation_head;
    int slot = -1;
    for (size_t i = 0; i < g_attn_layers->size(); ++i)
        if ((*g_attn_layers)[i] == layer) { slot = (int)i; break; }
    if (slot < 0) {
        std::fprintf(stderr, "WARM1: expected citation_layer %d among %zu discovered "
                             "attention layers, actual not found\n", layer, g_attn_layers->size());
        return 1;
    }
    L3H13_SLOT = slot; FROZEN_SLOT = slot; FROZEN_HEAD = head;
    std::printf("calibration: %s — citation L%dH%d (tap slot %d)   ctx=%u\n",
                calib->model, layer, head, slot, n_ctx);

    const int TOL = 2;
    const int MAX_NEW = 400;   // same budget as QKEY/CAND pass 1
    auto corpus = qdocs_messy_corpus();
    std::vector<int> taps(g_attn_layers->begin(), g_attn_layers->end());

    auto build_task = [](const std::vector<std::string>& keys) {
        std::string t = "\n\nExtract the following from the email above into a flat JSON "
            "object of \"key\": \"value\" pairs, using EXACTLY these keys, verbatim. "
            "Copy each value verbatim from the email. Output ONLY the JSON object, "
            "nothing else. Keys: ";
        for (size_t i = 0; i < keys.size(); ++i) t += (i ? ", " : "") + keys[i];
        return t;
    };

    struct Acc { int cite_n = 0, t1 = 0, t3 = 0, labeled = 0, extractive = 0; };
    Acc armO, armS, armW;
    int docs_n = 0, sw_match = 0, so_match = 0;
    std::vector<std::string> sw_diff, so_diff;

    for (const QMessy& d : corpus) {
        std::vector<std::string> keys;
        for (auto& f : d.fields) keys.push_back(f.concept);
        std::string task = build_task(keys);

        FreeRun RO = run_freegen_split(fp, sched, tok, meta, d.document, task, taps,
                                       MAX_NEW, SplitMode::ONESHOT);
        FreeRun RS = run_freegen_split(fp, sched, tok, meta, d.document, task, taps,
                                       MAX_NEW, SplitMode::SPLIT_COLD);
        qdocs_prime_chunk1_chat(fp, sched, tok, d.document, task, /*arm_taps=*/false, layer, head);
        FreeRun RW = run_freegen_split(fp, sched, tok, meta, d.document, task, taps,
                                       MAX_NEW, SplitMode::SPLIT_WARM);

        docs_n++;
        bool sw = (RS.gen_text == RW.gen_text);
        bool so = (RS.gen_text == RO.gen_text);
        if (sw) sw_match++; else sw_diff.push_back(d.tag + (d.de ? " DE" : ""));
        if (so) so_match++; else so_diff.push_back(d.tag + (d.de ? " DE" : ""));

        auto score = [&](FreeRun& R, Acc& A) {
            int doc_lo, doc_hi;
            if (!qdocs_span_in_prompt(tok, R, d.document, doc_lo, doc_hi)) { doc_lo = 0; doc_hi = R.P - 1; }
            for (auto& f : d.fields) {
                A.labeled++;
                QFieldEval e = qdocs_eval_field(tok, R, f.value, doc_lo, doc_hi, *g_attn_layers, TOL);
                if (e.found_verbatim) { A.extractive++; A.cite_n += e.cite_n; A.t1 += e.cite_t1; A.t3 += e.cite_t3; }
            }
        };
        score(RO, armO); score(RS, armS); score(RW, armW);
    }

    auto pct = [](int a, int b) { return b ? 100.0 * a / b : 0.0; };

    std::printf("\n================ 1. WARM == COLD — Arm W vs Arm S (bar: exact) ================\n");
    std::printf("exact-match completions: %d/%d (%.0f%%)\n", sw_match, docs_n, pct(sw_match, docs_n));
    if (!sw_diff.empty()) { std::printf("  DIFFERS on:"); for (auto& t : sw_diff) std::printf(" %s", t.c_str()); std::printf("\n"); }
    std::printf("VERDICT: %s\n", sw_match == docs_n
                ? "PASS — warm == cold by construction, as designed"
                : "FAIL — warm != cold: the split-prefill design does NOT hold by "
                  "construction on this engine; this is loud and should be treated as such");

    std::printf("\n================ 2. TOKEN STABILITY — Arm S vs Arm O (bar: exact) ================\n");
    std::printf("exact-match completions: %d/%d (%.0f%%)\n", so_match, docs_n, pct(so_match, docs_n));
    if (!so_diff.empty()) { std::printf("  DIFFERS on:"); for (auto& t : so_diff) std::printf(" %s", t.c_str()); std::printf("\n"); }
    std::printf("VERDICT: %s\n", so_match == docs_n
                ? "PASS — split path token-identical to one-shot"
                : "NOTE — split path diverges from one-shot at the token level; see the "
                  "mass-drift-ceiling check below (chunked-vs-one-shot prefill is a known "
                  "non-bit-identical fork on Metal, per the mm-vs-mv precedent)");

    std::printf("\n================ 3. CITATION top-1/top-3 — all three arms ================\n");
    auto report = [&](const char* label, Acc& A) {
        double t1 = pct(A.t1, A.cite_n), t3 = pct(A.t3, A.cite_n);
        std::printf("  %-6s top1 %d/%d (%.0f%%)  top3 %d/%d (%.0f%%)  [scoreable/verbatim: %d/%d]\n",
                    label, A.t1, A.cite_n, t1, A.t3, A.cite_n, t3, A.extractive, A.labeled);
        return std::make_pair(t1, t3);
    };
    std::pair<double,double> po = report("Arm O", armO);
    std::pair<double,double> ps = report("Arm S", armS);
    std::pair<double,double> pw = report("Arm W", armW);
    double o1 = po.first, o3 = po.second, s1 = ps.first, s3 = ps.second, w1 = pw.first, w3 = pw.second;

    bool repro = std::fabs(o1 - 92.0) <= 2.0 && std::fabs(o3 - 99.0) <= 2.0;
    std::printf("\nArm O vs published QKEY control-arm baseline (92%%/99%%): top1 delta %+.1f  "
                "top3 delta %+.1f  [%s]\n", o1 - 92.0, o3 - 99.0,
                repro ? "reproduces" : "DOES NOT reproduce — treat other numbers with suspicion");
    bool no_regress_S = s1 >= o1 - 2.0 && s3 >= o3 - 2.0;
    bool no_regress_W = w1 >= o1 - 2.0 && w3 >= o3 - 2.0;
    std::printf("Arm S vs Arm O: top1 %+.1f  top3 %+.1f  [%s]\n", s1 - o1, s3 - o3,
                no_regress_S ? "no regression" : "REGRESSION");
    std::printf("Arm W vs Arm O: top1 %+.1f  top3 %+.1f  [%s]\n", w1 - o1, w3 - o3,
                no_regress_W ? "no regression" : "REGRESSION");

    std::printf("\n================ SUMMARY ================\n");
    std::printf("gate1 warm==cold (Arm W vs Arm S exact):            %s\n", sw_match == docs_n ? "PASS" : "FAIL");
    std::printf("gate2 token stability (Arm S vs Arm O exact):       %s\n", so_match == docs_n ? "PASS" : "FAIL");
    std::printf("gate3 mass-drift ceiling (S/W top1/top3 >= O-2pt):  %s\n",
                (no_regress_S && no_regress_W) ? "PASS" : "FAIL");

    return (sw_match == docs_n && no_regress_S && no_regress_W) ? 0 : 1;
}

// ── WARM2 — pass-2 restore probe (plan-lens-warm-document.md §3.1) ──────────
// Extends CAND's own pass 2 (unchanged corpus/task/parser: CAND_PASS2_TASK_PREFIX,
// lens_apply_pass2_candidates). Two arms:
//   Arm C — pass 2 as CAND runs it today: cold, full P+suffix prefill, taps
//           disarmed throughout.
//   Arm W — pass 2 resuming from a simulated pass-1 document prefix: chunk 1
//           (chat header + document) is primed on a fresh slot with attention
//           taps ARMED (matching run_lens_tapped_decode's real pass-1 numeric
//           path — arming forces the non-flash path the plan's open question
//           is about), then disarmed, and only the pass-2 suffix is prefilled
//           and decoded on top — exactly as a real warm hit would run.
static int run_warm2_probe(ForwardPassBase* fp, ggml_backend_sched_t sched,
                           Tokenizer* tok, const ModelMetadata& meta, uint32_t n_ctx) {
    std::printf("\n╔══════════════════════════════════════════════════════════════╗\n");
    std::printf("║ WARM2 — pass-2 restore probe (plan-lens-warm-document §3.1)    ║\n");
    std::printf("╚══════════════════════════════════════════════════════════════╝\n");

    const qinf::LensCalibration* calib =
        qinf::lens_calibration_for(meta.architecture, meta.block_count,
                                   probe_lens_file_type(meta));
    if (!calib) {
        std::fprintf(stderr, "WARM2: expected a calibrated lens entry for arch '%s' "
                             "block_count %u, actual none — %s\n",
                    meta.architecture.c_str(), meta.block_count,
                    qinf::lens_calibration_refusal(meta.architecture, meta.block_count,
                                                   probe_lens_file_type(meta)).c_str());
        return 1;
    }
    const int citation_layer = calib->constants.citation_layer;
    const int coverage_layer = calib->constants.coverage_layer;
    std::printf("calibration: %s — arming {L%d citation, L%d coverage} for the simulated "
                "pass-1 prime   ctx=%u\n", calib->model, citation_layer, coverage_layer, n_ctx);

    const std::vector<std::string> ABSENT = {"payment_terms", "warranty_period"};
    auto corpus = qdocs_messy_corpus();

    struct DocCand {
        std::string tag, document; bool de;
        qinf::LensReport c, w;
        std::set<std::string> uncontested;
        double c_prefill_ms = 0, c_decode_ms = 0;
        double w_prime_ms = 0, w_prefill_ms = 0, w_decode_ms = 0;
    };
    std::vector<DocCand> out;
    int n_unparseable_c = 0, n_unparseable_w = 0;

    for (const QMessy& d : corpus) {
        std::vector<std::string> keys;
        for (auto& f : d.fields) keys.push_back(f.concept);
        for (auto& a : ABSENT) keys.push_back(a);
        std::string task = CAND_PASS2_TASK_PREFIX;
        for (size_t i = 0; i < keys.size(); ++i) task += (i ? ", " : "") + keys[i];

        DocCand dc; dc.tag = d.tag; dc.document = d.document; dc.de = d.de;

        // ── Arm C — cold, exactly as CAND runs pass 2 today ──────────────────
        fp->set_attention_taps({});  // hygiene: guarantee disarmed, matching "today"
        FreeRun PC = run_freegen_split(fp, sched, tok, meta, d.document, task, /*tap_layers=*/{},
                                       700, SplitMode::ONESHOT, false, '\x01',
                                       &dc.c_prefill_ms, &dc.c_decode_ms);
        qinf::lens_apply_pass2_candidates(d.document, PC.gen_text, keys, dc.c);
        if (dc.c.candidates_producer_failed) n_unparseable_c++;

        // ── Arm W — resume from a simulated warm pass-1 document prefix ──────
        qdocs_prime_chunk1_chat(fp, sched, tok, d.document, task, /*arm_taps=*/true,
                                citation_layer, coverage_layer, &dc.w_prime_ms);
        FreeRun PW = run_freegen_split(fp, sched, tok, meta, d.document, task, /*tap_layers=*/{},
                                       700, SplitMode::SPLIT_WARM, false, '\x01',
                                       &dc.w_prefill_ms, &dc.w_decode_ms);
        qinf::lens_apply_pass2_candidates(d.document, PW.gen_text, keys, dc.w);
        if (dc.w.candidates_producer_failed) n_unparseable_w++;

        std::map<std::string, int> truth_count;
        for (auto& f : d.fields) truth_count[f.concept]++;
        for (auto& kv : truth_count) if (kv.second == 1) dc.uncontested.insert(kv.first);

        out.push_back(std::move(dc));
    }

    // ── 1. Candidate-set identity, Arm W vs Arm C (diagnostic, not a bar) ────
    int keys_total = 0, keys_match = 0;
    std::vector<std::string> differ_docs;
    for (auto& dc : out) {
        bool doc_differs = false;
        std::set<std::string> allkeys;
        for (auto& kv : dc.c.key_candidates) allkeys.insert(kv.first);
        for (auto& kv : dc.w.key_candidates) allkeys.insert(kv.first);
        for (auto& k : allkeys) {
            keys_total++;
            auto itc = dc.c.key_candidates.find(k);
            auto itw = dc.w.key_candidates.find(k);
            std::vector<std::string> vc, vw;
            if (itc != dc.c.key_candidates.end()) for (auto& cc : itc->second) vc.push_back(cc.value);
            if (itw != dc.w.key_candidates.end()) for (auto& cc : itw->second) vw.push_back(cc.value);
            if (vc == vw) keys_match++; else doc_differs = true;
        }
        if (doc_differs) differ_docs.push_back(dc.tag + (dc.de ? " DE" : ""));
    }
    std::printf("\n================ 1. CANDIDATE-SET IDENTITY — Arm W vs Arm C (diagnostic) ================\n");
    std::printf("per-key exact match (same spans, same order): %d/%d (%.0f%%)\n",
                keys_match, keys_total, keys_total ? 100.0 * keys_match / keys_total : 0.0);
    if (!differ_docs.empty()) {
        std::printf("documents with >=1 differing key:"); for (auto& t : differ_docs) std::printf(" %s", t.c_str());
        std::printf("\n");
    }

    // ── 2. Gate 2 — median candidate-set size on uncontested keys, per arm ────
    auto gate2 = [&](bool warm) {
        std::vector<int> sizes; std::map<int, int> hist;
        for (auto& dc : out) {
            const qinf::LensReport& r = warm ? dc.w : dc.c;
            for (auto& k : dc.uncontested) {
                auto it = r.key_candidates.find(k);
                int n = (it != r.key_candidates.end()) ? (int)it->second.size() : 0;
                sizes.push_back(n); hist[n >= 3 ? 3 : n]++;
            }
        }
        std::sort(sizes.begin(), sizes.end());
        double median = 0;
        if (!sizes.empty()) {
            size_t mid = sizes.size() / 2;
            median = (sizes.size() % 2) ? sizes[mid] : (sizes[mid - 1] + sizes[mid]) / 2.0;
        }
        std::printf("  %-6s keys=%zu  median=%.1f  dist: 0=%d 1=%d 2=%d 3+=%d  [bar (Arm W only): exactly 1]\n",
                    warm ? "Arm W" : "Arm C", sizes.size(), median, hist[0], hist[1], hist[2], hist[3]);
        return median;
    };
    std::printf("\n================ 2. GATE 2 — median candidate-set size, uncontested keys ================\n");
    double med_c = gate2(false);
    double med_w = gate2(true);
    bool bar1 = med_w == 1.0;
    std::printf("VERDICT bar1 (Arm W median == 1): %s\n", bar1 ? "PASS" : "FAIL — pass 2 stays cold; warm pass 1 only");

    // ── 3. Byte-exactness under Arm W ──────────────────────────────────────────
    int be_ok = 0, be_tot = 0;
    for (auto& dc : out)
        for (auto& kv : dc.w.key_candidates)
            for (auto& cc : kv.second) {
                be_tot++;
                if (dc.document.find(cc.value) != std::string::npos) be_ok++;
            }
    std::printf("\n================ 3. BYTE-EXACTNESS — Arm W ================\n");
    std::printf("%d/%d candidates are a byte-exact slice of their document (%.0f%%)  [bar: 100%%]\n",
                be_ok, be_tot, be_tot ? 100.0 * be_ok / be_tot : 0.0);
    bool bar2 = be_tot > 0 && be_ok == be_tot;
    std::printf("VERDICT bar2: %s\n", bar2 ? "PASS"
                : "FAIL — a restored prefix produced spans that fail to resolve; pass 2 stays cold");

    // ── 4. Wall-clock per document ──────────────────────────────────────────
    double c_pre = 0, c_dec = 0, w_pre = 0, w_dec = 0, w_prime = 0;
    for (auto& dc : out) {
        c_pre += dc.c_prefill_ms; c_dec += dc.c_decode_ms;
        w_pre += dc.w_prefill_ms; w_dec += dc.w_decode_ms; w_prime += dc.w_prime_ms;
    }
    int n = (int)out.size();
    std::printf("\n================ 4. WALL-CLOCK per document (n=%d) ================\n", n);
    std::printf("Arm C  prefill %.1fms  decode %.1fms  total %.1fms\n",
                c_pre / n, c_dec / n, (c_pre + c_dec) / n);
    std::printf("Arm W  prefill %.1fms  decode %.1fms  total %.1fms  [suffix-only prefill; excludes\n",
                w_pre / n, w_dec / n, (w_pre + w_dec) / n);
    std::printf("       the %.1fms/doc document-priming step used to SIMULATE a restored prefix\n", w_prime / n);
    std::printf("       in-process — a real snapshot restore would replace that recompute with a\n");
    std::printf("       fast memcpy, not eliminate the cost the way excluding it here does]\n");
    bool bar3 = (w_pre + w_dec) < (c_pre + c_dec);
    std::printf("VERDICT bar3 (Arm W faster than Arm C, prime excluded): %s  (W %.1fms vs C %.1fms)\n",
                bar3 ? "PASS" : "FAIL — no reason to change a path for nothing",
                (w_pre + w_dec) / n, (c_pre + c_dec) / n);

    std::printf("\n================ SUMMARY ================\n");
    std::printf("bar1 Arm W gate-2 median == 1:        %s (%.1f)\n", bar1 ? "PASS" : "FAIL", med_w);
    std::printf("bar2 Arm W byte-exactness == 100%%:     %s (%.0f%%)\n",
                bar2 ? "PASS" : "FAIL", be_tot ? 100.0 * be_ok / be_tot : 0.0);
    std::printf("bar3 Arm W faster than Arm C:          %s\n", bar3 ? "PASS" : "FAIL");
    std::printf("(Arm C median for reference: %.1f)   producer failures: Arm C=%d  Arm W=%d\n",
                med_c, n_unparseable_c, n_unparseable_w);

    return (bar1 && bar2 && bar3) ? 0 : 1;
}

int main() {
    // OCRDUMP — offline fixture dump for the OCR-lens probe step 2a
    // (docs/plan-ocr-lens.md). No model load: writes each qdocs_messy_corpus()
    // entry's raw .document to /tmp/ocr_probe/<tag>.txt and exits. The
    // directory must already exist (mkdir -p /tmp/ocr_probe before running).
    if (std::getenv("OCRDUMP")) {
        auto corpus = qdocs_messy_corpus();
        for (const QMessy& d : corpus) {
            std::string dpath = "/tmp/ocr_probe/" + d.tag + ".txt";
            FILE* f = std::fopen(dpath.c_str(), "wb");
            if (!f) {
                std::fprintf(stderr, "OCRDUMP: expected %s to open for write, "
                                     "actual fopen failure (mkdir -p /tmp/ocr_probe first)\n",
                             dpath.c_str());
                return 1;
            }
            std::fwrite(d.document.data(), 1, d.document.size(), f);
            std::fclose(f);
            std::printf("OCRDUMP: wrote %s (%zu bytes)\n", dpath.c_str(), d.document.size());
        }
        return 0;
    }

    const char* env = std::getenv("QWEN36_MODEL_PATH");
    std::string path = env ? env : "models/Qwen3.6-35B-A3B-MTP-UD-Q2_K_XL.gguf";
    const bool selftest = std::getenv("ATTN_TAP_SELFTEST") != nullptr;
    // 2048 for the short-prompt probes; leg D needs ≥4K + generation margin.
    // QDOCS_S1 also takes the margin: free decode has no accepting state to
    // close on, so a run can spend its whole 400-token budget before EOS.
    // SS2 threads target up to 8K prompt tokens (the workload-envelope ceiling,
    // CLAUDE.md) plus a 380-token grammar-decode margin.
    // KV *capacity* only — decode uses exact n_kv, so prior paths are byte-inert.
    const uint32_t CTX = (std::getenv("LOCPERF") || std::getenv("LOCSPLIT") || std::getenv("LOCWARM") || std::getenv("VERDICT2") || std::getenv("VERDICTGATE") || std::getenv("PREFPROF") || std::getenv("ABSBENCH") || std::getenv("COMPARE2") || std::getenv("COMPAREGATE") || std::getenv("PLANCOST") || std::getenv("SCHEDMEM")) ? 11264
                        : (std::getenv("SS2") || std::getenv("SS3")) ? 9216
                        : std::getenv("WARMPERF") ? 9216
                        : (std::getenv("QDOCS_D") || std::getenv("QDOCS_S1") || std::getenv("CAND") ||
                           std::getenv("QKEY") || std::getenv("WARM1") || std::getenv("WARM2") ||
                           std::getenv("INJHARD") || std::getenv("SEARCHHEAD") || std::getenv("BUNDLEA"))
                            ? 5120 : 2048;
    const int TOL = 2;

    apply_frozen_head_overrides();
    register_builtin_models();
    std::cerr << "Loading " << path << " ...\n";
    Model model;
    model.load_metadata(path);
    model.load_tensors();
    const auto& meta = model.get_metadata();
    auto fp = create_forward_pass(model, &meta, CTX, 1);
    ggml_backend_sched_t sched = model.get_scheduler();
    Tokenizer* tok = model.get_tokenizer();

    // ── Discover attention layers from the BUILT DECODE GRAPH ────────────────
    // Was: `meta.raw_kv.get_uint32("qwen35moe.full_attention_interval")`, a key
    // only a qwen35moe GGUF carries — so this probe could not even load any
    // other architecture, and was structurally incapable of asking whether the
    // lens constants transfer. Same defect, same fix as the P1 gate
    // (tests/unit/test_forward_pass_base.cpp): the seam is the TENSOR NAME
    // `kq_soft.<il>` that layers/attention.cpp assigns inside build_attn_mha,
    // the single funnel every attention builder passes through. Scanning for it
    // needs no per-family knowledge and automatically excludes blocks held out
    // of the decode stack (a qwen35 GGUF's trailing NextN/MTP head builds no
    // nodes). On qwen36 this yields exactly the old fai-derived list.
    std::vector<int32_t> attn_layers;
    {
        std::vector<int32_t> warm = tok->encode("Hello");
        if (warm.empty()) {
            std::fprintf(stderr, "tap discovery: expected a non-empty warm-up "
                                 "tokenization, actual 0 tokens\n");
            return 1;
        }
        fp->clear_slot(0);
        fp->set_cache_pos(0, 0);
        fp->run_prefill(warm, 0, 0, sched);
        std::vector<int32_t>  t = {warm.back()};
        std::vector<uint32_t> s = {0};
        std::vector<int32_t>  p = {(int32_t)fp->get_cache_pos(0)};
        ggml_cgraph* gscan = fp->build_decoding_graph(t, s, p);
        for (uint32_t il = 0; il < meta.block_count; ++il) {
            const std::string nm = "kq_soft." + std::to_string(il);
            if (ggml_graph_get_tensor(gscan, nm.c_str())) attn_layers.push_back((int32_t)il);
        }
        fp->clear_slot(0);
        fp->set_cache_pos(0, 0);
    }
    if (attn_layers.empty()) {
        std::fprintf(stderr, "tap discovery: expected ≥1 `kq_soft.<il>` tensor in "
                             "the decode graph, actual 0 (arch '%s' does not "
                             "materialize attention and cannot host the lens tap)\n",
                     meta.architecture.c_str());
        return 1;
    }
    g_attn_layers = &attn_layers;
    g_arch = meta.architecture;
    g_meta = &meta;
    // Honour the model's own add_bos_token contract, as cli/complete.cpp and
    // cli/session_mode.cpp do before prefill. A Gemma -it model without a
    // leading BOS degenerates (repeats a single token), so every Gemma number
    // measured without this was taken on a broken state. Qwen GGUFs carry
    // add_bos_token=false, so g_bos_text stays empty and the qwen legs are
    // byte-identical.
    if (meta.add_bos_token && meta.bos_token_id >= 0) {
        g_bos_text = tok->decode({(int32_t)meta.bos_token_id});
        std::printf("prompt BOS: add_bos_token=true id=%d text=\"%s\" (%zu bytes)\n",
                    meta.bos_token_id, g_bos_text.c_str(), g_bos_text.size());
        if (g_bos_text.empty()) {
            std::fprintf(stderr, "prompt BOS: expected a non-empty decoding for "
                                 "bos_token_id %d, actual empty string — the "
                                 "text-level BOS scheme cannot represent it\n",
                         meta.bos_token_id);
            return 1;
        }
    }

    // Validate the slot overrides against the model actually loaded: a stale
    // ATTN_FROZEN_SLOT from a deeper model would otherwise index past the tap
    // vector and read garbage that still looks like a probability row.
    for (auto& sv : {std::make_pair("ATTN_FROZEN_SLOT/ATTN_COV_SLOT citation", FROZEN_SLOT),
                     std::make_pair("ATTN_COV_SLOT coverage", L11_SLOT)}) {
        if (sv.second < 0 || sv.second >= (int)attn_layers.size()) {
            std::fprintf(stderr, "%s: expected a tap slot in [0,%zu) for arch '%s' "
                                 "(%zu attention layers), actual %d\n",
                         sv.first, attn_layers.size(), meta.architecture.c_str(),
                         attn_layers.size(), sv.second);
            return 1;
        }
    }

    std::printf("\nmodel map: arch=%s block_count=%u\n",
                meta.architecture.c_str(), meta.block_count);
    std::printf("attention layers (%zu): ", attn_layers.size());
    for (int il : attn_layers) std::printf("%d ", il);
    std::printf("\nn_head_q=%u n_head_kv=%u\n\n",
                meta.attention_head_count, meta.attention_head_count_kv);

    // N3b — the ungrounded-value alarm (sibling probe, own prompts). Leaves the
    // A/B/C path below untouched.
    if (std::getenv("ATTN_UNGROUNDED"))
        return run_ungrounded_probe(fp.get(), sched, tok, meta, attn_layers);

    // CG1 — the confidence gap (top1-top2), reusing N3b's labeled prompts.
    if (std::getenv("CONF_GAP"))
        return run_confgap_probe(fp.get(), sched, tok, meta, attn_layers);

    // DP1 — the retrieval head as a speculative draft pointer (vs shipped PLD).
    if (std::getenv("DRAFT_POINTER"))
        return run_draft_pointer_probe(fp.get(), sched, tok, meta, attn_layers);

    // COV1 — coverage: does zero attention mass reveal a SKIPPED prompt span?
    if (std::getenv("COVERAGE"))
        return run_coverage_probe(fp.get(), sched, tok, meta, attn_layers);

    // CF1 — conflict flag: does bimodal attention mass detect ≥2 candidate sources?
    if (std::getenv("CONFLICT_FLAG"))
        return run_conflict_probe(fp.get(), sched, tok, meta, attn_layers);

    // SS1 — stale-source alarm: do citations+coverage transfer to multi-turn threads?
    if (std::getenv("STALE_SOURCE"))
        return run_stale_probe(fp.get(), sched, tok, meta, attn_layers);

    // LENS — data generator for the Attention Lens HTML demo (not a probe).
    if (std::getenv("LENS"))
        return run_lens_gen(fp.get(), sched, tok, meta, attn_layers);

    // Qemmi-Docs P0 — leg A: fixed KV grammar × attention tap sanity (the gate).
    if (std::getenv("QDOCS_A"))
        return run_qdocs_leg_a(fp.get(), sched, tok, meta, attn_layers);
    // Qemmi-Docs P0 — leg B: key-name stability (2 arms × 12 EN+DE docs).
    if (std::getenv("QDOCS_B"))
        return run_qdocs_leg_b(fp.get(), sched, tok, meta, attn_layers);
    // Qemmi-Docs P0 — leg C: messy-corpus robustness (frozen signals, 15 docs).
    if (std::getenv("QDOCS_C"))
        return run_qdocs_leg_c(fp.get(), sched, tok, meta, attn_layers);
    // Leg C's corpus, but SEARCHING the citation head instead of freezing one.
    if (std::getenv("LEGCSEARCH"))
        return run_legc_head_search(fp.get(), sched, tok, meta, attn_layers);
    // The same corpus, asking whether ANY head retrieves from a KEY token —
    // /v1/locate's regime (../qemmi-lens/docs/plan-locate-and-cut.md §11a).
    if (std::getenv("LOCHEAD"))
        return run_locate_head_search(fp.get(), sched, tok, meta, attn_layers);
    // INJHEAD — does any head see a document that talks to the model?
    if (std::getenv("INJHEAD"))
        return run_injection_head_search(fp.get(), sched, tok, meta, attn_layers);
    // INJHARD — INJHEAD's confirmation leg: long docs, polite injections, about-AI lures.
    if (std::getenv("INJHARD"))
        return run_injection_hard(fp.get(), sched, tok, meta, attn_layers);
    // SEARCHHEAD — which chunk answers a question, in one prompt and across prompts.
    if (std::getenv("SEARCHHEAD"))
        return run_search_head_search(fp.get(), sched, tok, meta, attn_layers);
    // COMPAREHEAD — two documents in one prompt: align, omission, addition.
    if (std::getenv("COMPAREHEAD"))
        return run_compare_head_search(fp.get(), sched, tok, meta, attn_layers);
    // COMPAREHARD — COMPAREHEAD with anchors stripped, near-twins, sentence drops.
    if (std::getenv("COMPAREHARD"))
        return run_compare_hard(fp.get(), sched, tok, meta, attn_layers);
    // BINDHEAD — this item's value, not the neighbour's.
    if (std::getenv("BINDHEAD"))
        return run_bind_head_search(fp.get(), sched, tok, meta, attn_layers);
    // REDACTHEAD — mark every piece of personal data (open-set).
    if (std::getenv("REDACTHEAD"))
        return run_redact_head_search(fp.get(), sched, tok, meta, attn_layers);
    // REQHEAD — requirements checklist against a CV.
    if (std::getenv("REQHEAD"))
        return run_req_head_search(fp.get(), sched, tok, meta, attn_layers);
    // BUNDLEA — head sets vs one head; asking across languages (search, bind, req, compare).
    if (std::getenv("BUNDLEA"))
        return run_bundle_a(fp.get(), sched, tok, meta, attn_layers);
    // LOCPERF — baseline cost of today's /v1/locate by document length (LOCPERF_TOKENS).
    if (std::getenv("LOCPERF"))
        return run_locperf(fp.get(), sched, tok, meta, CTX);
    // LOCSPLIT — drift gate: one-shot vs split vs split+flash locate prefill.
    if (std::getenv("LOCSPLIT"))
        return run_locsplit(fp.get(), sched, tok, meta, CTX);
    // BUNDLEB — the one-token verdict vs attention's blind spots (+ logit lens, receipt).
    if (std::getenv("BUNDLEB"))
        return run_bundle_b(fp.get(), sched, tok, meta);
    // LOCWARM — the kept document (document_id): warm == cold, depth, speed.
    if (std::getenv("LOCWARM"))
        return run_locwarm(fp.get(), sched, tok, meta, CTX);
    // EXTWARM — is /v1/extract's shipped warm path warm == cold on a hybrid?
    if (std::getenv("EXTWARM"))
        return run_extwarm(fp.get(), sched, tok, meta, CTX);
    // VERDICT2 — the verdict before a route: instruction, real CVs, length, depth.
    if (std::getenv("VERDICT2"))
        return run_verdict2(fp.get(), sched, tok, meta, CTX);
    // LENSDUMP — every shipped lens report, for a before/after diff (plan-lens-verdict G1).
    if (std::getenv("LENSDUMP"))
        return run_lensdump(fp.get(), sched, tok, meta, CTX);
    // VERDICTGATE — the shipped /v1/verdict driver, gates G2-G4 (plan-lens-verdict).
    if (std::getenv("VERDICTGATE"))
        return run_verdictgate(fp.get(), sched, tok, meta, CTX);
    // PREFPROF — full-depth prefill: speed, splits, time per op.
    if (std::getenv("PREFPROF"))
        return run_prefprof(fp.get(), sched, tok, meta, CTX);
    // ABSBENCH — the absent head on AbsenceBench (step 7).
    if (std::getenv("ABSBENCH"))
        return run_absbench(fp.get(), sched, tok, meta, CTX);
    // COMPARE2 — the gate before a served "compare" mode.
    if (std::getenv("COMPARE2"))
        return run_compare2(fp.get(), sched, tok, meta, CTX);
    // COMPAREGATE — the shipped /v1/compare driver, gates G2-G4 (plan-lens-compare).
    if (std::getenv("COMPAREGATE"))
        return run_comparegate(fp.get(), sched, tok, meta, CTX);
    // COMPARE3 — the compare baseline when most units are missing.
    if (std::getenv("COMPARE3"))
        return run_compare3(fp.get(), sched, tok, meta, CTX);
    // COREF — probe D, coreference: the reference's own row onto earlier mentions.
    if (std::getenv("COREF"))
        return run_coref(fp.get(), sched, tok, attn_layers);
    // SPLIT — probe D, document boundaries: does the next line look back?
    if (std::getenv("SPLIT"))
        return run_split(fp.get(), sched, tok, attn_layers);
    // SURPRISE — probe D, per-word surprisal from the prefill's own logits.
    if (std::getenv("SURPRISE"))
        return run_surprise(fp.get(), sched, tok);
    // TOTALCHECK — probe D narrow mode: does an invoice's arithmetic look wrong?
    if (std::getenv("TOTALCHECK"))
        return run_totalcheck(fp.get(), sched, tok);
    // PLANCOST — what alloc_readback_graph costs per tapped pass.
    if (std::getenv("PLANCOST"))
        return run_plancost(fp.get(), sched);
    // SCHEDMEM — GPU memory of the dedicated locate scheduler vs one merged scheduler.
    if (std::getenv("SCHEDMEM"))
        return run_schedmem(fp.get(), tok, meta, CTX, model.get_backend_metal(), model.get_backend_cpu());
    // LOCABSENT — the absence threshold for span-only: does the calibrated
    // locate head know when a key is NOT in the document?
    if (std::getenv("LOCABSENT"))
        return run_locate_absence(fp.get(), sched, tok, meta, attn_layers);
    // DECIDEHEAD — is the LOCATE pair the right head for a DECISION? Sweeps
    // every (layer, head) x instruction shape x score variant on two tasks.
    if (std::getenv("DECIDEHEAD"))
        return run_decide_head_search(fp.get(), sched, tok, meta, attn_layers);
    // ABSENTHEAD — the same question for the yes/no job: is the LOCATE pair the
    // right head for ABSENCE? LOCABSENT's 0.927 was read off it.
    if (std::getenv("ABSENTHEAD"))
        return run_absent_head_search(fp.get(), sched, tok, meta, attn_layers);
    // SCOREHEAD — the ordinal job. Unlike its two siblings this leg is not
    // looking for a bigger number: DECIDEHEAD already found 87.5% and could
    // not reproduce it by selecting twice. It ranks heads by ordinal
    // concordance over a fractional score and holds out on TWO axes.
    if (std::getenv("SCOREHEAD"))
        return run_score_head_search(fp.get(), sched, tok, meta, attn_layers);
    // Leg C's corpus again, asking whether its LABELS are causally true.
    if (std::getenv("OMISSION1"))
        return run_omission1(fp.get(), sched, tok, meta, attn_layers);
    // The same layers, re-scored against OMISSION1's causal labels.
    if (std::getenv("COVCAUSAL"))
        return run_covcausal(fp.get(), sched, tok, meta, attn_layers);
    // OCR-lens Arm T (docs/plan-ocr-lens.md): leg C cloned onto pdftotext
    // round-tripped documents instead of QMessy.document. Same CTX group as
    // QDOCS_C (unlisted below ⇒ 2048).
    // OCR-lens Arm O (same doc, step 2): identical scoring code, fixture
    // suffix switched to Vision-OCR text via OCR_SUFFIX/".ocr.txt" inside
    // run_ocr_t_probe. Same CTX group as OCRT (unlisted below ⇒ 2048).
    if (std::getenv("OCRT") || std::getenv("OCRO"))
        return run_ocr_t_probe(fp.get(), sched, tok, meta, attn_layers);
    // Norm-weighted attention calibration (docs/note-lens-norm-weighted-metric.md):
    // Metric A (raw alpha) vs Metric B (alpha*||V||) on citation (Leg C corpus)
    // and coverage separation (COV1 corpus), paired, same pass.
    if (std::getenv("NORM_WEIGHTED"))
        return run_norm_weighted_probe(fp.get(), sched, tok, meta, attn_layers);
    // GEMMA4 SEARCH — all (layer,head) candidates scored on the Leg C messy
    // corpus directly, Metric A vs Metric B, gemma4-only (the caches this
    // reads have no Qwen equivalent). docs/note-lens-gemma-norm-weighted.md.
    if (std::getenv("GEMMA4_SEARCH_DUAL"))
        return run_gemma4_search_dual(fp.get(), sched, tok, meta, attn_layers);
    // HEAD AGGREGATION PROBE -- parameter-free max/mean aggregation over
    // heads (per-layer full curve + global), Metric A shape, architecture-
    // agnostic (Gemma 4 and Qwen both). One-off probe, not in any doc yet.
    // MLXCMP -- cross-runtime head-survival dump (ggml reference + teacher-
    // forcing payload for the MLX leg).
    if (std::getenv("MLXCMP"))
        return run_mlx_compare_dump(fp.get(), sched, tok, meta, attn_layers);
    if (std::getenv("ATTN_HEAD_AGG"))
        return run_head_aggregation_probe(fp.get(), sched, tok, meta, attn_layers);
    // COVSEARCH -- coverage layer x threshold search (docs/plan-coverage-layer-
    // search.md). Re-runs the incumbent's selection with an independent
    // evaluation corpus, AUC instead of calibration accuracy, and a plateau
    // requirement. Probe only: moves no constant.
    if (std::getenv("COVSEARCH"))
        return run_coverage_layer_search(fp.get(), sched, tok, meta, attn_layers);
    // BANDDRIFT — the "requirement" half of decision stability (see the leg).
    if (std::getenv("BANDDRIFT"))
        return run_band_drift_probe(fp.get(), sched, tok, meta, attn_layers);

    // MOEROUTE — which mechanism makes an MoE irreproducible (see the leg).
    if (std::getenv("MOEROUTE"))
        return run_moe_route_probe(fp.get(), sched, tok, meta);
    // PINREPLAY — does pinning the selection collapse the drift (see the leg).
    if (std::getenv("PINREPLAY"))
        return run_pin_replay_probe(fp.get(), sched, tok, meta);
    // COVCOMBINE — multi-layer vote vs the best single layer (see the leg).
    if (std::getenv("COVCOMBINE"))
        return run_coverage_combiner(fp.get(), sched, tok, meta, attn_layers);
    // Qemmi-Docs P0 — leg D: context length (1K/2K/4K buckets, real token counts).
    if (std::getenv("QDOCS_D"))
        return run_qdocs_leg_d(fp.get(), sched, tok, meta, attn_layers);
    // Stage 1 gate — the trust layer over FREE-FORM output, on the shipped lens
    // math (docs/handoff-nogrammar-stages.md §S1.2). Gates the grammar removal.
    if (std::getenv("QDOCS_S1"))
        return run_qdocs_s1(fp.get(), sched, tok, meta, CTX);

    // CAND — candidate-set cheap-kill gate (docs/plan-candidate-set.md), tested
    // BEFORE any v4/key_candidates format or endpoint work. Cold two-pass: pass
    // 1 is the unchanged free extraction, pass 2 is a separate cold inference,
    // taps disarmed, asking for every span that answers each hinted key.
    // WARMPERF — the speed question WARM2 left unanswered (its timers disagreed).
    if (std::getenv("WARMPERF"))
        return run_warmperf_probe(fp.get(), sched, tok, CTX);

    if (std::getenv("CAND"))
        return run_cand_probe(fp.get(), sched, tok, meta, CTX);

    // QKEY — question-key probe (docs/plan-question-keys.md §4): matched-pairs
    // Arm K (identifier keys, control) vs Arm Q (question keys), same corpus,
    // same taps, same calibrated head, same constants, same greedy decode.
    if (std::getenv("QKEY"))
        return run_qkey_probe(fp.get(), sched, tok, meta, CTX);

    // WARM1/WARM2 — docs/plan-lens-warm-document.md probes (harness-only,
    // measurement only, no server/engine changes). WARM1 is the priority
    // (pass-1 split-prefill gates); WARM2 extends CAND's pass 2.
    if (std::getenv("WARM1"))
        return run_warm1_probe(fp.get(), sched, tok, meta, CTX);
    if (std::getenv("WARM2"))
        return run_warm2_probe(fp.get(), sched, tok, meta, CTX);

    // SS2 — coverage-free stale-source alarm on grammar-constrained email
    // threads at 4K-8K tokens (supersedes SS1's inconclusive short-context
    // composition). docs/note-ss2-thread-alarm.md.
    if (std::getenv("SS2"))
        return run_ss2(fp.get(), sched, tok, meta, attn_layers, ss2_thread_defs(), "SS2");

    // SS3 — Gate 2 power-up: six matched pairs (explicit vs indirect correction,
    // everything else held constant) that test SS2's one hypothesis and give
    // recall a denominator. docs/note-ss2-thread-alarm.md §2 Gate 1.
    if (std::getenv("SS3"))
        return run_ss2(fp.get(), sched, tok, meta, attn_layers, ss3_thread_defs(), "SS3");

    // ── Prompt A (calibration) ───────────────────────────────────────────────
    std::string promptA =
        "From: orders@acme-corp.example\n"
        "Subject: Purchase Order\n\n"
        "Hello,\n\n"
        "Please process the following order for customer Acme Corporation.\n"
        "Order date: 2026-03-14.\n"
        "We need a quantity of 240 units.\n"
        "The unit price is 12.50 USD.\n"
        "The order total comes to 3000.00 USD.\n\n"
        "Thanks.\n\n"
        "Extract the order as JSON with keys customer, date, quantity, unit_price, total:\n";
    std::string compA =
        "{\"customer\": \"Acme Corporation\", \"date\": \"2026-03-14\", "
        "\"quantity\": 240, \"unit_price\": 12.50, \"total\": 3000.00}";
    std::vector<Field> fieldsA = {
        {"customer",   "Acme Corporation", -1, -1},
        {"date",       "2026-03-14",       -1, -1},
        {"quantity",   "240",              -1, -1},
        {"unit_price", "12.50",            -1, -1},
        {"total",      "3000.00",          -1, -1},
    };

    // ── Prompt B (held-out, same shape) ──────────────────────────────────────
    std::string promptB =
        "From: purchasing@globex.example\n"
        "Subject: New Order\n\n"
        "Hi team,\n\n"
        "Kindly arrange an order for customer Globex Industries.\n"
        "Order date: 2025-11-02.\n"
        "We require a quantity of 875 units.\n"
        "The unit price is 47.30 EUR.\n"
        "The order total comes to 41387.50 EUR.\n\n"
        "Regards.\n\n"
        "Extract the order as JSON with keys customer, date, quantity, unit_price, total:\n";
    std::string compB =
        "{\"customer\": \"Globex Industries\", \"date\": \"2025-11-02\", "
        "\"quantity\": 875, \"unit_price\": 47.30, \"total\": 41387.50}";
    std::vector<Field> fieldsB = {
        {"customer",   "Globex Industries", -1, -1},
        {"date",       "2025-11-02",        -1, -1},
        {"quantity",   "875",               -1, -1},
        {"unit_price", "47.30",             -1, -1},
        {"total",      "41387.50",          -1, -1},
    };

    // ── Self-test path: tap sanity, then exit ────────────────────────────────
    if (selftest) {
        std::printf("=== TAP SELF-TEST (2 steps) ===\n");
        run_prompt(fp.get(), sched, tok, meta, "A", promptA, compA, fieldsA, true);
        std::printf("[selftest] OK if dims=[n_kv,1,%u,1] and every head sum≈1.0\n",
                    meta.attention_head_count);
        return 0;
    }

    // ── Run A, select best (layer,head) ──────────────────────────────────────
    PromptRun A = run_prompt(fp.get(), sched, tok, meta, "A", promptA, compA, fieldsA, false);

    auto report_fields = [&](const PromptRun& R) {
        std::printf("[%s] prompt_tokens=%zu comp_tokens=%zu\n",
                    R.label.c_str(), R.prompt_tokens.size(), R.comp_tokens.size());
        for (auto& f : R.fields)
            std::printf("    field %-11s value=\"%s\"  prompt span [%d..%d]  ctx: %s\n",
                        f.name.c_str(), f.value.c_str(), f.lo, f.hi,
                        ctx_around(tok, R.prompt_tokens, f.lo, 3).c_str());
        // count value tokens
        int nv = 0; for (int v = 1; v < (int)R.comp_tokens.size(); ++v)
            if (R.comp_field[v] >= 0) nv++;
        int agree = 0; for (int v = 1; v < (int)R.comp_tokens.size(); ++v)
            if (R.comp_field[v] >= 0 && v - 1 < (int)R.greedy_pred.size()
                && R.greedy_pred[v - 1] == R.comp_tokens[v]) agree++;
        std::printf("    value tokens scored: %d   greedy-agreement on them: %d/%d\n",
                    nv, agree, nv);
    };

    std::printf("\n================ PROMPT A (calibration) ================\n");
    report_fields(A);

    // Per-layer: best head + head-mean top1 fraction.
    std::printf("\n  layer | best_head  top1/N  top3/N | head-MEAN top1  bos_mass\n");
    std::printf("  ------+-------------------------------+--------------------------\n");
    int    best_ls = -1, best_h = -1;
    double best_frac = -1; int best_top3 = -1;
    for (int ls = 0; ls < (int)attn_layers.size(); ++ls) {
        int    lbest_h = -1; double lbest_frac = -1; int lbest_t1 = 0, lbest_t3 = 0, lbest_n = 0;
        double mean_t1 = 0, mean_bos = 0;
        for (int h = 0; h < A.n_head; ++h) {
            Score sc = score_lh(A, ls, h, TOL);
            double frac = sc.n ? (double)sc.top1 / sc.n : 0;
            mean_t1  += frac;
            mean_bos += sc.n ? sc.bos_mass / sc.n : 0;
            if (frac > lbest_frac) { lbest_frac = frac; lbest_h = h;
                                     lbest_t1 = sc.top1; lbest_t3 = sc.top3; lbest_n = sc.n; }
            // global best: prefer top1 fraction, tie-break top3
            if (frac > best_frac ||
                (frac == best_frac && sc.top3 > best_top3)) {
                best_frac = frac; best_top3 = sc.top3; best_ls = ls; best_h = h;
            }
        }
        mean_t1 /= A.n_head; mean_bos /= A.n_head;
        std::printf("  %5d | h=%-2d      %2d/%-2d   %2d/%-2d  |   %.2f          %.3f\n",
                    attn_layers[ls], lbest_h, lbest_t1, lbest_n, lbest_t3, lbest_n,
                    mean_t1, mean_bos);
    }

    // ── Full ranked (layer,head) table ───────────────────────────────────────
    // The per-layer summary above shows only each layer's winner, which hides
    // the shape of the field: whether ONE head stands out (a retrieval head) or
    // the top of the ranking is a flat crowd of near-ties (no head, just noise
    // with a lucky argmax). That distinction is the whole go/no-go question when
    // asking whether the lens constants transfer to another model, so print the
    // ranking itself rather than its argmax.
    {
        struct Cand { int layer, head, top1, top3, n; double frac, bos; };
        std::vector<Cand> cands;
        for (int ls = 0; ls < (int)attn_layers.size(); ++ls)
            for (int h = 0; h < A.n_head; ++h) {
                Score sc = score_lh(A, ls, h, TOL);
                cands.push_back({attn_layers[ls], h, sc.top1, sc.top3, sc.n,
                                 sc.n ? (double)sc.top1 / sc.n : 0.0,
                                 sc.n ? sc.bos_mass / sc.n : 0.0});
            }
        std::sort(cands.begin(), cands.end(), [](const Cand& a, const Cand& b) {
            if (a.frac != b.frac) return a.frac > b.frac;
            return a.top3 > b.top3;
        });
        const int SHOW = 20;
        std::printf("\n  === RANKED (layer,head) on A — top %d of %zu candidates ===\n",
                    SHOW, cands.size());
        std::printf("  rank | layer head | top1/N  (in-span)  top3/N | bos_mass\n");
        std::printf("  -----+------------+--------------------------+---------\n");
        for (int i = 0; i < SHOW && i < (int)cands.size(); ++i) {
            const Cand& c = cands[i];
            std::printf("  %4d | L%-4d H%-3d | %2d/%-2d   (%5.1f%%)   %2d/%-2d | %.3f\n",
                        i + 1, c.layer, c.head, c.top1, c.n, 100.0 * c.frac,
                        c.top3, c.n, c.bos);
        }
        // The Qwen 3.6 frozen coordinates, scored HERE as a control — on the
        // pinned model this must be at/near the top; on any other model it is
        // the direct measurement of whether the shipped constants transfer.
        for (int ls = 0; ls < (int)attn_layers.size(); ++ls) {
            if (attn_layers[ls] != 3) continue;
            if (13 >= A.n_head) break;
            Score sc = score_lh(A, ls, 13, TOL);
            int rank = 1;
            for (const Cand& c : cands)
                if (c.frac > (sc.n ? (double)sc.top1 / sc.n : 0.0)) rank++;
            std::printf("  CONTROL L3H13 (the shipped LensConstants coordinates): "
                        "top1 %d/%d (%.1f%%), top3 %d/%d — rank %d of %zu\n",
                        sc.top1, sc.n, sc.n ? 100.0 * sc.top1 / sc.n : 0.0,
                        sc.top3, sc.n, rank, cands.size());
        }
    }

    Score bA = score_lh(A, best_ls, best_h, TOL);
    std::printf("\n  >>> SELECTED on A: layer %d, head %d  ->  top1 %d/%d (%.0f%%), top3 %d/%d (%.0f%%)\n",
                attn_layers[best_ls], best_h,
                bA.top1, bA.n, 100.0 * bA.top1 / bA.n,
                bA.top3, bA.n, 100.0 * bA.top3 / bA.n);

    // ── HELD-OUT MODE ────────────────────────────────────────────────────────
    // ATTN_FROZEN_SLOT/HEAD were added "so the confirmation legs can be pointed
    // at a candidate found on another model without editing the file"
    // (note-lens-qwen38-probe.md §2). This is that facility finished: with the
    // override set, A's own winner is still searched and printed above — it is
    // the diagnostic — but B and C are scored on the OVERRIDE instead.
    //
    // Whether A/B/C are genuinely held out for this head is a fact about where
    // the head came from, which this probe cannot see and must not assert. It
    // prints the coordinates it was handed and names the condition; the caller
    // owns the claim.
    if (std::getenv("ATTN_FROZEN_SLOT") || std::getenv("ATTN_FROZEN_HEAD")) {
        if (FROZEN_SLOT < 0 || FROZEN_SLOT >= (int)attn_layers.size())
            throw std::runtime_error(
                "ATTN_FROZEN_SLOT: expected a tap slot in [0," +
                std::to_string(attn_layers.size() - 1) + "], actual " + std::to_string(FROZEN_SLOT));
        if (FROZEN_HEAD < 0 || FROZEN_HEAD >= A.n_head)
            throw std::runtime_error(
                "ATTN_FROZEN_HEAD: expected a head in [0," + std::to_string(A.n_head - 1) +
                "], actual " + std::to_string(FROZEN_HEAD));
        best_ls = FROZEN_SLOT;
        best_h  = FROZEN_HEAD;
        Score oA = score_lh(A, best_ls, best_h, TOL);
        std::printf("\n  >>> HELD-OUT MODE: B and C below are scored on the OVERRIDE "
                    "L%dH%d, not on A's winner.\n"
                    "      A, B and C are held out for it ONLY if it was selected elsewhere "
                    "(the probe cannot know).\n"
                    "      For reference it scores top1 %d/%d (%.0f%%), top3 %d/%d on A.\n",
                    attn_layers[best_ls], best_h,
                    oA.top1, oA.n, oA.n ? 100.0 * oA.top1 / oA.n : 0.0, oA.top3, oA.n);
    }

    // ── Run B, frozen eval ───────────────────────────────────────────────────
    PromptRun B = run_prompt(fp.get(), sched, tok, meta, "B", promptB, compB, fieldsB, false);
    std::printf("\n================ PROMPT B (held-out, FROZEN layer %d head %d) ================\n",
                attn_layers[best_ls], best_h);
    report_fields(B);
    Score bB = score_lh(B, best_ls, best_h, TOL);
    std::printf("\n  FROZEN eval on B: top1 %d/%d (%.0f%%), top3 %d/%d (%.0f%%), bos_mass %.3f\n",
                bB.top1, bB.n, 100.0 * bB.top1 / bB.n,
                bB.top3, bB.n, 100.0 * bB.top3 / bB.n,
                bB.n ? bB.bos_mass / bB.n : 0);

    // Per-field breakdown on B for the frozen head.
    std::printf("\n  per-field (B, frozen head):\n");
    for (int fi = 0; fi < (int)B.fields.size(); ++fi) {
        int n = 0, t1 = 0, t3 = 0;
        for (int v = 1; v < (int)B.comp_tokens.size(); ++v) {
            if (B.comp_field[v] != fi) continue;
            int step = v - 1; if (step >= (int)B.rows.size()) break;
            auto tk = topk_head(B.rows[step][best_ls], best_h, B.n_kv_at_step[step], 3);
            const Field& f = B.fields[fi];
            auto in = [&](int p){ return p >= f.lo - TOL && p <= f.hi + TOL; };
            n++; if (!tk.empty() && in(tk[0].first)) t1++;
            for (auto& pr : tk) if (in(pr.first)) { t3++; break; }
        }
        std::printf("    %-11s span[%d..%d]  top1 %d/%d  top3 %d/%d\n",
                    B.fields[fi].name.c_str(), B.fields[fi].lo, B.fields[fi].hi, t1, n, t3, n);
    }

    // ── 3 verbatim eyeball examples (from B, frozen head) ────────────────────
    std::printf("\n  === eyeball (B, frozen layer %d head %d): value token -> top-3 attended ===\n",
                attn_layers[best_ls], best_h);
    std::vector<int32_t> seqB = B.prompt_tokens;
    seqB.insert(seqB.end(), B.comp_tokens.begin(), B.comp_tokens.end());
    int shown = 0;
    for (int v = 1; v < (int)B.comp_tokens.size() && shown < 3; ++v) {
        int fi = B.comp_field[v]; if (fi < 0) continue;
        int step = v - 1; if (step >= (int)B.rows.size()) break;
        // pick the FIRST value token of each of the first 3 fields
        if (fi != shown) continue;
        auto tk = topk_head(B.rows[step][best_ls], best_h, B.n_kv_at_step[step], 3);
        std::string vt = tok->decode(B.comp_tokens[v]);
        for (char& c : vt) if (c == '\n') c = ' ';
        std::printf("\n  value token «%s» (field %s, source span [%d..%d])\n",
                    vt.c_str(), B.fields[fi].name.c_str(), B.fields[fi].lo, B.fields[fi].hi);
        for (int r = 0; r < (int)tk.size(); ++r) {
            bool in = tk[r].first >= B.fields[fi].lo - TOL && tk[r].first <= B.fields[fi].hi + TOL;
            std::printf("    #%d pos %3d  mass %.3f  %s | %s\n",
                        r + 1, tk[r].first, tk[r].second, in ? "IN " : "out",
                        ctx_around(tok, seqB, tk[r].first, 3).c_str());
        }
        shown++;
    }

    // ── Prompt C (boundary): reformatted values + a DATE CONFLICT ────────────
    // Same frozen head. Tests two things the verbatim PASS can't: (1) does the
    // head still point at the source when the emitted value is REFORMATTED
    // (European→plain, thousands stripped) rather than a byte copy? (WEAK line)
    // (2) with two candidate dates in the prompt, is the date row bimodal over
    // both spans, or does it lock onto the one it emits? (stretch)
    std::string promptC =
        "From: sales@initech.example\n"
        "Subject: Order Confirmation\n\n"
        "Hi,\n\n"
        "Order for customer Initech LLC.\n"
        "Order date: 2024-06-09.\n"
        "Requested delivery date: 2024-07-20.\n"
        "Quantity: 1.250 units.\n"
        "Unit price: EUR 8,75.\n"
        "Order total: EUR 10.937,50.\n\n"
        "Best.\n\n"
        "Extract as JSON with keys customer, order_date, quantity, unit_price, total:\n";
    std::string compC =
        "{\"customer\": \"Initech LLC\", \"order_date\": \"2024-06-09\", "
        "\"quantity\": 1250, \"unit_price\": 8.75, \"total\": 10937.50}";
    std::vector<Field> fieldsC = {
        {"customer",   "Initech LLC", -1, -1, ""},          // verbatim control
        {"order_date", "2024-06-09",  -1, -1, ""},          // verbatim, but conflicted
        {"quantity",   "1.250",       -1, -1, "1250"},      // reformatted: 1.250 -> 1250
        {"unit_price", "8,75",        -1, -1, "8.75"},      // reformatted: 8,75 -> 8.75
        {"total",      "10.937,50",   -1, -1, "10937.50"},  // reformatted
    };

    PromptRun C = run_prompt(fp.get(), sched, tok, meta, "C", promptC, compC, fieldsC, false);
    std::printf("\n================ PROMPT C (boundary: reformatting + conflict, FROZEN L%d H%d) ================\n",
                attn_layers[best_ls], best_h);
    report_fields(C);
    Score bC = score_lh(C, best_ls, best_h, TOL);
    std::printf("\n  FROZEN eval on C: top1 %d/%d (%.0f%%), top3 %d/%d (%.0f%%)\n",
                bC.top1, bC.n, bC.n ? 100.0 * bC.top1 / bC.n : 0,
                bC.top3, bC.n, bC.n ? 100.0 * bC.top3 / bC.n : 0);
    std::printf("  per-field (C, frozen head) — verbatim vs reformatted:\n");
    for (int fi = 0; fi < (int)C.fields.size(); ++fi) {
        int n = 0, t1 = 0, t3 = 0, agree = 0;
        for (int v = 1; v < (int)C.comp_tokens.size(); ++v) {
            if (C.comp_field[v] != fi) continue;
            int step = v - 1; if (step >= (int)C.rows.size()) break;
            auto tk = topk_head(C.rows[step][best_ls], best_h, C.n_kv_at_step[step], 3);
            const Field& f = C.fields[fi];
            auto in = [&](int p){ return p >= f.lo - TOL && p <= f.hi + TOL; };
            n++; if (!tk.empty() && in(tk[0].first)) t1++;
            for (auto& pr : tk) if (in(pr.first)) { t3++; break; }
            if (C.greedy_pred[step] == C.comp_tokens[v]) agree++;
        }
        bool reform = !C.fields[fi].cvalue.empty();
        std::printf("    %-11s %-11s span[%d..%d]  top1 %d/%d  top3 %d/%d  greedy-agree %d/%d\n",
                    C.fields[fi].name.c_str(), reform ? "[REFORMAT]" : "[verbatim]",
                    C.fields[fi].lo, C.fields[fi].hi, t1, n, t3, n, agree, n);
    }

    // Conflict bimodality: the order_date token's mass over the TWO date spans.
    {
        int order_lo, order_hi, deliv_lo, deliv_hi;
        find_token_span(tok, C.prompt_tokens, promptC, "2024-06-09", order_lo, order_hi);
        find_token_span(tok, C.prompt_tokens, promptC, "2024-07-20", deliv_lo, deliv_hi);
        // first completion token of order_date
        int dv = -1, ofi = 1; // order_date is field index 1
        for (int v = 1; v < (int)C.comp_tokens.size(); ++v)
            if (C.comp_field[v] == ofi) { dv = v; break; }
        std::printf("\n  conflict readout: order_date span[%d..%d] vs delivery span[%d..%d]\n",
                    order_lo, order_hi, deliv_lo, deliv_hi);
        if (dv > 0) {
            int step = dv - 1;
            const std::vector<float>& row = C.rows[step][best_ls];
            int n_kv = C.n_kv_at_step[step];
            auto mass_in = [&](int lo, int hi){ double m = 0;
                for (int j = std::max(1, lo - TOL); j <= hi + TOL && j < n_kv; ++j)
                    m += row[(size_t)best_h * n_kv + j]; return m; };
            std::printf("    date token «%s»: mass on ORDER span = %.3f, on DELIVERY span = %.3f\n",
                        tok->decode(C.comp_tokens[dv]).c_str(),
                        mass_in(order_lo, order_hi), mass_in(deliv_lo, deliv_hi));
            auto tk = topk_head(row, best_h, n_kv, 5);
            std::vector<int32_t> seqC = C.prompt_tokens;
            seqC.insert(seqC.end(), C.comp_tokens.begin(), C.comp_tokens.end());
            for (int r = 0; r < (int)tk.size(); ++r)
                std::printf("      top%d pos %3d mass %.3f | %s\n", r + 1, tk[r].first,
                            tk[r].second, ctx_around(tok, seqC, tk[r].first, 3).c_str());
        }
    }

    // ── Verdict ──────────────────────────────────────────────────────────────
    double t1f = bB.n ? (double)bB.top1 / bB.n : 0;
    double t3f = bB.n ? (double)bB.top3 / bB.n : 0;
    std::printf("\n================ VERDICT ================\n");
    std::printf("  frozen top1=%.0f%% (PASS needs >=66.7%%), top3=%.0f%% (PASS needs >=80%%)\n",
                100 * t1f, 100 * t3f);
    if (t1f >= 2.0 / 3.0 && t3f >= 0.80) std::printf("  => PASS\n");
    else if (t3f >= 0.80)                std::printf("  => WEAK (top3 aligns, top1 does not)\n");
    else                                 std::printf("  => KILL / WEAK — see tables\n");
    return 0;
}
